INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0001', '34-sit-up', '3/4 Sit-up', '3/4 Sit-up', '3/4 Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', '3/4 Sit-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0001-2gPfomN.jpg', 'videos/0001-2gPfomN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0002', '45-side-bend', '45° Side Bend', '45° Side Bend', '45° Side Bendは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', '45° Side Bend is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0002-Hy9D21L.jpg', 'videos/0002-Hy9D21L.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0003', 'air-bike', 'Air Bike', 'Air Bike', 'Air Bikeは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Air Bike is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."]', 'images/0003-1ZFqTDN.jpg', 'videos/0003-1ZFqTDN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1512', 'all-fours-squad-stretch', 'All Fours Squad ストレッチ', 'All Fours Squad Stretch', 'All Fours Squad ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'All Fours Squad Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."]', 'images/1512-qBcKorM.jpg', 'videos/1512-qBcKorM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0006', 'alternate-heel-touchers', 'Alternate Heel Touchers', 'Alternate Heel Touchers', 'Alternate Heel Touchersは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Alternate Heel Touchers is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."]', 'images/0006-qaZVsGk.jpg', 'videos/0006-qaZVsGk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0007', 'alternate-lateral-pulldown', 'Alternate サイド プルダウン', 'Alternate Lateral Pulldown', 'Alternate サイド プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Alternate Lateral Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0007-4IKbhHV.jpg', 'videos/0007-4IKbhHV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1368', 'ankle-circles', 'アンクル Circles', 'Ankle Circles', 'アンクル Circlesは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Ankle Circles is an effective exercise targeting the ankle stabilizers using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."]', 'images/1368-uL9CsKm.jpg', 'videos/1368-uL9CsKm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3293', 'archer-pull-up', 'Archer Pull Up', 'Archer Pull Up', 'Archer Pull Upは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Archer Pull Up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."]', 'images/3293-72BC5Za.jpg', 'videos/3293-72BC5Za.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3294', 'archer-push-up', 'Archer Push Up', 'Archer Push Up', 'Archer Push Upは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Archer Push Up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]', 'images/3294-A9qxk2F.jpg', 'videos/3294-A9qxk2F.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2355', 'arm-slingers-hanging-bent-knee-legs', 'Arm Slingers Hanging Bent Knee Legs', 'Arm Slingers Hanging Bent Knee Legs', 'Arm Slingers Hanging Bent Knee Legsは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Arm Slingers Hanging Bent Knee Legs is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2355-uWpxD4v.jpg', 'videos/2355-uWpxD4v.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2333', 'arm-slingers-hanging-straight-legs', 'Arm Slingers Hanging Straight Legs', 'Arm Slingers Hanging Straight Legs', 'Arm Slingers Hanging Straight Legsは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Arm Slingers Hanging Straight Legs is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2333-PXTIwgu.jpg', 'videos/2333-PXTIwgu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3214', 'arms-apart-circular-toe-touch-male', 'Arms Apart Circular Toe Touch (male)', 'Arms Apart Circular Toe Touch (male)', 'Arms Apart Circular Toe Touch (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Arms Apart Circular Toe Touch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."]', 'images/3214-RtyAsy1.jpg', 'videos/3214-RtyAsy1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3204', 'arms-overhead-full-sit-up-male', 'Arms オーバーヘッド Full Sit-up (male)', 'Arms Overhead Full Sit-up (male)', 'Arms オーバーヘッド Full Sit-up (male)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Arms Overhead Full Sit-up (male) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3204-NAkmgdx.jpg', 'videos/3204-NAkmgdx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0009', 'assisted-chest-dip-kneeling', 'アシスト チェスト ディップス (ニーリング)', 'Assisted Chest Dip (kneeling)', 'アシスト チェスト ディップス (ニーリング)は、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Assisted Chest Dip (kneeling) is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0009-PAgTVaK.jpg', 'videos/0009-PAgTVaK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0011', 'assisted-hanging-knee-raise', 'アシスト Hanging Knee レイズ', 'Assisted Hanging Knee Raise', 'アシスト Hanging Knee レイズは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Hanging Knee Raise is an effective exercise targeting the hip flexors using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0011-03lzqwk.jpg', 'videos/0011-03lzqwk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0010', 'assisted-hanging-knee-raise-with-throw-down', 'アシスト Hanging Knee レイズ With Throw Down', 'Assisted Hanging Knee Raise With Throw Down', 'アシスト Hanging Knee レイズ With Throw Downは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Hanging Knee Raise With Throw Down is an effective exercise targeting the hip flexors using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]', 'images/0010-8K0w2yA.jpg', 'videos/0010-8K0w2yA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1708', 'assisted-lying-calves-stretch', 'アシスト ライイング カーフ ストレッチ', 'Assisted Lying Calves Stretch', 'アシスト ライイング カーフ ストレッチは、アシストマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Assisted Lying Calves Stretch is an effective exercise targeting the hamstrings using assisted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."]', 'images/1708-GxDwDX0.jpg', 'videos/1708-GxDwDX0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1709', 'assisted-lying-glutes-stretch', 'アシスト ライイング Glutes ストレッチ', 'Assisted Lying Glutes Stretch', 'アシスト ライイング Glutes ストレッチは、アシストマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Assisted Lying Glutes Stretch is an effective exercise targeting the hamstrings using assisted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', 'images/1709-yn0LjwL.jpg', 'videos/1709-yn0LjwL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1710', 'assisted-lying-gluteus-and-piriformis-stretch', 'アシスト ライイング Gluteus And Piriformis ストレッチ', 'Assisted Lying Gluteus And Piriformis Stretch', 'アシスト ライイング Gluteus And Piriformis ストレッチは、アシストマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Assisted Lying Gluteus And Piriformis Stretch is an effective exercise targeting the hamstrings using assisted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', 'images/1710-RQNVT10.jpg', 'videos/1710-RQNVT10.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0012', 'assisted-lying-leg-raise-with-lateral-throw-down', 'アシスト ライイング Leg レイズ With サイド Throw Down', 'Assisted Lying Leg Raise With Lateral Throw Down', 'アシスト ライイング Leg レイズ With サイド Throw Downは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Lying Leg Raise With Lateral Throw Down is an effective exercise targeting the hip flexors using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0012-UGhRD1A.jpg', 'videos/0012-UGhRD1A.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0013', 'assisted-lying-leg-raise-with-throw-down', 'アシスト ライイング Leg レイズ With Throw Down', 'Assisted Lying Leg Raise With Throw Down', 'アシスト ライイング Leg レイズ With Throw Downは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Lying Leg Raise With Throw Down is an effective exercise targeting the hip flexors using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0013-VX5YKR5.jpg', 'videos/0013-VX5YKR5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0014', 'assisted-motion-russian-twist', 'アシスト Motion Russian ツイスト', 'Assisted Motion Russian Twist', 'アシスト Motion Russian ツイストは、メディシンボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Motion Russian Twist is an effective exercise targeting the obliques using medicine ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', 'images/0014-r7cT9YD.jpg', 'videos/0014-r7cT9YD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0015', 'assisted-parallel-close-grip-pull-up', 'アシスト Parallel Close Grip プルアップ', 'Assisted Parallel Close Grip Pull-up', 'アシスト Parallel Close Grip プルアップは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Assisted Parallel Close Grip Pull-up is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0015-vrhHa6D.jpg', 'videos/0015-vrhHa6D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0016', 'assisted-prone-hamstring', 'アシスト プローン Hamstring', 'Assisted Prone Hamstring', 'アシスト プローン Hamstringは、アシストマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Assisted Prone Hamstring is an effective exercise targeting the glutes using assisted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0016-VedGSby.jpg', 'videos/0016-VedGSby.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1713', 'assisted-prone-lying-quads-stretch', 'アシスト プローン ライイング Quads ストレッチ', 'Assisted Prone Lying Quads Stretch', 'アシスト プローン ライイング Quads ストレッチは、アシストマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Assisted Prone Lying Quads Stretch is an effective exercise targeting the hamstrings using assisted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."]', 'images/1713-YUYAMEj.jpg', 'videos/1713-YUYAMEj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1714', 'assisted-prone-rectus-femoris-stretch', 'アシスト プローン Rectus Femoris ストレッチ', 'Assisted Prone Rectus Femoris Stretch', 'アシスト プローン Rectus Femoris ストレッチは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Prone Rectus Femoris Stretch is an effective exercise targeting the quadriceps using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', 'images/1714-2Ryn564.jpg', 'videos/1714-2Ryn564.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0017', 'assisted-pull-up', 'アシスト プルアップ', 'Assisted Pull-up', 'アシスト プルアップは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Assisted Pull-up is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0017-kiJ4Z2K.jpg', 'videos/0017-kiJ4Z2K.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1716', 'assisted-seated-pectoralis-major-stretch-with-stability-ball', 'アシスト シーテッド Pectoralis Major ストレッチ With Stability Ball', 'Assisted Seated Pectoralis Major Stretch With Stability Ball', 'アシスト シーテッド Pectoralis Major ストレッチ With Stability Ballは、アシストマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Assisted Seated Pectoralis Major Stretch With Stability Ball is an effective exercise targeting the shoulders using assisted.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1716-RoV1Rfa.jpg', 'videos/1716-RoV1Rfa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1712', 'assisted-side-lying-adductor-stretch', 'アシスト Side ライイング Adductor ストレッチ', 'Assisted Side Lying Adductor Stretch', 'アシスト Side ライイング Adductor ストレッチは、アシストマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Assisted Side Lying Adductor Stretch is an effective exercise targeting the hamstrings using assisted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."]', 'images/1712-hC6oYY5.jpg', 'videos/1712-hC6oYY5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1758', 'assisted-sit-up', 'アシスト Sit-up', 'Assisted Sit-up', 'アシスト Sit-upは、アシストマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Assisted Sit-up is an effective exercise targeting the hip flexors using assisted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1758-aumB2IV.jpg', 'videos/1758-aumB2IV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1431', 'assisted-standing-chin-up', 'アシスト スタンディング チンアップ', 'Assisted Standing Chin-up', 'アシスト スタンディング チンアップは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Assisted Standing Chin-up is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1431-7OeHptV.jpg', 'videos/1431-7OeHptV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1432', 'assisted-standing-pull-up', 'アシスト スタンディング プルアップ', 'Assisted Standing Pull-up', 'アシスト スタンディング プルアップは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Assisted Standing Pull-up is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1432-f4xtKBj.jpg', 'videos/1432-f4xtKBj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0018', 'assisted-standing-triceps-extension-with-towel', 'アシスト スタンディング トライセップス エクステンション (with タオル)', 'Assisted Standing Triceps Extension (with Towel)', 'アシスト スタンディング トライセップス エクステンション (with タオル)は、アシストマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Assisted Standing Triceps Extension (with Towel) is an effective exercise targeting the shoulders using assisted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0018-7HcfMBP.jpg', 'videos/0018-7HcfMBP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0019', 'assisted-triceps-dip-kneeling', 'アシスト トライセップス ディップス (ニーリング)', 'Assisted Triceps Dip (kneeling)', 'アシスト トライセップス ディップス (ニーリング)は、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Assisted Triceps Dip (kneeling) is an effective exercise targeting the chest using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0019-J60bN17.jpg', 'videos/0019-J60bN17.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2364', 'assisted-wide-grip-chest-dip-kneeling', 'アシスト ワイドグリップ チェスト ディップス (ニーリング)', 'Assisted Wide-grip Chest Dip (kneeling)', 'アシスト ワイドグリップ チェスト ディップス (ニーリング)は、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Assisted Wide-grip Chest Dip (kneeling) is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/2364-PnZJIrk.jpg', 'videos/2364-PnZJIrk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3220', 'astride-jumps-male', 'Astride Jumps (male)', 'Astride Jumps (male)', 'Astride Jumps (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Astride Jumps (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', 'images/3220-f9lVSSI.jpg', 'videos/3220-f9lVSSI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3672', 'back-and-forth-step', 'バック And Forth Step', 'Back And Forth Step', 'バック And Forth Stepは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Back And Forth Step is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."]', 'images/3672-fNGumX0.jpg', 'videos/3672-fNGumX0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1314', 'back-extension-on-exercise-ball', 'バック エクステンション On Exercise Ball', 'Back Extension On Exercise Ball', 'バック エクステンション On Exercise Ballは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Back Extension On Exercise Ball is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1314-qLpO4vV.jpg', 'videos/1314-qLpO4vV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3297', 'back-lever', 'バック Lever', 'Back Lever', 'バック Leverは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Back Lever is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3297-GaSzzuh.jpg', 'videos/3297-GaSzzuh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1405', 'back-pec-stretch', 'バック Pec ストレッチ', 'Back Pec Stretch', 'バック Pec ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Back Pec Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."]', 'images/1405-chfnQnM.jpg', 'videos/1405-chfnQnM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1473', 'backward-jump', 'Backward Jump', 'Backward Jump', 'Backward Jumpは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Backward Jump is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', 'images/1473-SaDOwk7.jpg', 'videos/1473-SaDOwk7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0020', 'balance-board', 'Balance Board', 'Balance Board', 'Balance Boardは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Balance Board is an effective exercise targeting the calves using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."]', 'images/0020-xAySMB0.jpg', 'videos/0020-xAySMB0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0968', 'band-alternating-biceps-curl', 'バンド Alternating バイセップス カール', 'Band Alternating Biceps Curl', 'バンド Alternating バイセップス カールは、バンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Band Alternating Biceps Curl is an effective exercise targeting the forearms using band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0968-3omWx6P.jpg', 'videos/0968-3omWx6P.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0969', 'band-alternating-v-up', 'バンド Alternating V-up', 'Band Alternating V-up', 'バンド Alternating V-upは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Alternating V-up is an effective exercise targeting the hip flexors using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."]', 'images/0969-ztAa1RK.jpg', 'videos/0969-ztAa1RK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0970', 'band-assisted-pull-up', 'バンド アシスト プルアップ', 'Band Assisted Pull-up', 'バンド アシスト プルアップは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Assisted Pull-up is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0970-r1XNRYB.jpg', 'videos/0970-r1XNRYB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0971', 'band-assisted-wheel-rollerout', 'バンド アシスト ホイール Rollerout', 'Band Assisted Wheel Rollerout', 'バンド アシスト ホイール Rolleroutは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Assisted Wheel Rollerout is an effective exercise targeting the lower back using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0971-zhF9lW4.jpg', 'videos/0971-zhF9lW4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1254', 'band-bench-press', 'バンド ベンチプレス', 'Band Bench Press', 'バンド ベンチプレスは、バンドを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Band Bench Press is an effective exercise targeting the triceps using band.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."]', 'images/1254-khlHMqs.jpg', 'videos/1254-khlHMqs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0980', 'band-bent-over-hip-extension', 'バンド Bent-over ヒップ エクステンション', 'Band Bent-over Hip Extension', 'バンド Bent-over ヒップ エクステンションは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Bent-over Hip Extension is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."]', 'images/0980-wSScovH.jpg', 'videos/0980-wSScovH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0972', 'band-bicycle-crunch', 'バンド Bicycle クランチ', 'Band Bicycle Crunch', 'バンド Bicycle クランチは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Bicycle Crunch is an effective exercise targeting the hip flexors using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."]', 'images/0972-tZkGYZ9.jpg', 'videos/0972-tZkGYZ9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0974', 'band-close-grip-pulldown', 'バンド ナローグリップ プルダウン', 'Band Close-grip Pulldown', 'バンド ナローグリップ プルダウンは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Close-grip Pulldown is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0974-DptumMx.jpg', 'videos/0974-DptumMx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0975', 'band-close-grip-push-up', 'バンド ナローグリップ プッシュアップ', 'Band Close-grip Push-up', 'バンド ナローグリップ プッシュアップは、バンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Band Close-grip Push-up is an effective exercise targeting the chest using band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0975-ufaxB52.jpg', 'videos/0975-ufaxB52.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0976', 'band-concentration-curl', 'バンド Concentration カール', 'Band Concentration Curl', 'バンド Concentration カールは、バンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Band Concentration Curl is an effective exercise targeting the forearms using band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0976-kmVVAfu.jpg', 'videos/0976-kmVVAfu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3117', 'band-fixed-back-close-grip-pulldown', 'バンド Fixed バック Close Grip プルダウン', 'Band Fixed Back Close Grip Pulldown', 'バンド Fixed バック Close Grip プルダウンは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Fixed Back Close Grip Pulldown is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', 'images/3117-4LoWllp.jpg', 'videos/3117-4LoWllp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3116', 'band-fixed-back-underhand-pulldown', 'バンド Fixed バック Underhand プルダウン', 'Band Fixed Back Underhand Pulldown', 'バンド Fixed バック Underhand プルダウンは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Fixed Back Underhand Pulldown is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3116-ZH68exZ.jpg', 'videos/3116-ZH68exZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0977', 'band-front-lateral-raise', 'バンド フロント サイド レイズ', 'Band Front Lateral Raise', 'バンド フロント サイド レイズは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Front Lateral Raise is an effective exercise targeting the traps using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0977-sTg7iys.jpg', 'videos/0977-sTg7iys.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0978', 'band-front-raise', 'バンド フロント レイズ', 'Band Front Raise', 'バンド フロント レイズは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Front Raise is an effective exercise targeting the triceps using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0978-TFA88iB.jpg', 'videos/0978-TFA88iB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1408', 'band-hip-lift', 'バンド ヒップ Lift', 'Band Hip Lift', 'バンド ヒップ Liftは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Hip Lift is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1408-E4R8Hz1.jpg', 'videos/1408-E4R8Hz1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0979', 'band-horizontal-pallof-press', 'バンド Horizontal Pallof プレス', 'Band Horizontal Pallof Press', 'バンド Horizontal Pallof プレスは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Horizontal Pallof Press is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."]', 'images/0979-9pa4H5m.jpg', 'videos/0979-9pa4H5m.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0981', 'band-jack-knife-sit-up', 'バンド Jack Knife Sit-up', 'Band Jack Knife Sit-up', 'バンド Jack Knife Sit-upは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Jack Knife Sit-up is an effective exercise targeting the hip flexors using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0981-KCBKjma.jpg', 'videos/0981-KCBKjma.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0983', 'band-kneeling-one-arm-pulldown', 'バンド ニーリング ワンハンド プルダウン', 'Band Kneeling One Arm Pulldown', 'バンド ニーリング ワンハンド プルダウンは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Kneeling One Arm Pulldown is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0983-pmnrOp0.jpg', 'videos/0983-pmnrOp0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0985', 'band-kneeling-twisting-crunch', 'バンド ニーリング Twisting クランチ', 'Band Kneeling Twisting Crunch', 'バンド ニーリング Twisting クランチは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Kneeling Twisting Crunch is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0985-225x2Vd.jpg', 'videos/0985-225x2Vd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0984', 'band-lying-hip-internal-rotation', 'バンド ライイング ヒップ Internal Rotation', 'Band Lying Hip Internal Rotation', 'バンド ライイング ヒップ Internal Rotationは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Lying Hip Internal Rotation is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0984-vIICElP.jpg', 'videos/0984-vIICElP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1002', 'band-lying-straight-leg-raise', 'バンド ライイング Straight Leg レイズ', 'Band Lying Straight Leg Raise', 'バンド ライイング Straight Leg レイズは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Lying Straight Leg Raise is an effective exercise targeting the hip flexors using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1002-bbLR7fB.jpg', 'videos/1002-bbLR7fB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0986', 'band-one-arm-overhead-biceps-curl', 'バンド ワンハンド オーバーヘッド バイセップス カール', 'Band One Arm Overhead Biceps Curl', 'バンド ワンハンド オーバーヘッド バイセップス カールは、バンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Band One Arm Overhead Biceps Curl is an effective exercise targeting the forearms using band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0986-UNAB8ak.jpg', 'videos/0986-UNAB8ak.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0987', 'band-one-arm-single-leg-split-squat', 'バンド ワンハンド シングルレッグ Split スクワット', 'Band One Arm Single Leg Split Squat', 'バンド ワンハンド シングルレッグ Split スクワットは、バンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Band One Arm Single Leg Split Squat is an effective exercise targeting the glutes using band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0987-arsYEd3.jpg', 'videos/0987-arsYEd3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0988', 'band-one-arm-standing-low-row', 'バンド ワンハンド スタンディング Low ロー', 'Band One Arm Standing Low Row', 'バンド ワンハンド スタンディング Low ローは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band One Arm Standing Low Row is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0988-km0sQC0.jpg', 'videos/0988-km0sQC0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0989', 'band-one-arm-twisting-chest-press', 'バンド ワンハンド Twisting チェスト プレス', 'Band One Arm Twisting Chest Press', 'バンド ワンハンド Twisting チェスト プレスは、バンドを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Band One Arm Twisting Chest Press is an effective exercise targeting the shoulders using band.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."]', 'images/0989-c16nYGA.jpg', 'videos/0989-c16nYGA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0990', 'band-one-arm-twisting-seated-row', 'バンド ワンハンド Twisting シーテッド ロー', 'Band One Arm Twisting Seated Row', 'バンド ワンハンド Twisting シーテッド ローは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band One Arm Twisting Seated Row is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0990-DKBwJrL.jpg', 'videos/0990-DKBwJrL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0991', 'band-pull-through', 'バンド Pull Through', 'Band Pull Through', 'バンド Pull Throughは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Pull Through is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'pull', 'lower', '["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0991-VtTbiP3.jpg', 'videos/0991-VtTbiP3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0992', 'band-push-sit-up', 'バンド Push Sit-up', 'Band Push Sit-up', 'バンド Push Sit-upは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Push Sit-up is an effective exercise targeting the shoulders using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0992-zFzbBfL.jpg', 'videos/0992-zFzbBfL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0993', 'band-reverse-fly', 'バンド Reverse フライ', 'Band Reverse Fly', 'バンド Reverse フライは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Reverse Fly is an effective exercise targeting the upper back using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0993-sTfvVsG.jpg', 'videos/0993-sTfvVsG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0994', 'band-reverse-wrist-curl', 'バンド Reverse リスト カール', 'Band Reverse Wrist Curl', 'バンド Reverse リスト カールは、バンドを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Band Reverse Wrist Curl is an effective exercise targeting the forearms using band.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0994-Ezpnw9d.jpg', 'videos/0994-Ezpnw9d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0996', 'band-seated-hip-internal-rotation', 'バンド シーテッド ヒップ Internal Rotation', 'Band Seated Hip Internal Rotation', 'バンド シーテッド ヒップ Internal Rotationは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Seated Hip Internal Rotation is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0996-9gbyYKk.jpg', 'videos/0996-9gbyYKk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1011', 'band-seated-twist', 'バンド シーテッド ツイスト', 'Band Seated Twist', 'バンド シーテッド ツイストは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Seated Twist is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1011-S1JXDAG.jpg', 'videos/1011-S1JXDAG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0997', 'band-shoulder-press', 'バンド Shoulder プレス', 'Band Shoulder Press', 'バンド Shoulder プレスは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Shoulder Press is an effective exercise targeting the triceps using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0997-peAeMR3.jpg', 'videos/0997-peAeMR3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1018', 'band-shrug', 'バンド シュラッグ', 'Band Shrug', 'バンド シュラッグは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Shrug is an effective exercise targeting the shoulders using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1018-trmte8s.jpg', 'videos/1018-trmte8s.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0998', 'band-side-triceps-extension', 'バンド Side トライセップス エクステンション', 'Band Side Triceps Extension', 'バンド Side トライセップス エクステンションは、バンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Band Side Triceps Extension is an effective exercise targeting the shoulders using band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."]', 'images/0998-obe5LMq.jpg', 'videos/0998-obe5LMq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0999', 'band-single-leg-calf-raise', 'バンド シングルレッグ カーフ レイズ', 'Band Single Leg Calf Raise', 'バンド シングルレッグ カーフ レイズは、バンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Band Single Leg Calf Raise is an effective exercise targeting the ankles using band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."]', 'images/0999-9JprnPh.jpg', 'videos/0999-9JprnPh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1000', 'band-single-leg-reverse-calf-raise', 'バンド シングルレッグ Reverse カーフ レイズ', 'Band Single Leg Reverse Calf Raise', 'バンド シングルレッグ Reverse カーフ レイズは、バンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Band Single Leg Reverse Calf Raise is an effective exercise targeting the hamstrings using band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', 'images/1000-QsSQWbf.jpg', 'videos/1000-QsSQWbf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1001', 'band-single-leg-split-squat', 'バンド シングルレッグ Split スクワット', 'Band Single Leg Split Squat', 'バンド シングルレッグ Split スクワットは、バンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Band Single Leg Split Squat is an effective exercise targeting the glutes using band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."]', 'images/1001-y8bYM8w.jpg', 'videos/1001-y8bYM8w.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1004', 'band-squat', 'バンド スクワット', 'Band Squat', 'バンド スクワットは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Squat is an effective exercise targeting the quadriceps using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1004-TUZLh71.jpg', 'videos/1004-TUZLh71.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1003', 'band-squat-row', 'バンド スクワット ロー', 'Band Squat Row', 'バンド スクワット ローは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Squat Row is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1003-w1NOByi.jpg', 'videos/1003-w1NOByi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1005', 'band-standing-crunch', 'バンド スタンディング クランチ', 'Band Standing Crunch', 'バンド スタンディング クランチは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Standing Crunch is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1005-Kzg30R7.jpg', 'videos/1005-Kzg30R7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1022', 'band-standing-rear-delt-row', 'バンド スタンディング リア Delt ロー', 'Band Standing Rear Delt Row', 'バンド スタンディング リア Delt ローは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Standing Rear Delt Row is an effective exercise targeting the trapezius using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1022-tc5dYrf.jpg', 'videos/1022-tc5dYrf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1007', 'band-standing-twisting-crunch', 'バンド スタンディング Twisting クランチ', 'Band Standing Twisting Crunch', 'バンド スタンディング Twisting クランチは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Standing Twisting Crunch is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1007-euq4pwp.jpg', 'videos/1007-euq4pwp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1008', 'band-step-up', 'バンド Step-up', 'Band Step-up', 'バンド Step-upは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Step-up is an effective exercise targeting the quadriceps using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."]', 'images/1008-d5bTEPV.jpg', 'videos/1008-d5bTEPV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1009', 'band-stiff-leg-deadlift', 'バンド Stiff Leg デッドリフト', 'Band Stiff Leg Deadlift', 'バンド Stiff Leg デッドリフトは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Stiff Leg Deadlift is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1009-kuMiR2T.jpg', 'videos/1009-kuMiR2T.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1023', 'band-straight-back-stiff-leg-deadlift', 'バンド Straight バック Stiff Leg デッドリフト', 'Band Straight Back Stiff Leg Deadlift', 'バンド Straight バック Stiff Leg デッドリフトは、バンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Band Straight Back Stiff Leg Deadlift is an effective exercise targeting the hamstrings using band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1023-lHeUULr.jpg', 'videos/1023-lHeUULr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1010', 'band-straight-leg-deadlift', 'バンド Straight Leg デッドリフト', 'Band Straight Leg Deadlift', 'バンド Straight Leg デッドリフトは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Straight Leg Deadlift is an effective exercise targeting the hamstrings using band.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1010-KUaoUV8.jpg', 'videos/1010-KUaoUV8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1012', 'band-twisting-overhead-press', 'バンド Twisting オーバーヘッド プレス', 'Band Twisting Overhead Press', 'バンド Twisting オーバーヘッド プレスは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Twisting Overhead Press is an effective exercise targeting the triceps using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/1012-u4bAmKp.jpg', 'videos/1012-u4bAmKp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1369', 'band-two-legs-calf-raise-band-under-both-legs-v-2', 'バンド Two Legs カーフ レイズ - (バンド Under Both Legs) V. 2', 'Band Two Legs Calf Raise - (band Under Both Legs) V. 2', 'バンド Two Legs カーフ レイズ - (バンド Under Both Legs) V. 2は、バンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Band Two Legs Calf Raise - (band Under Both Legs) V. 2 is an effective exercise targeting the ankles using band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1369-jl6uxZV.jpg', 'videos/1369-jl6uxZV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1013', 'band-underhand-pulldown', 'バンド Underhand プルダウン', 'Band Underhand Pulldown', 'バンド Underhand プルダウンは、バンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Band Underhand Pulldown is an effective exercise targeting the biceps using band.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1013-k6tUeqS.jpg', 'videos/1013-k6tUeqS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1014', 'band-v-up', 'バンド V-up', 'Band V-up', 'バンド V-upは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band V-up is an effective exercise targeting the hip flexors using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1014-H6ETwO9.jpg', 'videos/1014-H6ETwO9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1015', 'band-vertical-pallof-press', 'バンド Vertical Pallof プレス', 'Band Vertical Pallof Press', 'バンド Vertical Pallof プレスは、バンドを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Band Vertical Pallof Press is an effective exercise targeting the obliques using band.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1015-G7PXMlT.jpg', 'videos/1015-G7PXMlT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1016', 'band-wrist-curl', 'バンド リスト カール', 'Band Wrist Curl', 'バンド リスト カールは、バンドを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Band Wrist Curl is an effective exercise targeting the biceps using band.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1016-vUTfFHw.jpg', 'videos/1016-vUTfFHw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1017', 'band-y-raise', 'バンド Y-レイズ', 'Band Y-raise', 'バンド Y-レイズは、バンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Band Y-raise is an effective exercise targeting the traps using band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1017-aHDy5O5.jpg', 'videos/1017-aHDy5O5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0023', 'barbell-alternate-biceps-curl', 'バーベル Alternate バイセップス カール', 'Barbell Alternate Biceps Curl', 'バーベル Alternate バイセップス カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Alternate Biceps Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', 'images/0023-Yza7XrQ.jpg', 'videos/0023-Yza7XrQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0024', 'barbell-bench-front-squat', 'バーベル ベンチ フロント スクワット', 'Barbell Bench Front Squat', 'バーベル ベンチ フロント スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Bench Front Squat is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0024-Y7YcmIJ.jpg', 'videos/0024-Y7YcmIJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0025', 'barbell-bench-press', 'バーベル ベンチプレス', 'Barbell Bench Press', 'バーベル ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Bench Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0025-EIeI8Vf.jpg', 'videos/0025-EIeI8Vf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0026', 'barbell-bench-squat', 'バーベル ベンチ スクワット', 'Barbell Bench Squat', 'バーベル ベンチ スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Bench Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0026-W9pFVv1.jpg', 'videos/0026-W9pFVv1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1316', 'barbell-bent-arm-pullover', 'バーベル Bent Arm プルオーバー', 'Barbell Bent Arm Pullover', 'バーベル Bent Arm プルオーバーは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Bent Arm Pullover is an effective exercise targeting the triceps using barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1316-cA9FuWG.jpg', 'videos/1316-cA9FuWG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0027', 'barbell-bent-over-row', 'バーベル Bent Over ロー', 'Barbell Bent Over Row', 'バーベル Bent Over ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Bent Over Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0027-eZyBC3j.jpg', 'videos/0027-eZyBC3j.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2407', 'barbell-biceps-curl-with-arm-blaster', 'バーベル バイセップス カール (with Arm Blaster)', 'Barbell Biceps Curl (with Arm Blaster)', 'バーベル バイセップス カール (with Arm Blaster)は、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Biceps Curl (with Arm Blaster) is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2407-aee2Fcj.jpg', 'videos/2407-aee2Fcj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0028', 'barbell-clean-and-press', 'バーベル Clean And プレス', 'Barbell Clean And Press', 'バーベル Clean And プレスは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Clean And Press is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0028-SGY8Zui.jpg', 'videos/0028-SGY8Zui.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0029', 'barbell-clean-grip-front-squat', 'バーベル Clean-grip フロント スクワット', 'Barbell Clean-grip Front Squat', 'バーベル Clean-grip フロント スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Clean-grip Front Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/0029-qi996YS.jpg', 'videos/0029-qi996YS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0030', 'barbell-close-grip-bench-press', 'バーベル ナローグリップ ベンチプレス', 'Barbell Close-grip Bench Press', 'バーベル ナローグリップ ベンチプレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Close-grip Bench Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0030-J6Dx1Mu.jpg', 'videos/0030-J6Dx1Mu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0031', 'barbell-curl', 'バーベル カール', 'Barbell Curl', 'バーベル カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0031-25GPyDY.jpg', 'videos/0031-25GPyDY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0032', 'barbell-deadlift', 'バーベル デッドリフト', 'Barbell Deadlift', 'バーベル デッドリフトは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Deadlift is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."]', 'images/0032-ila4NZS.jpg', 'videos/0032-ila4NZS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0033', 'barbell-decline-bench-press', 'バーベル デクライン ベンチプレス', 'Barbell Decline Bench Press', 'バーベル デクライン ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Bench Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0033-GrO65fd.jpg', 'videos/0033-GrO65fd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0034', 'barbell-decline-bent-arm-pullover', 'バーベル デクライン Bent Arm プルオーバー', 'Barbell Decline Bent Arm Pullover', 'バーベル デクライン Bent Arm プルオーバーは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Bent Arm Pullover is an effective exercise targeting the triceps using barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."]', 'images/0034-hMEptv0.jpg', 'videos/0034-hMEptv0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0035', 'barbell-decline-close-grip-to-skull-press', 'バーベル デクライン Close Grip To Skull プレス', 'Barbell Decline Close Grip To Skull Press', 'バーベル デクライン Close Grip To Skull プレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Close Grip To Skull Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0035-LMGXZn8.jpg', 'videos/0035-LMGXZn8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1255', 'barbell-decline-pullover', 'バーベル デクライン プルオーバー', 'Barbell Decline Pullover', 'バーベル デクライン プルオーバーは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Pullover is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."]', 'images/1255-9sgNE2O.jpg', 'videos/1255-9sgNE2O.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0036', 'barbell-decline-wide-grip-press', 'バーベル デクライン ワイドグリップ プレス', 'Barbell Decline Wide-grip Press', 'バーベル デクライン ワイドグリップ プレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Wide-grip Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0036-hl8DUh8.jpg', 'videos/0036-hl8DUh8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0037', 'barbell-decline-wide-grip-pullover', 'バーベル デクライン ワイドグリップ プルオーバー', 'Barbell Decline Wide-grip Pullover', 'バーベル デクライン ワイドグリップ プルオーバーは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Decline Wide-grip Pullover is an effective exercise targeting the triceps using barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0037-Hj4FOCd.jpg', 'videos/0037-Hj4FOCd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0038', 'barbell-drag-curl', 'バーベル Drag カール', 'Barbell Drag Curl', 'バーベル Drag カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Drag Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm''s length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0038-IENzBdA.jpg', 'videos/0038-IENzBdA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1370', 'barbell-floor-calf-raise', 'バーベル Floor カーフ レイズ', 'Barbell Floor Calf Raise', 'バーベル Floor カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Floor Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1370-2IHEa2T.jpg', 'videos/1370-2IHEa2T.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0039', 'barbell-front-chest-squat', 'バーベル フロント チェスト スクワット', 'Barbell Front Chest Squat', 'バーベル フロント チェスト スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Front Chest Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0039-IeTIEqg.jpg', 'videos/0039-IeTIEqg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0041', 'barbell-front-raise', 'バーベル フロント レイズ', 'Barbell Front Raise', 'バーベル フロント レイズは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Front Raise is an effective exercise targeting the biceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0041-b2Uoz54.jpg', 'videos/0041-b2Uoz54.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0040', 'barbell-front-raise-and-pullover', 'バーベル フロント レイズ And プルオーバー', 'Barbell Front Raise And Pullover', 'バーベル フロント レイズ And プルオーバーは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Front Raise And Pullover is an effective exercise targeting the deltoids using barbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0040-33AzZeV.jpg', 'videos/0040-33AzZeV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0042', 'barbell-front-squat', 'バーベル フロント スクワット', 'Barbell Front Squat', 'バーベル フロント スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Front Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0042-zG0zs85.jpg', 'videos/0042-zG0zs85.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0043', 'barbell-full-squat', 'バーベル Full スクワット', 'Barbell Full Squat', 'バーベル Full スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Full Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/0043-qXTaZnJ.jpg', 'videos/0043-qXTaZnJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1461', 'barbell-full-squat-back-pov', 'バーベル Full スクワット (バック Pov)', 'Barbell Full Squat (back Pov)', 'バーベル Full スクワット (バック Pov)は、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Full Squat (back Pov) is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/1461-DhMl549.jpg', 'videos/1461-DhMl549.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1462', 'barbell-full-squat-side-pov', 'バーベル Full スクワット (side Pov)', 'Barbell Full Squat (side Pov)', 'バーベル Full スクワット (side Pov)は、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Full Squat (side Pov) is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/1462-iYzB0Cz.jpg', 'videos/1462-iYzB0Cz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1545', 'barbell-full-zercher-squat', 'バーベル Full Zercher スクワット', 'Barbell Full Zercher Squat', 'バーベル Full Zercher スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Full Zercher Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."]', 'images/1545-vR1vold.jpg', 'videos/1545-vR1vold.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1409', 'barbell-glute-bridge', 'バーベル グルート Bridge', 'Barbell Glute Bridge', 'バーベル グルート Bridgeは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Glute Bridge is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1409-qKBpF7I.jpg', 'videos/1409-qKBpF7I.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3562', 'barbell-glute-bridge-two-legs-on-bench-male', 'バーベル グルート Bridge Two Legs On ベンチ (male)', 'Barbell Glute Bridge Two Legs On Bench (male)', 'バーベル グルート Bridge Two Legs On ベンチ (male)は、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Glute Bridge Two Legs On Bench (male) is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3562-qg2PGl6.jpg', 'videos/3562-qg2PGl6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0044', 'barbell-good-morning', 'バーベル Good Morning', 'Barbell Good Morning', 'バーベル Good Morningは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Good Morning is an effective exercise targeting the lower back using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."]', 'images/0044-XlZ4lAC.jpg', 'videos/0044-XlZ4lAC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0045', 'barbell-guillotine-bench-press', 'バーベル Guillotine ベンチプレス', 'Barbell Guillotine Bench Press', 'バーベル Guillotine ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Guillotine Bench Press is an effective exercise targeting the shoulders using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0045-GXoaSgn.jpg', 'videos/0045-GXoaSgn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0046', 'barbell-hack-squat', 'バーベル ハック スクワット', 'Barbell Hack Squat', 'バーベル ハック スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Hack Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0046-5VCj6iH.jpg', 'videos/0046-5VCj6iH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1436', 'barbell-high-bar-squat', 'バーベル High Bar スクワット', 'Barbell High Bar Squat', 'バーベル High Bar スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell High Bar Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/1436-Gnfo4FM.jpg', 'videos/1436-Gnfo4FM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0047', 'barbell-incline-bench-press', 'バーベル インクライン ベンチプレス', 'Barbell Incline Bench Press', 'バーベル インクライン ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Incline Bench Press is an effective exercise targeting the shoulders using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0047-3TZduzM.jpg', 'videos/0047-3TZduzM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1719', 'barbell-incline-close-grip-bench-press', 'バーベル インクライン Close Grip ベンチプレス', 'Barbell Incline Close Grip Bench Press', 'バーベル インクライン Close Grip ベンチプレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Incline Close Grip Bench Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1719-gx7s7uF.jpg', 'videos/1719-gx7s7uF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0048', 'barbell-incline-reverse-grip-press', 'バーベル インクライン リバースグリップ プレス', 'Barbell Incline Reverse-grip Press', 'バーベル インクライン リバースグリップ プレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Incline Reverse-grip Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0048-641mIfk.jpg', 'videos/0048-641mIfk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0049', 'barbell-incline-row', 'バーベル インクライン ロー', 'Barbell Incline Row', 'バーベル インクライン ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Incline Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0049-dmgMp3n.jpg', 'videos/0049-dmgMp3n.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0050', 'barbell-incline-shoulder-raise', 'バーベル インクライン Shoulder レイズ', 'Barbell Incline Shoulder Raise', 'バーベル インクライン Shoulder レイズは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Incline Shoulder Raise is an effective exercise targeting the deltoids using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0050-xi0yckC.jpg', 'videos/0050-xi0yckC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0051', 'barbell-jefferson-squat', 'バーベル Jefferson スクワット', 'Barbell Jefferson Squat', 'バーベル Jefferson スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Jefferson Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."]', 'images/0051-pkSoCW9.jpg', 'videos/0051-pkSoCW9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0052', 'barbell-jm-bench-press', 'バーベル Jm ベンチプレス', 'Barbell Jm Bench Press', 'バーベル Jm ベンチプレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Jm Bench Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0052-ZsiqXYa.jpg', 'videos/0052-ZsiqXYa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0053', 'barbell-jump-squat', 'バーベル Jump スクワット', 'Barbell Jump Squat', 'バーベル Jump スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Jump Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]', 'images/0053-1gFNTZV.jpg', 'videos/0053-1gFNTZV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1410', 'barbell-lateral-lunge', 'バーベル サイド ランジ', 'Barbell Lateral Lunge', 'バーベル サイド ランジは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Lateral Lunge is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."]', 'images/1410-py1HSzx.jpg', 'videos/1410-py1HSzx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1435', 'barbell-low-bar-squat', 'バーベル Low Bar スクワット', 'Barbell Low Bar Squat', 'バーベル Low Bar スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Low Bar Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1435-bTpEUcm.jpg', 'videos/1435-bTpEUcm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0054', 'barbell-lunge', 'バーベル ランジ', 'Barbell Lunge', 'バーベル ランジは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Lunge is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."]', 'images/0054-t8iSghb.jpg', 'videos/0054-t8iSghb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1720', 'barbell-lying-back-of-the-head-tricep-extension', 'バーベル ライイング バック Of The Head Tricep エクステンション', 'Barbell Lying Back Of The Head Tricep Extension', 'バーベル ライイング バック Of The Head Tricep エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Back Of The Head Tricep Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1720-yg8Totb.jpg', 'videos/1720-yg8Totb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0055', 'barbell-lying-close-grip-press', 'バーベル ライイング ナローグリップ プレス', 'Barbell Lying Close-grip Press', 'バーベル ライイング ナローグリップ プレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Close-grip Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0055-EcaV7aL.jpg', 'videos/0055-EcaV7aL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0056', 'barbell-lying-close-grip-triceps-extension', 'バーベル ライイング ナローグリップ トライセップス エクステンション', 'Barbell Lying Close-grip Triceps Extension', 'バーベル ライイング ナローグリップ トライセップス エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Close-grip Triceps Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0056-HJ63mSO.jpg', 'videos/0056-HJ63mSO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0057', 'barbell-lying-extension', 'バーベル ライイング エクステンション', 'Barbell Lying Extension', 'バーベル ライイング エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0057-EMpUwRI.jpg', 'videos/0057-EMpUwRI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0058', 'barbell-lying-lifting-on-hip', 'バーベル ライイング Lifting (on ヒップ)', 'Barbell Lying Lifting (on Hip)', 'バーベル ライイング Lifting (on ヒップ)は、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Lifting (on Hip) is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0058-SNFfUff.jpg', 'videos/0058-SNFfUff.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0059', 'barbell-lying-preacher-curl', 'バーベル ライイング Preacher カール', 'Barbell Lying Preacher Curl', 'バーベル ライイング Preacher カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Preacher Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0059-SYJ4Bkt.jpg', 'videos/0059-SYJ4Bkt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0061', 'barbell-lying-triceps-extension', 'バーベル ライイング トライセップス エクステンション', 'Barbell Lying Triceps Extension', 'バーベル ライイング トライセップス エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Triceps Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0061-iZop9xO.jpg', 'videos/0061-iZop9xO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0060', 'barbell-lying-triceps-extension-skull-crusher', 'バーベル ライイング トライセップス エクステンション Skull Crusher', 'Barbell Lying Triceps Extension Skull Crusher', 'バーベル ライイング トライセップス エクステンション Skull Crusherは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Lying Triceps Extension Skull Crusher is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0060-h8LFzo9.jpg', 'videos/0060-h8LFzo9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0063', 'barbell-narrow-stance-squat', 'バーベル Narrow Stance スクワット', 'Barbell Narrow Stance Squat', 'バーベル Narrow Stance スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Narrow Stance Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0063-elhhVgj.jpg', 'videos/0063-elhhVgj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0064', 'barbell-one-arm-bent-over-row', 'バーベル ワンハンド Bent Over ロー', 'Barbell One Arm Bent Over Row', 'バーベル ワンハンド Bent Over ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell One Arm Bent Over Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0064-Jsgsc27.jpg', 'videos/0064-Jsgsc27.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0065', 'barbell-one-arm-floor-press', 'バーベル ワンハンド Floor プレス', 'Barbell One Arm Floor Press', 'バーベル ワンハンド Floor プレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell One Arm Floor Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0065-vtusOWT.jpg', 'videos/0065-vtusOWT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0066', 'barbell-one-arm-side-deadlift', 'バーベル ワンハンド Side デッドリフト', 'Barbell One Arm Side Deadlift', 'バーベル ワンハンド Side デッドリフトは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell One Arm Side Deadlift is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0066-2DxtqHL.jpg', 'videos/0066-2DxtqHL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0067', 'barbell-one-arm-snatch', 'バーベル ワンハンド Snatch', 'Barbell One Arm Snatch', 'バーベル ワンハンド Snatchは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell One Arm Snatch is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0067-xHKN2s8.jpg', 'videos/0067-xHKN2s8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0068', 'barbell-one-leg-squat', 'バーベル One Leg スクワット', 'Barbell One Leg Squat', 'バーベル One Leg スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell One Leg Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/0068-uKyN64F.jpg', 'videos/0068-uKyN64F.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0069', 'barbell-overhead-squat', 'バーベル オーバーヘッド スクワット', 'Barbell Overhead Squat', 'バーベル オーバーヘッド スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Overhead Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0069-gfk9kD4.jpg', 'videos/0069-gfk9kD4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1411', 'barbell-palms-down-wrist-curl-over-a-bench', 'バーベル Palms Down リスト カール Over A ベンチ', 'Barbell Palms Down Wrist Curl Over A Bench', 'バーベル Palms Down リスト カール Over A ベンチは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Palms Down Wrist Curl Over A Bench is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."]', 'images/1411-yzYH9pI.jpg', 'videos/1411-yzYH9pI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1412', 'barbell-palms-up-wrist-curl-over-a-bench', 'バーベル Palms Up リスト カール Over A ベンチ', 'Barbell Palms Up Wrist Curl Over A Bench', 'バーベル Palms Up リスト カール Over A ベンチは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Palms Up Wrist Curl Over A Bench is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1412-SJAA2IQ.jpg', 'videos/1412-SJAA2IQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3017', 'barbell-pendlay-row', 'バーベル Pendlay ロー', 'Barbell Pendlay Row', 'バーベル Pendlay ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Pendlay Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3017-r0z6xzQ.jpg', 'videos/3017-r0z6xzQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1751', 'barbell-pin-presses', 'バーベル Pin Presses', 'Barbell Pin Presses', 'バーベル Pin Pressesは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Pin Presses is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1751-bndCa3Q.jpg', 'videos/1751-bndCa3Q.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0070', 'barbell-preacher-curl', 'バーベル Preacher カール', 'Barbell Preacher Curl', 'バーベル Preacher カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Preacher Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0070-qOgPVf6.jpg', 'videos/0070-qOgPVf6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0071', 'barbell-press-sit-up', 'バーベル プレス Sit-up', 'Barbell Press Sit-up', 'バーベル プレス Sit-upは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Press Sit-up is an effective exercise targeting the shoulders using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0071-wnEscH8.jpg', 'videos/0071-wnEscH8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0072', 'barbell-prone-incline-curl', 'バーベル プローン インクライン カール', 'Barbell Prone Incline Curl', 'バーベル プローン インクライン カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Prone Incline Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0072-WLvTAv5.jpg', 'videos/0072-WLvTAv5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0073', 'barbell-pullover', 'バーベル プルオーバー', 'Barbell Pullover', 'バーベル プルオーバーは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Pullover is an effective exercise targeting the chest using barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0073-i6LWjok.jpg', 'videos/0073-i6LWjok.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0022', 'barbell-pullover-to-press', 'バーベル プルオーバー To プレス', 'Barbell Pullover To Press', 'バーベル プルオーバー To プレスは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Pullover To Press is an effective exercise targeting the triceps using barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."]', 'images/0022-znLogoF.jpg', 'videos/0022-znLogoF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0074', 'barbell-rack-pull', 'バーベル Rack Pull', 'Barbell Rack Pull', 'バーベル Rack Pullは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Rack Pull is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'pull', 'lower', '["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."]', 'images/0074-za9Ni4z.jpg', 'videos/0074-za9Ni4z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0075', 'barbell-rear-delt-raise', 'バーベル リア Delt レイズ', 'Barbell Rear Delt Raise', 'バーベル リア Delt レイズは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Rear Delt Raise is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0075-Ln9iTbU.jpg', 'videos/0075-Ln9iTbU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0076', 'barbell-rear-delt-row', 'バーベル リア Delt ロー', 'Barbell Rear Delt Row', 'バーベル リア Delt ローは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Rear Delt Row is an effective exercise targeting the trapezius using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0076-S9zHIvU.jpg', 'videos/0076-S9zHIvU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0078', 'barbell-rear-lunge', 'バーベル リア ランジ', 'Barbell Rear Lunge', 'バーベル リア ランジは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Rear Lunge is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', 'images/0078-VaP75jl.jpg', 'videos/0078-VaP75jl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0077', 'barbell-rear-lunge-v-2', 'バーベル リア ランジ V. 2', 'Barbell Rear Lunge V. 2', 'バーベル リア ランジ V. 2は、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Rear Lunge V. 2 is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', 'images/0077-62Nw60O.jpg', 'videos/0077-62Nw60O.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0079', 'barbell-revers-wrist-curl-v-2', 'バーベル Revers リスト カール V. 2', 'Barbell Revers Wrist Curl V. 2', 'バーベル Revers リスト カール V. 2は、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Revers Wrist Curl V. 2 is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0079-qDnGfDb.jpg', 'videos/0079-qDnGfDb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2187', 'barbell-reverse-close-grip-bench-press', 'バーベル Reverse ナローグリップ ベンチプレス', 'Barbell Reverse Close-grip Bench Press', 'バーベル Reverse ナローグリップ ベンチプレスは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Close-grip Bench Press is an effective exercise targeting the chest using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/2187-YqJw82s.jpg', 'videos/2187-YqJw82s.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0080', 'barbell-reverse-curl', 'バーベル Reverse カール', 'Barbell Reverse Curl', 'バーベル Reverse カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."]', 'images/0080-xNrS20v.jpg', 'videos/0080-xNrS20v.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0118', 'barbell-reverse-grip-bent-over-row', 'バーベル Reverse Grip Bent Over ロー', 'Barbell Reverse Grip Bent Over Row', 'バーベル Reverse Grip Bent Over ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Grip Bent Over Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0118-SzX3uzM.jpg', 'videos/0118-SzX3uzM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1256', 'barbell-reverse-grip-decline-bench-press', 'バーベル Reverse Grip デクライン ベンチプレス', 'Barbell Reverse Grip Decline Bench Press', 'バーベル Reverse Grip デクライン ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Grip Decline Bench Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1256-DotAgEF.jpg', 'videos/1256-DotAgEF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1257', 'barbell-reverse-grip-incline-bench-press', 'バーベル Reverse Grip インクライン ベンチプレス', 'Barbell Reverse Grip Incline Bench Press', 'バーベル Reverse Grip インクライン ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Grip Incline Bench Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1257-DU7I633.jpg', 'videos/1257-DU7I633.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1317', 'barbell-reverse-grip-incline-bench-row', 'バーベル Reverse Grip インクライン ベンチ ロー', 'Barbell Reverse Grip Incline Bench Row', 'バーベル Reverse Grip インクライン ベンチ ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Grip Incline Bench Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1317-8d8qJQI.jpg', 'videos/1317-8d8qJQI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1721', 'barbell-reverse-grip-skullcrusher', 'バーベル Reverse Grip Skullcrusher', 'Barbell Reverse Grip Skullcrusher', 'バーベル Reverse Grip Skullcrusherは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Grip Skullcrusher is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1721-yRLPCLu.jpg', 'videos/1721-yRLPCLu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0081', 'barbell-reverse-preacher-curl', 'バーベル Reverse Preacher カール', 'Barbell Reverse Preacher Curl', 'バーベル Reverse Preacher カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Preacher Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0081-4LIG9xr.jpg', 'videos/0081-4LIG9xr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0082', 'barbell-reverse-wrist-curl', 'バーベル Reverse リスト カール', 'Barbell Reverse Wrist Curl', 'バーベル Reverse リスト カールは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Reverse Wrist Curl is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0082-LsZkfU6.jpg', 'videos/0082-LsZkfU6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0084', 'barbell-rollerout', 'バーベル Rollerout', 'Barbell Rollerout', 'バーベル Rolleroutは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Rollerout is an effective exercise targeting the lower back using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."]', 'images/0084-7M66AVi.jpg', 'videos/0084-7M66AVi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0083', 'barbell-rollerout-from-bench', 'バーベル Rollerout From ベンチ', 'Barbell Rollerout From Bench', 'バーベル Rollerout From ベンチは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Rollerout From Bench is an effective exercise targeting the shoulders using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', 'images/0083-Gxg9lDc.jpg', 'videos/0083-Gxg9lDc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0085', 'barbell-romanian-deadlift', 'バーベル Romanian デッドリフト', 'Barbell Romanian Deadlift', 'バーベル Romanian デッドリフトは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Romanian Deadlift is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0085-wQ2c4XD.jpg', 'videos/0085-wQ2c4XD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0086', 'barbell-seated-behind-head-military-press', 'バーベル シーテッド Behind Head Military プレス', 'Barbell Seated Behind Head Military Press', 'バーベル シーテッド Behind Head Military プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Behind Head Military Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0086-ngPpyRS.jpg', 'videos/0086-ngPpyRS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0087', 'barbell-seated-bradford-rocky-press', 'バーベル シーテッド Bradford Rocky プレス', 'Barbell Seated Bradford Rocky Press', 'バーベル シーテッド Bradford Rocky プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Bradford Rocky Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', 'images/0087-0dCyly0.jpg', 'videos/0087-0dCyly0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0088', 'barbell-seated-calf-raise', 'バーベル シーテッド カーフ レイズ', 'Barbell Seated Calf Raise', 'バーベル シーテッド カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0088-ktsFQAZ.jpg', 'videos/0088-ktsFQAZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1371', 'barbell-seated-calf-raise-1371', 'バーベル シーテッド カーフ レイズ', 'Barbell Seated Calf Raise', 'バーベル シーテッド カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."]', 'images/1371-ipvgBnC.jpg', 'videos/1371-ipvgBnC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1718', 'barbell-seated-close-grip-behind-neck-triceps-extension', 'バーベル シーテッド Close Grip Behind ネック トライセップス エクステンション', 'Barbell Seated Close Grip Behind Neck Triceps Extension', 'バーベル シーテッド Close Grip Behind ネック トライセップス エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Close Grip Behind Neck Triceps Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1718-4CBIBOM.jpg', 'videos/1718-4CBIBOM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0089', 'barbell-seated-close-grip-concentration-curl', 'バーベル シーテッド ナローグリップ Concentration カール', 'Barbell Seated Close-grip Concentration Curl', 'バーベル シーテッド ナローグリップ Concentration カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Close-grip Concentration Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0089-1V1gj1u.jpg', 'videos/0089-1V1gj1u.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0090', 'barbell-seated-good-morning', 'バーベル シーテッド Good Morning', 'Barbell Seated Good Morning', 'バーベル シーテッド Good Morningは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Good Morning is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0090-d960PgE.jpg', 'videos/0090-d960PgE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0091', 'barbell-seated-overhead-press', 'バーベル シーテッド オーバーヘッド プレス', 'Barbell Seated Overhead Press', 'バーベル シーテッド オーバーヘッド プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Overhead Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0091-kTbSH9h.jpg', 'videos/0091-kTbSH9h.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0092', 'barbell-seated-overhead-triceps-extension', 'バーベル シーテッド オーバーヘッド トライセップス エクステンション', 'Barbell Seated Overhead Triceps Extension', 'バーベル シーテッド オーバーヘッド トライセップス エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Overhead Triceps Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0092-5uFK1xr.jpg', 'videos/0092-5uFK1xr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0094', 'barbell-seated-twist', 'バーベル シーテッド ツイスト', 'Barbell Seated Twist', 'バーベル シーテッド ツイストは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Seated Twist is an effective exercise targeting the obliques using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0094-dFSNDOA.jpg', 'videos/0094-dFSNDOA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0095', 'barbell-shrug', 'バーベル シュラッグ', 'Barbell Shrug', 'バーベル シュラッグは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Shrug is an effective exercise targeting the shoulders using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0095-dG7tG5y.jpg', 'videos/0095-dG7tG5y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0096', 'barbell-side-bent-v-2', 'バーベル Side Bent V. 2', 'Barbell Side Bent V. 2', 'バーベル Side Bent V. 2は、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Side Bent V. 2 is an effective exercise targeting the obliques using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."]', 'images/0096-i4JkUaL.jpg', 'videos/0096-i4JkUaL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0098', 'barbell-side-split-squat', 'バーベル Side Split スクワット', 'Barbell Side Split Squat', 'バーベル Side Split スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Side Split Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0098-W31mMjd.jpg', 'videos/0098-W31mMjd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0097', 'barbell-side-split-squat-v-2', 'バーベル Side Split スクワット V. 2', 'Barbell Side Split Squat V. 2', 'バーベル Side Split スクワット V. 2は、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Side Split Squat V. 2 is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."]', 'images/0097-HUEqZ1y.jpg', 'videos/0097-HUEqZ1y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1756', 'barbell-single-leg-deadlift', 'バーベル シングルレッグ デッドリフト', 'Barbell Single Leg Deadlift', 'バーベル シングルレッグ デッドリフトは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Single Leg Deadlift is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1756-gEyURal.jpg', 'videos/1756-gEyURal.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0099', 'barbell-single-leg-split-squat', 'バーベル シングルレッグ Split スクワット', 'Barbell Single Leg Split Squat', 'バーベル シングルレッグ Split スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Single Leg Split Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0099-gGNQmVt.jpg', 'videos/0099-gGNQmVt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2799', 'barbell-sitted-alternate-leg-raise', 'バーベル Sitted Alternate Leg レイズ', 'Barbell Sitted Alternate Leg Raise', 'バーベル Sitted Alternate Leg レイズは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Sitted Alternate Leg Raise is an effective exercise targeting the hip flexors using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/2799-G7xoEzr.jpg', 'videos/2799-G7xoEzr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2800', 'barbell-sitted-alternate-leg-raise-female', 'バーベル Sitted Alternate Leg レイズ (female)', 'Barbell Sitted Alternate Leg Raise (female)', 'バーベル Sitted Alternate Leg レイズ (female)は、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Sitted Alternate Leg Raise (female) is an effective exercise targeting the hip flexors using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/2800-BCs0G2F.jpg', 'videos/2800-BCs0G2F.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0100', 'barbell-skier', 'バーベル Skier', 'Barbell Skier', 'バーベル Skierは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Skier is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0100-4Leypho.jpg', 'videos/0100-4Leypho.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0101', 'barbell-speed-squat', 'バーベル Speed スクワット', 'Barbell Speed Squat', 'バーベル Speed スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Speed Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', 'images/0101-euI1BwR.jpg', 'videos/0101-euI1BwR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2810', 'barbell-split-squat-v-2', 'バーベル Split スクワット V. 2', 'Barbell Split Squat V. 2', 'バーベル Split スクワット V. 2は、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Split Squat V. 2 is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."]', 'images/2810-HBYyX94.jpg', 'videos/2810-HBYyX94.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0102', 'barbell-squat-on-knees', 'バーベル スクワット (on Knees)', 'Barbell Squat (on Knees)', 'バーベル スクワット (on Knees)は、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Squat (on Knees) is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0102-oR7O9LW.jpg', 'videos/0102-oR7O9LW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2798', 'barbell-squat-jump-step-rear-lunge', 'バーベル スクワット Jump Step リア ランジ', 'Barbell Squat Jump Step Rear Lunge', 'バーベル スクワット Jump Step リア ランジは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Squat Jump Step Rear Lunge is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/2798-RYcV1kH.jpg', 'videos/2798-RYcV1kH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0103', 'barbell-standing-ab-rollerout', 'バーベル スタンディング Ab Rollerout', 'Barbell Standing Ab Rollerout', 'バーベル スタンディング Ab Rolleroutは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Ab Rollerout is an effective exercise targeting the shoulders using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."]', 'images/0103-xnInPfE.jpg', 'videos/0103-xnInPfE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0104', 'barbell-standing-back-wrist-curl', 'バーベル スタンディング バック リスト カール', 'Barbell Standing Back Wrist Curl', 'バーベル スタンディング バック リスト カールは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Back Wrist Curl is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0104-2qTvJAZ.jpg', 'videos/0104-2qTvJAZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0105', 'barbell-standing-bradford-press', 'バーベル スタンディング Bradford プレス', 'Barbell Standing Bradford Press', 'バーベル スタンディング Bradford プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Bradford Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0105-dCPESfR.jpg', 'videos/0105-dCPESfR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1372', 'barbell-standing-calf-raise', 'バーベル スタンディング カーフ レイズ', 'Barbell Standing Calf Raise', 'バーベル スタンディング カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1372-8ozhUIZ.jpg', 'videos/1372-8ozhUIZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0106', 'barbell-standing-close-grip-curl', 'バーベル スタンディング Close Grip カール', 'Barbell Standing Close Grip Curl', 'バーベル スタンディング Close Grip カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Close Grip Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0106-4dUn2iv.jpg', 'videos/0106-4dUn2iv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1456', 'barbell-standing-close-grip-military-press', 'バーベル スタンディング Close Grip Military プレス', 'Barbell Standing Close Grip Military Press', 'バーベル スタンディング Close Grip Military プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Close Grip Military Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/1456-wdRZISl.jpg', 'videos/1456-wdRZISl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2414', 'barbell-standing-concentration-curl', 'バーベル スタンディング Concentration カール', 'Barbell Standing Concentration Curl', 'バーベル スタンディング Concentration カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Concentration Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/2414-vsMcDi9.jpg', 'videos/2414-vsMcDi9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0107', 'barbell-standing-front-raise-over-head', 'バーベル スタンディング フロント レイズ Over Head', 'Barbell Standing Front Raise Over Head', 'バーベル スタンディング フロント レイズ Over Headは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Front Raise Over Head is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0107-S8mo30S.jpg', 'videos/0107-S8mo30S.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0108', 'barbell-standing-leg-calf-raise', 'バーベル スタンディング Leg カーフ レイズ', 'Barbell Standing Leg Calf Raise', 'バーベル スタンディング Leg カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Leg Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0108-rGwhJ5o.jpg', 'videos/0108-rGwhJ5o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0109', 'barbell-standing-overhead-triceps-extension', 'バーベル スタンディング オーバーヘッド トライセップス エクステンション', 'Barbell Standing Overhead Triceps Extension', 'バーベル スタンディング オーバーヘッド トライセップス エクステンションは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Overhead Triceps Extension is an effective exercise targeting the shoulders using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0109-dZl9Q27.jpg', 'videos/0109-dZl9Q27.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0110', 'barbell-standing-reverse-grip-curl', 'バーベル スタンディング Reverse Grip カール', 'Barbell Standing Reverse Grip Curl', 'バーベル スタンディング Reverse Grip カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Reverse Grip Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0110-LWuA3aZ.jpg', 'videos/0110-LWuA3aZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0111', 'barbell-standing-rocking-leg-calf-raise', 'バーベル スタンディング Rocking Leg カーフ レイズ', 'Barbell Standing Rocking Leg Calf Raise', 'バーベル スタンディング Rocking Leg カーフ レイズは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Rocking Leg Calf Raise is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0111-6HiHHe0.jpg', 'videos/0111-6HiHHe0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0112', 'barbell-standing-twist', 'バーベル スタンディング ツイスト', 'Barbell Standing Twist', 'バーベル スタンディング ツイストは、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Twist is an effective exercise targeting the obliques using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', 'images/0112-yQe5HpE.jpg', 'videos/0112-yQe5HpE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1629', 'barbell-standing-wide-grip-biceps-curl', 'バーベル スタンディング Wide Grip バイセップス カール', 'Barbell Standing Wide Grip Biceps Curl', 'バーベル スタンディング Wide Grip バイセップス カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Wide Grip Biceps Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1629-faHKVkK.jpg', 'videos/1629-faHKVkK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1457', 'barbell-standing-wide-military-press', 'バーベル スタンディング Wide Military プレス', 'Barbell Standing Wide Military Press', 'バーベル スタンディング Wide Military プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Wide Military Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', 'images/1457-Kyd9Rz5.jpg', 'videos/1457-Kyd9Rz5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0113', 'barbell-standing-wide-grip-curl', 'バーベル スタンディング ワイドグリップ カール', 'Barbell Standing Wide-grip Curl', 'バーベル スタンディング ワイドグリップ カールは、バーベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Standing Wide-grip Curl is an effective exercise targeting the forearms using barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0113-NdIb5Z1.jpg', 'videos/0113-NdIb5Z1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0114', 'barbell-step-up', 'バーベル Step-up', 'Barbell Step-up', 'バーベル Step-upは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Step-up is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."]', 'images/0114-Kxquu2E.jpg', 'videos/0114-Kxquu2E.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0115', 'barbell-stiff-leg-good-morning', 'バーベル Stiff Leg Good Morning', 'Barbell Stiff Leg Good Morning', 'バーベル Stiff Leg Good Morningは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Stiff Leg Good Morning is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0115-JrOHAZc.jpg', 'videos/0115-JrOHAZc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0116', 'barbell-straight-leg-deadlift', 'バーベル Straight Leg デッドリフト', 'Barbell Straight Leg Deadlift', 'バーベル Straight Leg デッドリフトは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Straight Leg Deadlift is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0116-hrVQWvE.jpg', 'videos/0116-hrVQWvE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0117', 'barbell-sumo-deadlift', 'バーベル Sumo デッドリフト', 'Barbell Sumo Deadlift', 'バーベル Sumo デッドリフトは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Sumo Deadlift is an effective exercise targeting the hamstrings using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', 'images/0117-KgI0tqW.jpg', 'videos/0117-KgI0tqW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3305', 'barbell-thruster', 'バーベル Thruster', 'Barbell Thruster', 'バーベル Thrusterは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Thruster is an effective exercise targeting the quadriceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."]', 'images/3305-f7Y9eDZ.jpg', 'videos/3305-f7Y9eDZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0120', 'barbell-upright-row', 'バーベル Upright ロー', 'Barbell Upright Row', 'バーベル Upright ローは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Upright Row is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0120-UDlhcO8.jpg', 'videos/0120-UDlhcO8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0119', 'barbell-upright-row-v-2', 'バーベル Upright ロー V. 2', 'Barbell Upright Row V. 2', 'バーベル Upright ロー V. 2は、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Upright Row V. 2 is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0119-83HoW9X.jpg', 'videos/0119-83HoW9X.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0121', 'barbell-upright-row-v-3', 'バーベル Upright ロー V. 3', 'Barbell Upright Row V. 3', 'バーベル Upright ロー V. 3は、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Upright Row V. 3 is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0121-fI18Rbc.jpg', 'videos/0121-fI18Rbc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0122', 'barbell-wide-bench-press', 'バーベル Wide ベンチプレス', 'Barbell Wide Bench Press', 'バーベル Wide ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Wide Bench Press is an effective exercise targeting the shoulders using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0122-JsKq9so.jpg', 'videos/0122-JsKq9so.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1258', 'barbell-wide-reverse-grip-bench-press', 'バーベル Wide Reverse Grip ベンチプレス', 'Barbell Wide Reverse Grip Bench Press', 'バーベル Wide Reverse Grip ベンチプレスは、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Barbell Wide Reverse Grip Bench Press is an effective exercise targeting the triceps using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1258-945zpRg.jpg', 'videos/1258-945zpRg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0124', 'barbell-wide-squat', 'バーベル Wide スクワット', 'Barbell Wide Squat', 'バーベル Wide スクワットは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Barbell Wide Squat is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0124-s7HX1BY.jpg', 'videos/0124-s7HX1BY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0123', 'barbell-wide-grip-upright-row', 'バーベル ワイドグリップ Upright ロー', 'Barbell Wide-grip Upright Row', 'バーベル ワイドグリップ Upright ローは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Barbell Wide-grip Upright Row is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0123-RgJDRR1.jpg', 'videos/0123-RgJDRR1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0126', 'barbell-wrist-curl', 'バーベル リスト カール', 'Barbell Wrist Curl', 'バーベル リスト カールは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Wrist Curl is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0126-82LxxkW.jpg', 'videos/0126-82LxxkW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0125', 'barbell-wrist-curl-v-2', 'バーベル リスト カール V. 2', 'Barbell Wrist Curl V. 2', 'バーベル リスト カール V. 2は、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Barbell Wrist Curl V. 2 is an effective exercise targeting the biceps using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0125-6kSxYnw.jpg', 'videos/0125-6kSxYnw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0127', 'barbell-zercher-squat', 'バーベル Zercher スクワット', 'Barbell Zercher Squat', 'バーベル Zercher スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Barbell Zercher Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0127-LSTChY9.jpg', 'videos/0127-LSTChY9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3212', 'basic-toe-touch-male', 'Basic Toe Touch (male)', 'Basic Toe Touch (male)', 'Basic Toe Touch (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Basic Toe Touch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3212-BbfB8Gb.jpg', 'videos/3212-BbfB8Gb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0128', 'battling-ropes', 'Battling Ropes', 'Battling Ropes', 'Battling Ropesは、ロープを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Battling Ropes is an effective exercise targeting the forearms using rope.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."]', 'images/0128-RJa4tCo.jpg', 'videos/0128-RJa4tCo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3360', 'bear-crawl', 'Bear Crawl', 'Bear Crawl', 'Bear Crawlは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Bear Crawl is an effective exercise targeting the core using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."]', 'images/3360-0Yz8WdV.jpg', 'videos/3360-0Yz8WdV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1259', 'behind-head-chest-stretch', 'Behind Head チェスト ストレッチ', 'Behind Head Chest Stretch', 'Behind Head チェスト ストレッチは、アシストマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Behind Head Chest Stretch is an effective exercise targeting the shoulders using assisted.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."]', 'images/1259-QoHIhPl.jpg', 'videos/1259-QoHIhPl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0129', 'bench-dip-knees-bent', 'ベンチ ディップス (knees Bent)', 'Bench Dip (knees Bent)', 'ベンチ ディップス (knees Bent)は、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Bench Dip (knees Bent) is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0129-RrLske5.jpg', 'videos/0129-RrLske5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1399', 'bench-dip-on-floor', 'ベンチ ディップス On Floor', 'Bench Dip On Floor', 'ベンチ ディップス On Floorは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Bench Dip On Floor is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/1399-9RT8oQW.jpg', 'videos/1399-9RT8oQW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0130', 'bench-hip-extension', 'ベンチ ヒップ エクステンション', 'Bench Hip Extension', 'ベンチ ヒップ エクステンションは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Bench Hip Extension is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0130-u27Kcdz.jpg', 'videos/0130-u27Kcdz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3019', 'bench-pull-ups', 'ベンチ Pull-ups', 'Bench Pull-ups', 'ベンチ Pull-upsは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bench Pull-ups is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."]', 'images/3019-mExgrF9.jpg', 'videos/3019-mExgrF9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3639', 'bent-knee-lying-twist-male', 'Bent Knee ライイング ツイスト (male)', 'Bent Knee Lying Twist (male)', 'Bent Knee ライイング ツイスト (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Bent Knee Lying Twist (male) is an effective exercise targeting the obliques using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/3639-6sYyrRX.jpg', 'videos/3639-6sYyrRX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1770', 'biceps-leg-concentration-curl', 'バイセップス Leg Concentration カール', 'Biceps Leg Concentration Curl', 'バイセップス Leg Concentration カールは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Biceps Leg Concentration Curl is an effective exercise targeting the forearms using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1770-sJFIDIp.jpg', 'videos/1770-sJFIDIp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0139', 'biceps-narrow-pull-ups', 'バイセップス Narrow Pull-ups', 'Biceps Narrow Pull-ups', 'バイセップス Narrow Pull-upsは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Biceps Narrow Pull-ups is an effective exercise targeting the forearms using body weight.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0139-50BETrz.jpg', 'videos/0139-50BETrz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0140', 'biceps-pull-up', 'バイセップス プルアップ', 'Biceps Pull-up', 'バイセップス プルアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Biceps Pull-up is an effective exercise targeting the forearms using body weight.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0140-guT8YnS.jpg', 'videos/0140-guT8YnS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0137', 'body-up', 'Body-up', 'Body-up', 'Body-upは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Body-up is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0137-U6G2gk9.jpg', 'videos/0137-U6G2gk9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3543', 'bodyweight-drop-jump-squat', '自重 Drop Jump スクワット', 'Bodyweight Drop Jump Squat', '自重 Drop Jump スクワットは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Drop Jump Squat is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."]', 'images/3543-wfotm7S.jpg', 'videos/3543-wfotm7S.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3544', 'bodyweight-incline-side-plank', '自重 インクライン Side プランク', 'Bodyweight Incline Side Plank', '自重 インクライン Side プランクは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Incline Side Plank is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."]', 'images/3544-5VXmnV5.jpg', 'videos/3544-5VXmnV5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1771', 'bodyweight-kneeling-triceps-extension', '自重 ニーリング トライセップス エクステンション', 'Bodyweight Kneeling Triceps Extension', '自重 ニーリング トライセップス エクステンションは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Kneeling Triceps Extension is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1771-s0HKO2I.jpg', 'videos/1771-s0HKO2I.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1769', 'bodyweight-side-lying-biceps-curl', '自重 Side ライイング バイセップス カール', 'Bodyweight Side Lying Biceps Curl', '自重 Side ライイング バイセップス カールは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Side Lying Biceps Curl is an effective exercise targeting the forearms using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1769-gscGLOU.jpg', 'videos/1769-gscGLOU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3168', 'bodyweight-squatting-row', '自重 Squatting ロー', 'Bodyweight Squatting Row', '自重 Squatting ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Squatting Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3168-3xK09Sk.jpg', 'videos/3168-3xK09Sk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3167', 'bodyweight-squatting-row-with-towel', '自重 Squatting ロー (with タオル)', 'Bodyweight Squatting Row (with Towel)', '自重 Squatting ロー (with タオル)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Squatting Row (with Towel) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."]', 'images/3167-BReCuOn.jpg', 'videos/3167-BReCuOn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1373', 'bodyweight-standing-calf-raise', '自重 スタンディング カーフ レイズ', 'Bodyweight Standing Calf Raise', '自重 スタンディング カーフ レイズは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing Calf Raise is an effective exercise targeting the ankles using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1373-bJYHBIN.jpg', 'videos/1373-bJYHBIN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3156', 'bodyweight-standing-close-grip-one-arm-row', '自重 スタンディング ナローグリップ ワンハンド ロー', 'Bodyweight Standing Close-grip One Arm Row', '自重 スタンディング ナローグリップ ワンハンド ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing Close-grip One Arm Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/3156-v2DfH14.jpg', 'videos/3156-v2DfH14.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3158', 'bodyweight-standing-close-grip-row', '自重 スタンディング ナローグリップ ロー', 'Bodyweight Standing Close-grip Row', '自重 スタンディング ナローグリップ ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing Close-grip Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3158-tig3PXb.jpg', 'videos/3158-tig3PXb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3162', 'bodyweight-standing-one-arm-row', '自重 スタンディング ワンハンド ロー', 'Bodyweight Standing One Arm Row', '自重 スタンディング ワンハンド ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing One Arm Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/3162-xbkPfaw.jpg', 'videos/3162-xbkPfaw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3161', 'bodyweight-standing-one-arm-row-with-towel', '自重 スタンディング ワンハンド ロー (with タオル)', 'Bodyweight Standing One Arm Row (with Towel)', '自重 スタンディング ワンハンド ロー (with タオル)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing One Arm Row (with Towel) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/3161-O4oIqQD.jpg', 'videos/3161-O4oIqQD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3166', 'bodyweight-standing-row', '自重 スタンディング ロー', 'Bodyweight Standing Row', '自重 スタンディング ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3166-wd4ds3s.jpg', 'videos/3166-wd4ds3s.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3165', 'bodyweight-standing-row-with-towel', '自重 スタンディング ロー (with タオル)', 'Bodyweight Standing Row (with Towel)', '自重 スタンディング ロー (with タオル)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Bodyweight Standing Row (with Towel) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3165-uTv34oq.jpg', 'videos/3165-uTv34oq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0138', 'bottoms-up', 'Bottoms-up', 'Bottoms-up', 'Bottoms-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Bottoms-up is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0138-CI6baTY.jpg', 'videos/0138-CI6baTY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1374', 'box-jump-down-with-one-leg-stabilization', 'Box Jump Down With One Leg Stabilization', 'Box Jump Down With One Leg Stabilization', 'Box Jump Down With One Leg Stabilizationは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Box Jump Down With One Leg Stabilization is an effective exercise targeting the quadriceps using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."]', 'images/1374-iPm26QU.jpg', 'videos/1374-iPm26QU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2466', 'bridge-mountain-climber-cross-body', 'Bridge - Mountain Climber (cross Body)', 'Bridge - Mountain Climber (cross Body)', 'Bridge - Mountain Climber (cross Body)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Bridge - Mountain Climber (cross Body) is an effective exercise targeting the glutes using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."]', 'images/2466-9c6T1YX.jpg', 'videos/2466-9c6T1YX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1160', 'burpee', 'Burpee', 'Burpee', 'Burpeeは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Burpee is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."]', 'images/1160-dK9394r.jpg', 'videos/1160-dK9394r.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0870', 'butt-ups', 'Butt-ups', 'Butt-ups', 'Butt-upsは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Butt-ups is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0870-qcNN2FN.jpg', 'videos/0870-qcNN2FN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1494', 'butterfly-yoga-pose', 'Butterfly Yoga Pose', 'Butterfly Yoga Pose', 'Butterfly Yoga Poseは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Butterfly Yoga Pose is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."]', 'images/1494-bWlZvXh.jpg', 'videos/1494-bWlZvXh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0148', 'cable-alternate-shoulder-press', 'ケーブル Alternate Shoulder プレス', 'Cable Alternate Shoulder Press', 'ケーブル Alternate Shoulder プレスは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Alternate Shoulder Press is an effective exercise targeting the triceps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', 'images/0148-KHPZL0b.jpg', 'videos/0148-KHPZL0b.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0149', 'cable-alternate-triceps-extension', 'ケーブル Alternate トライセップス エクステンション', 'Cable Alternate Triceps Extension', 'ケーブル Alternate トライセップス エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Alternate Triceps Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0149-Gchi5Tr.jpg', 'videos/0149-Gchi5Tr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3235', 'cable-assisted-inverse-leg-curl', 'ケーブル アシスト Inverse Leg カール', 'Cable Assisted Inverse Leg Curl', 'ケーブル アシスト Inverse Leg カールは、ケーブルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Cable Assisted Inverse Leg Curl is an effective exercise targeting the glutes using cable.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3235-zHEpuuc.jpg', 'videos/3235-zHEpuuc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0150', 'cable-bar-lateral-pulldown', 'ケーブル Bar サイド プルダウン', 'Cable Bar Lateral Pulldown', 'ケーブル Bar サイド プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Bar Lateral Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/0150-eYnzaCm.jpg', 'videos/0150-eYnzaCm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0151', 'cable-bench-press', 'ケーブル ベンチプレス', 'Cable Bench Press', 'ケーブル ベンチプレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Bench Press is an effective exercise targeting the triceps using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0151-7xI5MXA.jpg', 'videos/0151-7xI5MXA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1630', 'cable-close-grip-curl', 'ケーブル Close Grip カール', 'Cable Close Grip Curl', 'ケーブル Close Grip カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Close Grip Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1630-BCGQ6J5.jpg', 'videos/1630-BCGQ6J5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1631', 'cable-concentration-curl', 'ケーブル Concentration カール', 'Cable Concentration Curl', 'ケーブル Concentration カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Concentration Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1631-NvfE43H.jpg', 'videos/1631-NvfE43H.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0152', 'cable-concentration-extension-on-knee', 'ケーブル Concentration エクステンション (on Knee)', 'Cable Concentration Extension (on Knee)', 'ケーブル Concentration エクステンション (on Knee)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Concentration Extension (on Knee) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0152-Db7eEgw.jpg', 'videos/0152-Db7eEgw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0153', 'cable-cross-over-lateral-pulldown', 'ケーブル Cross-over サイド プルダウン', 'Cable Cross-over Lateral Pulldown', 'ケーブル Cross-over サイド プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Cross-over Lateral Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0153-OQ1otBN.jpg', 'videos/0153-OQ1otBN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0154', 'cable-cross-over-revers-fly', 'ケーブル Cross-over Revers フライ', 'Cable Cross-over Revers Fly', 'ケーブル Cross-over Revers フライは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Cross-over Revers Fly is an effective exercise targeting the rhomboids using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0154-aqvSOQE.jpg', 'videos/0154-aqvSOQE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0155', 'cable-cross-over-variation', 'ケーブル Cross-over Variation', 'Cable Cross-over Variation', 'ケーブル Cross-over Variationは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Cross-over Variation is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0155-0CXGHya.jpg', 'videos/0155-0CXGHya.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0868', 'cable-curl', 'ケーブル カール', 'Cable Curl', 'ケーブル カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0868-G08RZcQ.jpg', 'videos/0868-G08RZcQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0157', 'cable-deadlift', 'ケーブル デッドリフト', 'Cable Deadlift', 'ケーブル デッドリフトは、ケーブルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Cable Deadlift is an effective exercise targeting the hamstrings using cable.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0157-eGDudUV.jpg', 'videos/0157-eGDudUV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0158', 'cable-decline-fly', 'ケーブル デクライン フライ', 'Cable Decline Fly', 'ケーブル デクライン フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Decline Fly is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0158-7saC5zz.jpg', 'videos/0158-7saC5zz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1260', 'cable-decline-one-arm-press', 'ケーブル デクライン ワンハンド プレス', 'Cable Decline One Arm Press', 'ケーブル デクライン ワンハンド プレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Decline One Arm Press is an effective exercise targeting the triceps using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1260-KHGNa16.jpg', 'videos/1260-KHGNa16.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1261', 'cable-decline-press', 'ケーブル デクライン プレス', 'Cable Decline Press', 'ケーブル デクライン プレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Decline Press is an effective exercise targeting the triceps using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1261-2Pya1cP.jpg', 'videos/1261-2Pya1cP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0159', 'cable-decline-seated-wide-grip-row', 'ケーブル デクライン シーテッド ワイドグリップ ロー', 'Cable Decline Seated Wide-grip Row', 'ケーブル デクライン シーテッド ワイドグリップ ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Decline Seated Wide-grip Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0159-kesXOpB.jpg', 'videos/0159-kesXOpB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1632', 'cable-drag-curl', 'ケーブル Drag カール', 'Cable Drag Curl', 'ケーブル Drag カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Drag Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1632-dXz8zjF.jpg', 'videos/1632-dXz8zjF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0160', 'cable-floor-seated-wide-grip-row', 'ケーブル Floor シーテッド ワイドグリップ ロー', 'Cable Floor Seated Wide-grip Row', 'ケーブル Floor シーテッド ワイドグリップ ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Floor Seated Wide-grip Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0160-veXwo0D.jpg', 'videos/0160-veXwo0D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0161', 'cable-forward-raise', 'ケーブル Forward レイズ', 'Cable Forward Raise', 'ケーブル Forward レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Forward Raise is an effective exercise targeting the triceps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0161-hvHhCv8.jpg', 'videos/0161-hvHhCv8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0162', 'cable-front-raise', 'ケーブル フロント レイズ', 'Cable Front Raise', 'ケーブル フロント レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Front Raise is an effective exercise targeting the triceps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0162-u2X71Np.jpg', 'videos/0162-u2X71Np.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0164', 'cable-front-shoulder-raise', 'ケーブル フロント Shoulder レイズ', 'Cable Front Shoulder Raise', 'ケーブル フロント Shoulder レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Front Shoulder Raise is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0164-mTT3KLn.jpg', 'videos/0164-mTT3KLn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0165', 'cable-hammer-curl-with-rope', 'ケーブル ハンマー カール (with Rope)', 'Cable Hammer Curl (with Rope)', 'ケーブル ハンマー カール (with Rope)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Hammer Curl (with Rope) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0165-HPlPoQA.jpg', 'videos/0165-HPlPoQA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1722', 'cable-high-pulley-overhead-tricep-extension', 'ケーブル High Pulley オーバーヘッド Tricep エクステンション', 'Cable High Pulley Overhead Tricep Extension', 'ケーブル High Pulley オーバーヘッド Tricep エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable High Pulley Overhead Tricep Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1722-1xHyxys.jpg', 'videos/1722-1xHyxys.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0167', 'cable-high-row-kneeling', 'ケーブル High ロー (ニーリング)', 'Cable High Row (kneeling)', 'ケーブル High ロー (ニーリング)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable High Row (kneeling) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0167-ZSJNetl.jpg', 'videos/0167-ZSJNetl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0168', 'cable-hip-adduction', 'ケーブル ヒップ Adduction', 'Cable Hip Adduction', 'ケーブル ヒップ Adductionは、ケーブルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Cable Hip Adduction is an effective exercise targeting the glutes using cable.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0168-hBGWILP.jpg', 'videos/0168-hBGWILP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0169', 'cable-incline-bench-press', 'ケーブル インクライン ベンチプレス', 'Cable Incline Bench Press', 'ケーブル インクライン ベンチプレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Bench Press is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0169-Vh0GsK4.jpg', 'videos/0169-Vh0GsK4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1318', 'cable-incline-bench-row', 'ケーブル インクライン ベンチ ロー', 'Cable Incline Bench Row', 'ケーブル インクライン ベンチ ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Bench Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1318-yaMIo4D.jpg', 'videos/1318-yaMIo4D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0171', 'cable-incline-fly', 'ケーブル インクライン フライ', 'Cable Incline Fly', 'ケーブル インクライン フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Fly is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0171-tBWXbIT.jpg', 'videos/0171-tBWXbIT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0170', 'cable-incline-fly-on-stability-ball', 'ケーブル インクライン フライ (on Stability Ball)', 'Cable Incline Fly (on Stability Ball)', 'ケーブル インクライン フライ (on Stability Ball)は、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Fly (on Stability Ball) is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0170-27NNGFr.jpg', 'videos/0170-27NNGFr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0172', 'cable-incline-pushdown', 'ケーブル インクライン Pushdown', 'Cable Incline Pushdown', 'ケーブル インクライン Pushdownは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Pushdown is an effective exercise targeting the triceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/0172-1PK5Uo3.jpg', 'videos/0172-1PK5Uo3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0173', 'cable-incline-triceps-extension', 'ケーブル インクライン トライセップス エクステンション', 'Cable Incline Triceps Extension', 'ケーブル インクライン トライセップス エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Incline Triceps Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0173-Hx1WC8I.jpg', 'videos/0173-Hx1WC8I.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0174', 'cable-judo-flip', 'ケーブル Judo Flip', 'Cable Judo Flip', 'ケーブル Judo Flipは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Judo Flip is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0174-MvQPqVW.jpg', 'videos/0174-MvQPqVW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0860', 'cable-kickback', 'ケーブル キックバック', 'Cable Kickback', 'ケーブル キックバックは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Kickback is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0860-HEJ6DIX.jpg', 'videos/0860-HEJ6DIX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0175', 'cable-kneeling-crunch', 'ケーブル ニーリング クランチ', 'Cable Kneeling Crunch', 'ケーブル ニーリング クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Kneeling Crunch is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0175-WW95auq.jpg', 'videos/0175-WW95auq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3697', 'cable-kneeling-rear-delt-row-with-rope-male', 'ケーブル ニーリング リア Delt ロー (with Rope) (male)', 'Cable Kneeling Rear Delt Row (with Rope) (male)', 'ケーブル ニーリング リア Delt ロー (with Rope) (male)は、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Kneeling Rear Delt Row (with Rope) (male) is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3697-G61cXLk.jpg', 'videos/3697-G61cXLk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0176', 'cable-kneeling-triceps-extension', 'ケーブル ニーリング トライセップス エクステンション', 'Cable Kneeling Triceps Extension', 'ケーブル ニーリング トライセップス エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Kneeling Triceps Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."]', 'images/0176-KWdF2JI.jpg', 'videos/0176-KWdF2JI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2330', 'cable-lat-pulldown-full-range-of-motion', 'ケーブル ラットプルダウン Full Range Of Motion', 'Cable Lat Pulldown Full Range Of Motion', 'ケーブル ラットプルダウン Full Range Of Motionは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Lat Pulldown Full Range Of Motion is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2330-LEprlgG.jpg', 'videos/2330-LEprlgG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0177', 'cable-lateral-pulldown-with-rope-attachment', 'ケーブル サイド プルダウン (with Rope Attachment)', 'Cable Lateral Pulldown (with Rope Attachment)', 'ケーブル サイド プルダウン (with Rope Attachment)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Lateral Pulldown (with Rope Attachment) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0177-CuaWCmC.jpg', 'videos/0177-CuaWCmC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2616', 'cable-lateral-pulldown-with-v-bar', 'ケーブル サイド プルダウン With V-bar', 'Cable Lateral Pulldown With V-bar', 'ケーブル サイド プルダウン With V-barは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Lateral Pulldown With V-bar is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]', 'images/2616-4c9BhzB.jpg', 'videos/2616-4c9BhzB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0178', 'cable-lateral-raise', 'ケーブル サイド レイズ', 'Cable Lateral Raise', 'ケーブル サイド レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Lateral Raise is an effective exercise targeting the traps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0178-goJ6ezq.jpg', 'videos/0178-goJ6ezq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0179', 'cable-low-fly', 'ケーブル Low フライ', 'Cable Low Fly', 'ケーブル Low フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Low Fly is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."]', 'images/0179-FVmZVhk.jpg', 'videos/0179-FVmZVhk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0180', 'cable-low-seated-row', 'ケーブル Low シーテッド ロー', 'Cable Low Seated Row', 'ケーブル Low シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Low Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0180-hvV79Si.jpg', 'videos/0180-hvV79Si.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1634', 'cable-lying-bicep-curl', 'ケーブル ライイング Bicep カール', 'Cable Lying Bicep Curl', 'ケーブル ライイング Bicep カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Lying Bicep Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1634-otqIxU4.jpg', 'videos/1634-otqIxU4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0182', 'cable-lying-close-grip-curl', 'ケーブル ライイング ナローグリップ カール', 'Cable Lying Close-grip Curl', 'ケーブル ライイング ナローグリップ カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Lying Close-grip Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0182-61GrD55.jpg', 'videos/0182-61GrD55.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0184', 'cable-lying-extension-pullover-with-rope-attachment', 'ケーブル ライイング エクステンション プルオーバー (with Rope Attachment)', 'Cable Lying Extension Pullover (with Rope Attachment)', 'ケーブル ライイング エクステンション プルオーバー (with Rope Attachment)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Lying Extension Pullover (with Rope Attachment) is an effective exercise targeting the triceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0184-Q2Eu1Ax.jpg', 'videos/0184-Q2Eu1Ax.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0185', 'cable-lying-fly', 'ケーブル ライイング フライ', 'Cable Lying Fly', 'ケーブル ライイング フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Lying Fly is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0185-lJJ7Yq8.jpg', 'videos/0185-lJJ7Yq8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0186', 'cable-lying-triceps-extension-v-2', 'ケーブル ライイング トライセップス エクステンション V. 2', 'Cable Lying Triceps Extension V. 2', 'ケーブル ライイング トライセップス エクステンション V. 2は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Lying Triceps Extension V. 2 is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0186-uxJcFUU.jpg', 'videos/0186-uxJcFUU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0188', 'cable-middle-fly', 'ケーブル Middle フライ', 'Cable Middle Fly', 'ケーブル Middle フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Middle Fly is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0188-xLYSdtg.jpg', 'videos/0188-xLYSdtg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0189', 'cable-one-arm-bent-over-row', 'ケーブル ワンハンド Bent Over ロー', 'Cable One Arm Bent Over Row', 'ケーブル ワンハンド Bent Over ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Bent Over Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0189-EIsE3u8.jpg', 'videos/0189-EIsE3u8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0190', 'cable-one-arm-curl', 'ケーブル ワンハンド カール', 'Cable One Arm Curl', 'ケーブル ワンハンド カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0190-YTur5nR.jpg', 'videos/0190-YTur5nR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1262', 'cable-one-arm-decline-chest-fly', 'ケーブル ワンハンド デクライン チェスト フライ', 'Cable One Arm Decline Chest Fly', 'ケーブル ワンハンド デクライン チェスト フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Decline Chest Fly is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]', 'images/1262-w4dLzSx.jpg', 'videos/1262-w4dLzSx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1263', 'cable-one-arm-fly-on-exercise-ball', 'ケーブル ワンハンド フライ On Exercise Ball', 'Cable One Arm Fly On Exercise Ball', 'ケーブル ワンハンド フライ On Exercise Ballは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Fly On Exercise Ball is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1263-hHy8tQG.jpg', 'videos/1263-hHy8tQG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1264', 'cable-one-arm-incline-fly-on-exercise-ball', 'ケーブル ワンハンド インクライン フライ On Exercise Ball', 'Cable One Arm Incline Fly On Exercise Ball', 'ケーブル ワンハンド インクライン フライ On Exercise Ballは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Incline Fly On Exercise Ball is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1264-P14Dz9D.jpg', 'videos/1264-P14Dz9D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1265', 'cable-one-arm-incline-press', 'ケーブル ワンハンド インクライン プレス', 'Cable One Arm Incline Press', 'ケーブル ワンハンド インクライン プレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Incline Press is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1265-GKEH6jj.jpg', 'videos/1265-GKEH6jj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1266', 'cable-one-arm-incline-press-on-exercise-ball', 'ケーブル ワンハンド インクライン プレス On Exercise Ball', 'Cable One Arm Incline Press On Exercise Ball', 'ケーブル ワンハンド インクライン プレス On Exercise Ballは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Incline Press On Exercise Ball is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1266-6t00BsF.jpg', 'videos/1266-6t00BsF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0191', 'cable-one-arm-lateral-bent-over', 'ケーブル ワンハンド サイド Bent-over', 'Cable One Arm Lateral Bent-over', 'ケーブル ワンハンド サイド Bent-overは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Lateral Bent-over is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0191-dB07vDu.jpg', 'videos/0191-dB07vDu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0192', 'cable-one-arm-lateral-raise', 'ケーブル ワンハンド サイド レイズ', 'Cable One Arm Lateral Raise', 'ケーブル ワンハンド サイド レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Lateral Raise is an effective exercise targeting the traps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0192-wEulIzp.jpg', 'videos/0192-wEulIzp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1633', 'cable-one-arm-preacher-curl', 'ケーブル ワンハンド Preacher カール', 'Cable One Arm Preacher Curl', 'ケーブル ワンハンド Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', 'images/1633-eHBlPsa.jpg', 'videos/1633-eHBlPsa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1267', 'cable-one-arm-press-on-exercise-ball', 'ケーブル ワンハンド プレス On Exercise Ball', 'Cable One Arm Press On Exercise Ball', 'ケーブル ワンハンド プレス On Exercise Ballは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Press On Exercise Ball is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1267-MKIelrR.jpg', 'videos/1267-MKIelrR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3563', 'cable-one-arm-pulldown', 'ケーブル ワンハンド プルダウン', 'Cable One Arm Pulldown', 'ケーブル ワンハンド プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', 'images/3563-U5INZY6.jpg', 'videos/3563-U5INZY6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1635', 'cable-one-arm-reverse-preacher-curl', 'ケーブル ワンハンド Reverse Preacher カール', 'Cable One Arm Reverse Preacher Curl', 'ケーブル ワンハンド Reverse Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Reverse Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', 'images/1635-ZXnjcOQ.jpg', 'videos/1635-ZXnjcOQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0193', 'cable-one-arm-straight-back-high-row-kneeling', 'ケーブル ワンハンド Straight バック High ロー (ニーリング)', 'Cable One Arm Straight Back High Row (kneeling)', 'ケーブル ワンハンド Straight バック High ロー (ニーリング)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Straight Back High Row (kneeling) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', 'images/0193-WrYPP2g.jpg', 'videos/0193-WrYPP2g.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1723', 'cable-one-arm-tricep-pushdown', 'ケーブル ワンハンド Tricep Pushdown', 'Cable One Arm Tricep Pushdown', 'ケーブル ワンハンド Tricep Pushdownは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable One Arm Tricep Pushdown is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1723-qRZ5S1N.jpg', 'videos/1723-qRZ5S1N.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1636', 'cable-overhead-curl', 'ケーブル オーバーヘッド カール', 'Cable Overhead Curl', 'ケーブル オーバーヘッド カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Overhead Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1636-wDUqY2u.jpg', 'videos/1636-wDUqY2u.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1637', 'cable-overhead-curl-on-exercise-ball', 'ケーブル オーバーヘッド カール On Exercise Ball', 'Cable Overhead Curl On Exercise Ball', 'ケーブル オーバーヘッド カール On Exercise Ballは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Overhead Curl On Exercise Ball is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1637-ioTf098.jpg', 'videos/1637-ioTf098.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0194', 'cable-overhead-triceps-extension-rope-attachment', 'ケーブル オーバーヘッド トライセップス エクステンション (rope Attachment)', 'Cable Overhead Triceps Extension (rope Attachment)', 'ケーブル オーバーヘッド トライセップス エクステンション (rope Attachment)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Overhead Triceps Extension (rope Attachment) is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0194-2IxROQ1.jpg', 'videos/0194-2IxROQ1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1319', 'cable-palm-rotational-row', 'ケーブル Palm Rotational ロー', 'Cable Palm Rotational Row', 'ケーブル Palm Rotational ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Palm Rotational Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1319-OmQ8w0p.jpg', 'videos/1319-OmQ8w0p.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0195', 'cable-preacher-curl', 'ケーブル Preacher カール', 'Cable Preacher Curl', 'ケーブル Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0195-P2lNrGL.jpg', 'videos/0195-P2lNrGL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1268', 'cable-press-on-exercise-ball', 'ケーブル プレス On Exercise Ball', 'Cable Press On Exercise Ball', 'ケーブル プレス On Exercise Ballは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Press On Exercise Ball is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1268-vAwm6rK.jpg', 'videos/1268-vAwm6rK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0196', 'cable-pull-through-with-rope', 'ケーブル Pull Through (with Rope)', 'Cable Pull Through (with Rope)', 'ケーブル Pull Through (with Rope)は、ケーブルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Cable Pull Through (with Rope) is an effective exercise targeting the hamstrings using cable.', 'mg-glutes', 'Beginner', 'compound', 'pull', 'lower', '["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0196-OM46QHm.jpg', 'videos/0196-OM46QHm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0198', 'cable-pulldown', 'ケーブル プルダウン', 'Cable Pulldown', 'ケーブル プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0198-RVwzP10.jpg', 'videos/0198-RVwzP10.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0197', 'cable-pulldown-pro-lat-bar', 'ケーブル プルダウン (pro Lat Bar)', 'Cable Pulldown (pro Lat Bar)', 'ケーブル プルダウン (pro Lat Bar)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Pulldown (pro Lat Bar) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0197-qdRxqCj.jpg', 'videos/0197-qdRxqCj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1638', 'cable-pulldown-bicep-curl', 'ケーブル プルダウン Bicep カール', 'Cable Pulldown Bicep Curl', 'ケーブル プルダウン Bicep カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Pulldown Bicep Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1638-QTXKWPh.jpg', 'videos/1638-QTXKWPh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0201', 'cable-pushdown', 'ケーブル Pushdown', 'Cable Pushdown', 'ケーブル Pushdownは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Pushdown is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/0201-3ZflifB.jpg', 'videos/0201-3ZflifB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0199', 'cable-pushdown-straight-arm-v-2', 'ケーブル Pushdown (straight Arm) V. 2', 'Cable Pushdown (straight Arm) V. 2', 'ケーブル Pushdown (straight Arm) V. 2は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Pushdown (straight Arm) V. 2 is an effective exercise targeting the triceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."]', 'images/0199-PskORrA.jpg', 'videos/0199-PskORrA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0200', 'cable-pushdown-with-rope-attachment', 'ケーブル Pushdown (with Rope Attachment)', 'Cable Pushdown (with Rope Attachment)', 'ケーブル Pushdown (with Rope Attachment)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Pushdown (with Rope Attachment) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."]', 'images/0200-dU605di.jpg', 'videos/0200-dU605di.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0202', 'cable-rear-delt-row-stirrups', 'ケーブル リア Delt ロー (stirrups)', 'Cable Rear Delt Row (stirrups)', 'ケーブル リア Delt ロー (stirrups)は、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Rear Delt Row (stirrups) is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."]', 'images/0202-yUdIGNs.jpg', 'videos/0202-yUdIGNs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0203', 'cable-rear-delt-row-with-rope', 'ケーブル リア Delt ロー (with Rope)', 'Cable Rear Delt Row (with Rope)', 'ケーブル リア Delt ロー (with Rope)は、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Rear Delt Row (with Rope) is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0203-wqNPGCg.jpg', 'videos/0203-wqNPGCg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0204', 'cable-rear-drive', 'ケーブル リア Drive', 'Cable Rear Drive', 'ケーブル リア Driveは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rear Drive is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."]', 'images/0204-c3QQLPi.jpg', 'videos/0204-c3QQLPi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0205', 'cable-rear-pulldown', 'ケーブル リア プルダウン', 'Cable Rear Pulldown', 'ケーブル リア プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Rear Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0205-SpsOSXk.jpg', 'videos/0205-SpsOSXk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0873', 'cable-reverse-crunch', 'ケーブル Reverse クランチ', 'Cable Reverse Crunch', 'ケーブル Reverse クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse Crunch is an effective exercise targeting the hip flexors using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0873-RqOtqD7.jpg', 'videos/0873-RqOtqD7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0206', 'cable-reverse-curl', 'ケーブル Reverse カール', 'Cable Reverse Curl', 'ケーブル Reverse カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0206-eOG0r6v.jpg', 'videos/0206-eOG0r6v.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2406', 'cable-reverse-grip-triceps-pushdown-sz-bar-with-arm-blaster', 'ケーブル Reverse Grip トライセップス Pushdown (sz-bar) (with Arm Blaster)', 'Cable Reverse Grip Triceps Pushdown (sz-bar) (with Arm Blaster)', 'ケーブル Reverse Grip トライセップス Pushdown (sz-bar) (with Arm Blaster)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse Grip Triceps Pushdown (sz-bar) (with Arm Blaster) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/2406-ThKP69G.jpg', 'videos/2406-ThKP69G.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1413', 'cable-reverse-one-arm-curl', 'ケーブル Reverse ワンハンド カール', 'Cable Reverse One Arm Curl', 'ケーブル Reverse ワンハンド カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse One Arm Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1413-gVlnLIJ.jpg', 'videos/1413-gVlnLIJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0209', 'cable-reverse-preacher-curl', 'ケーブル Reverse Preacher カール', 'Cable Reverse Preacher Curl', 'ケーブル Reverse Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', 'images/0209-IwX5NqK.jpg', 'videos/0209-IwX5NqK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0210', 'cable-reverse-wrist-curl', 'ケーブル Reverse リスト カール', 'Cable Reverse Wrist Curl', 'ケーブル Reverse リスト カールは、ケーブルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse Wrist Curl is an effective exercise targeting the forearms using cable.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0210-eYmsEPR.jpg', 'videos/0210-eYmsEPR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0207', 'cable-reverse-grip-pushdown', 'ケーブル リバースグリップ Pushdown', 'Cable Reverse-grip Pushdown', 'ケーブル リバースグリップ Pushdownは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse-grip Pushdown is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/0207-VjYliFZ.jpg', 'videos/0207-VjYliFZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0208', 'cable-reverse-grip-straight-back-seated-high-row', 'ケーブル リバースグリップ Straight バック シーテッド High ロー', 'Cable Reverse-grip Straight Back Seated High Row', 'ケーブル リバースグリップ Straight バック シーテッド High ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Reverse-grip Straight Back Seated High Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0208-PNtsX17.jpg', 'videos/0208-PNtsX17.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1320', 'cable-rope-crossover-seated-row', 'ケーブル Rope クロスオーバー シーテッド ロー', 'Cable Rope Crossover Seated Row', 'ケーブル Rope クロスオーバー シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Crossover Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1320-UFGF6gk.jpg', 'videos/1320-UFGF6gk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1321', 'cable-rope-elevated-seated-row', 'ケーブル Rope Elevated シーテッド ロー', 'Cable Rope Elevated Seated Row', 'ケーブル Rope Elevated シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Elevated Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1321-c8oybX6.jpg', 'videos/1321-c8oybX6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1322', 'cable-rope-extension-incline-bench-row', 'ケーブル Rope エクステンション インクライン ベンチ ロー', 'Cable Rope Extension Incline Bench Row', 'ケーブル Rope エクステンション インクライン ベンチ ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Extension Incline Bench Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1322-MgKwAAo.jpg', 'videos/1322-MgKwAAo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1639', 'cable-rope-hammer-preacher-curl', 'ケーブル Rope ハンマー Preacher カール', 'Cable Rope Hammer Preacher Curl', 'ケーブル Rope ハンマー Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Hammer Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1639-PcPe0P5.jpg', 'videos/1639-PcPe0P5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1724', 'cable-rope-high-pulley-overhead-tricep-extension', 'ケーブル Rope High Pulley オーバーヘッド Tricep エクステンション', 'Cable Rope High Pulley Overhead Tricep Extension', 'ケーブル Rope High Pulley オーバーヘッド Tricep エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rope High Pulley Overhead Tricep Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1724-NN8nSNT.jpg', 'videos/1724-NN8nSNT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1725', 'cable-rope-incline-tricep-extension', 'ケーブル Rope インクライン Tricep エクステンション', 'Cable Rope Incline Tricep Extension', 'ケーブル Rope インクライン Tricep エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Incline Tricep Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1725-ZujAdR9.jpg', 'videos/1725-ZujAdR9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1726', 'cable-rope-lying-on-floor-tricep-extension', 'ケーブル Rope ライイング On Floor Tricep エクステンション', 'Cable Rope Lying On Floor Tricep Extension', 'ケーブル Rope ライイング On Floor Tricep エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Lying On Floor Tricep Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1726-U3ffHlY.jpg', 'videos/1726-U3ffHlY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1640', 'cable-rope-one-arm-hammer-preacher-curl', 'ケーブル Rope ワンハンド ハンマー Preacher カール', 'Cable Rope One Arm Hammer Preacher Curl', 'ケーブル Rope ワンハンド ハンマー Preacher カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Rope One Arm Hammer Preacher Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1640-4hATdoB.jpg', 'videos/1640-4hATdoB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1323', 'cable-rope-seated-row', 'ケーブル Rope シーテッド ロー', 'Cable Rope Seated Row', 'ケーブル Rope シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Rope Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1323-SJqRxOt.jpg', 'videos/1323-SJqRxOt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0211', 'cable-russian-twists-on-stability-ball', 'ケーブル Russian Twists (on Stability Ball)', 'Cable Russian Twists (on Stability Ball)', 'ケーブル Russian Twists (on Stability Ball)は、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Russian Twists (on Stability Ball) is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."]', 'images/0211-d9Xaxq6.jpg', 'videos/0211-d9Xaxq6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2144', 'cable-seated-chest-press', 'ケーブル シーテッド チェスト プレス', 'Cable Seated Chest Press', 'ケーブル シーテッド チェスト プレスは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Chest Press is an effective exercise targeting the shoulders using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2144-nIR4Rwl.jpg', 'videos/2144-nIR4Rwl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0212', 'cable-seated-crunch', 'ケーブル シーテッド クランチ', 'Cable Seated Crunch', 'ケーブル シーテッド クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Crunch is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0212-8xUv4J7.jpg', 'videos/0212-8xUv4J7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1641', 'cable-seated-curl', 'ケーブル シーテッド カール', 'Cable Seated Curl', 'ケーブル シーテッド カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1641-8oYqOt9.jpg', 'videos/1641-8oYqOt9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0213', 'cable-seated-high-row-v-bar', 'ケーブル シーテッド High ロー (v-bar)', 'Cable Seated High Row (v-bar)', 'ケーブル シーテッド High ロー (v-bar)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Seated High Row (v-bar) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0213-pwt0pnM.jpg', 'videos/0213-pwt0pnM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0214', 'cable-seated-one-arm-alternate-row', 'ケーブル シーテッド ワンハンド Alternate ロー', 'Cable Seated One Arm Alternate Row', 'ケーブル シーテッド ワンハンド Alternate ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Seated One Arm Alternate Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', 'images/0214-vpp9Ku2.jpg', 'videos/0214-vpp9Ku2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1642', 'cable-seated-one-arm-concentration-curl', 'ケーブル シーテッド ワンハンド Concentration カール', 'Cable Seated One Arm Concentration Curl', 'ケーブル シーテッド ワンハンド Concentration カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Seated One Arm Concentration Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1642-rZ80Gbp.jpg', 'videos/1642-rZ80Gbp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1643', 'cable-seated-overhead-curl', 'ケーブル シーテッド オーバーヘッド カール', 'Cable Seated Overhead Curl', 'ケーブル シーテッド オーバーヘッド カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Overhead Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1643-DpWMFP5.jpg', 'videos/1643-DpWMFP5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0215', 'cable-seated-rear-lateral-raise', 'ケーブル シーテッド リア サイド レイズ', 'Cable Seated Rear Lateral Raise', 'ケーブル シーテッド リア サイド レイズは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Rear Lateral Raise is an effective exercise targeting the traps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0215-x825CZm.jpg', 'videos/0215-x825CZm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0861', 'cable-seated-row', 'ケーブル シーテッド ロー', 'Cable Seated Row', 'ケーブル シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0861-fUBheHs.jpg', 'videos/0861-fUBheHs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0216', 'cable-seated-shoulder-internal-rotation', 'ケーブル シーテッド Shoulder Internal Rotation', 'Cable Seated Shoulder Internal Rotation', 'ケーブル シーテッド Shoulder Internal Rotationは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Shoulder Internal Rotation is an effective exercise targeting the rotator cuff using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0216-YPoVrBi.jpg', 'videos/0216-YPoVrBi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2399', 'cable-seated-twist', 'ケーブル シーテッド ツイスト', 'Cable Seated Twist', 'ケーブル シーテッド ツイストは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Twist is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/2399-UEjSrKI.jpg', 'videos/2399-UEjSrKI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0218', 'cable-seated-wide-grip-row', 'ケーブル シーテッド ワイドグリップ ロー', 'Cable Seated Wide-grip Row', 'ケーブル シーテッド ワイドグリップ ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Seated Wide-grip Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0218-qcY50ZD.jpg', 'videos/0218-qcY50ZD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0219', 'cable-shoulder-press', 'ケーブル Shoulder プレス', 'Cable Shoulder Press', 'ケーブル Shoulder プレスは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Shoulder Press is an effective exercise targeting the triceps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0219-PzQanLE.jpg', 'videos/0219-PzQanLE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0220', 'cable-shrug', 'ケーブル シュラッグ', 'Cable Shrug', 'ケーブル シュラッグは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Shrug is an effective exercise targeting the shoulders using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0220-Eg98Ft9.jpg', 'videos/0220-Eg98Ft9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0222', 'cable-side-bend', 'ケーブル Side Bend', 'Cable Side Bend', 'ケーブル Side Bendは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Side Bend is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."]', 'images/0222-wPypxFY.jpg', 'videos/0222-wPypxFY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0221', 'cable-side-bend-crunch-bosu-ball', 'ケーブル Side Bend クランチ (bosu Ball)', 'Cable Side Bend Crunch (bosu Ball)', 'ケーブル Side Bend クランチ (bosu Ball)は、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Side Bend Crunch (bosu Ball) is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0221-qatbkEd.jpg', 'videos/0221-qatbkEd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0223', 'cable-side-crunch', 'ケーブル Side クランチ', 'Cable Side Crunch', 'ケーブル Side クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Side Crunch is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0223-q2ADGqV.jpg', 'videos/0223-q2ADGqV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1717', 'cable-squat-row-with-rope-attachment', 'ケーブル スクワット ロー (with Rope Attachment)', 'Cable Squat Row (with Rope Attachment)', 'ケーブル スクワット ロー (with Rope Attachment)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Squat Row (with Rope Attachment) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1717-f7fnAIB.jpg', 'videos/1717-f7fnAIB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1644', 'cable-squatting-curl', 'ケーブル Squatting カール', 'Cable Squatting Curl', 'ケーブル Squatting カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Squatting Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1644-3XFdb1Z.jpg', 'videos/1644-3XFdb1Z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0224', 'cable-standing-back-wrist-curl', 'ケーブル スタンディング バック リスト カール', 'Cable Standing Back Wrist Curl', 'ケーブル スタンディング バック リスト カールは、ケーブルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Back Wrist Curl is an effective exercise targeting the biceps using cable.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0224-VhX2JdE.jpg', 'videos/0224-VhX2JdE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1375', 'cable-standing-calf-raise', 'ケーブル スタンディング カーフ レイズ', 'Cable Standing Calf Raise', 'ケーブル スタンディング カーフ レイズは、ケーブルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Calf Raise is an effective exercise targeting the hamstrings using cable.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1375-yl2IYyy.jpg', 'videos/1375-yl2IYyy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0225', 'cable-standing-cross-over-high-reverse-fly', 'ケーブル スタンディング Cross-over High Reverse フライ', 'Cable Standing Cross-over High Reverse Fly', 'ケーブル スタンディング Cross-over High Reverse フライは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Cross-over High Reverse Fly is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0225-P5p0j8B.jpg', 'videos/0225-P5p0j8B.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0226', 'cable-standing-crunch', 'ケーブル スタンディング クランチ', 'Cable Standing Crunch', 'ケーブル スタンディング クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Crunch is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0226-jpgqxiS.jpg', 'videos/0226-jpgqxiS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0874', 'cable-standing-crunch-with-rope-attachment', 'ケーブル スタンディング クランチ (with Rope Attachment)', 'Cable Standing Crunch (with Rope Attachment)', 'ケーブル スタンディング クランチ (with Rope Attachment)は、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Crunch (with Rope Attachment) is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0874-XU3ePuv.jpg', 'videos/0874-XU3ePuv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0227', 'cable-standing-fly', 'ケーブル スタンディング フライ', 'Cable Standing Fly', 'ケーブル スタンディング フライは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Fly is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."]', 'images/0227-Pr9Rhf4.jpg', 'videos/0227-Pr9Rhf4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0228', 'cable-standing-hip-extension', 'ケーブル スタンディング ヒップ エクステンション', 'Cable Standing Hip Extension', 'ケーブル スタンディング ヒップ エクステンションは、ケーブルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Hip Extension is an effective exercise targeting the hamstrings using cable.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."]', 'images/0228-Kpajagk.jpg', 'videos/0228-Kpajagk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0229', 'cable-standing-inner-curl', 'ケーブル スタンディング Inner カール', 'Cable Standing Inner Curl', 'ケーブル スタンディング Inner カールは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Inner Curl is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0229-YwnI4ja.jpg', 'videos/0229-YwnI4ja.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0230', 'cable-standing-lift', 'ケーブル スタンディング Lift', 'Cable Standing Lift', 'ケーブル スタンディング Liftは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Lift is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0230-qFpAkpP.jpg', 'videos/0230-qFpAkpP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0231', 'cable-standing-one-arm-triceps-extension', 'ケーブル スタンディング ワンハンド トライセップス エクステンション', 'Cable Standing One Arm Triceps Extension', 'ケーブル スタンディング ワンハンド トライセップス エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Standing One Arm Triceps Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."]', 'images/0231-sYCcnon.jpg', 'videos/0231-sYCcnon.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1376', 'cable-standing-one-leg-calf-raise', 'ケーブル スタンディング One Leg カーフ レイズ', 'Cable Standing One Leg Calf Raise', 'ケーブル スタンディング One Leg カーフ レイズは、ケーブルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Cable Standing One Leg Calf Raise is an effective exercise targeting the ankles using cable.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/1376-fgc9Xdl.jpg', 'videos/1376-fgc9Xdl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0232', 'cable-standing-pulldown-with-rope', 'ケーブル スタンディング プルダウン (with Rope)', 'Cable Standing Pulldown (with Rope)', 'ケーブル スタンディング プルダウン (with Rope)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Pulldown (with Rope) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."]', 'images/0232-CvPn9WV.jpg', 'videos/0232-CvPn9WV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0233', 'cable-standing-rear-delt-row-with-rope', 'ケーブル スタンディング リア Delt ロー (with Rope)', 'Cable Standing Rear Delt Row (with Rope)', 'ケーブル スタンディング リア Delt ロー (with Rope)は、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Rear Delt Row (with Rope) is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0233-ZfyAGhK.jpg', 'videos/0233-ZfyAGhK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1727', 'cable-standing-reverse-grip-one-arm-overhead-tricep-extension', 'ケーブル スタンディング Reverse Grip ワンハンド オーバーヘッド Tricep エクステンション', 'Cable Standing Reverse Grip One Arm Overhead Tricep Extension', 'ケーブル スタンディング Reverse Grip ワンハンド オーバーヘッド Tricep エクステンションは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Reverse Grip One Arm Overhead Tricep Extension is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1727-i11JWU7.jpg', 'videos/1727-i11JWU7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0234', 'cable-standing-row-v-bar', 'ケーブル スタンディング ロー (v-bar)', 'Cable Standing Row (v-bar)', 'ケーブル スタンディング ロー (v-bar)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Row (v-bar) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0234-4f8RXP8.jpg', 'videos/0234-4f8RXP8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0235', 'cable-standing-shoulder-external-rotation', 'ケーブル スタンディング Shoulder External Rotation', 'Cable Standing Shoulder External Rotation', 'ケーブル スタンディング Shoulder External Rotationは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Shoulder External Rotation is an effective exercise targeting the rotator cuff using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0235-FWdVhcW.jpg', 'videos/0235-FWdVhcW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0236', 'cable-standing-twist-row-v-bar', 'ケーブル スタンディング ツイスト ロー (v-bar)', 'Cable Standing Twist Row (v-bar)', 'ケーブル スタンディング ツイスト ロー (v-bar)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Twist Row (v-bar) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]', 'images/0236-JOZhu2h.jpg', 'videos/0236-JOZhu2h.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1269', 'cable-standing-up-straight-crossovers', 'ケーブル スタンディング Up Straight Crossovers', 'Cable Standing Up Straight Crossovers', 'ケーブル スタンディング Up Straight Crossoversは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Standing Up Straight Crossovers is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."]', 'images/1269-UKWTJWR.jpg', 'videos/1269-UKWTJWR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0238', 'cable-straight-arm-pulldown', 'ケーブル Straight Arm プルダウン', 'Cable Straight Arm Pulldown', 'ケーブル Straight Arm プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Straight Arm Pulldown is an effective exercise targeting the shoulders using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', 'images/0238-x69MAlq.jpg', 'videos/0238-x69MAlq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0237', 'cable-straight-arm-pulldown-with-rope', 'ケーブル Straight Arm プルダウン (with Rope)', 'Cable Straight Arm Pulldown (with Rope)', 'ケーブル Straight Arm プルダウン (with Rope)は、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Straight Arm Pulldown (with Rope) is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0237-DT14T9T.jpg', 'videos/0237-DT14T9T.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0239', 'cable-straight-back-seated-row', 'ケーブル Straight バック シーテッド ロー', 'Cable Straight Back Seated Row', 'ケーブル Straight バック シーテッド ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Straight Back Seated Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0239-Tq6gbK6.jpg', 'videos/0239-Tq6gbK6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0240', 'cable-supine-reverse-fly', 'ケーブル Supine Reverse フライ', 'Cable Supine Reverse Fly', 'ケーブル Supine Reverse フライは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Supine Reverse Fly is an effective exercise targeting the trapezius using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0240-PQcUlDi.jpg', 'videos/0240-PQcUlDi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2464', 'cable-thibaudeau-kayak-row', 'ケーブル Thibaudeau Kayak ロー', 'Cable Thibaudeau Kayak Row', 'ケーブル Thibaudeau Kayak ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Thibaudeau Kayak Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]', 'images/2464-ZgwWBoC.jpg', 'videos/2464-ZgwWBoC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0241', 'cable-triceps-pushdown-v-bar', 'ケーブル トライセップス Pushdown (v-bar)', 'Cable Triceps Pushdown (v-bar)', 'ケーブル トライセップス Pushdown (v-bar)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Triceps Pushdown (v-bar) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', 'images/0241-gAwDzB3.jpg', 'videos/0241-gAwDzB3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2405', 'cable-triceps-pushdown-v-bar-with-arm-blaster', 'ケーブル トライセップス Pushdown (v-bar) (with Arm Blaster)', 'Cable Triceps Pushdown (v-bar) (with Arm Blaster)', 'ケーブル トライセップス Pushdown (v-bar) (with Arm Blaster)は、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Triceps Pushdown (v-bar) (with Arm Blaster) is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', 'images/2405-OxJk1fg.jpg', 'videos/2405-OxJk1fg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0242', 'cable-tuck-reverse-crunch', 'ケーブル Tuck Reverse クランチ', 'Cable Tuck Reverse Crunch', 'ケーブル Tuck Reverse クランチは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Tuck Reverse Crunch is an effective exercise targeting the hip flexors using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0242-TXtXc84.jpg', 'videos/0242-TXtXc84.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0243', 'cable-twist', 'ケーブル ツイスト', 'Cable Twist', 'ケーブル ツイストは、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Twist is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable''s pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."]', 'images/0243-aVs3BR3.jpg', 'videos/0243-aVs3BR3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0862', 'cable-twist-up-down', 'ケーブル ツイスト (up-down)', 'Cable Twist (up-down)', 'ケーブル ツイスト (up-down)は、ケーブルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cable Twist (up-down) is an effective exercise targeting the obliques using cable.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0862-fhZQPlV.jpg', 'videos/0862-fhZQPlV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0244', 'cable-twisting-pull', 'ケーブル Twisting Pull', 'Cable Twisting Pull', 'ケーブル Twisting Pullは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Twisting Pull is an effective exercise targeting the shoulders using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]', 'images/0244-zCgxPbV.jpg', 'videos/0244-zCgxPbV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1645', 'cable-two-arm-curl-on-incline-bench', 'ケーブル Two Arm カール On インクライン ベンチ', 'Cable Two Arm Curl On Incline Bench', 'ケーブル Two Arm カール On インクライン ベンチは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Two Arm Curl On Incline Bench is an effective exercise targeting the forearms using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1645-H9y3Dkr.jpg', 'videos/1645-H9y3Dkr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1728', 'cable-two-arm-tricep-kickback', 'ケーブル Two Arm Tricep キックバック', 'Cable Two Arm Tricep Kickback', 'ケーブル Two Arm Tricep キックバックは、ケーブルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Cable Two Arm Tricep Kickback is an effective exercise targeting the shoulders using cable.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1728-vvNjDJS.jpg', 'videos/1728-vvNjDJS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0245', 'cable-underhand-pulldown', 'ケーブル Underhand プルダウン', 'Cable Underhand Pulldown', 'ケーブル Underhand プルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Underhand Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0245-xBYcQHj.jpg', 'videos/0245-xBYcQHj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1270', 'cable-upper-chest-crossovers', 'ケーブル Upper チェスト Crossovers', 'Cable Upper Chest Crossovers', 'ケーブル Upper チェスト Crossoversは、ケーブルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Cable Upper Chest Crossovers is an effective exercise targeting the deltoids using cable.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1270-j7XMAyn.jpg', 'videos/1270-j7XMAyn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1324', 'cable-upper-row', 'ケーブル Upper ロー', 'Cable Upper Row', 'ケーブル Upper ローは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Upper Row is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1324-PQStVXH.jpg', 'videos/1324-PQStVXH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0246', 'cable-upright-row', 'ケーブル Upright ロー', 'Cable Upright Row', 'ケーブル Upright ローは、ケーブルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Cable Upright Row is an effective exercise targeting the traps using cable.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0246-cALKspW.jpg', 'videos/0246-cALKspW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1325', 'cable-wide-grip-rear-pulldown-behind-neck', 'ケーブル Wide Grip リア プルダウン Behind ネック', 'Cable Wide Grip Rear Pulldown Behind Neck', 'ケーブル Wide Grip リア プルダウン Behind ネックは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cable Wide Grip Rear Pulldown Behind Neck is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1325-CmEr4pM.jpg', 'videos/1325-CmEr4pM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0247', 'cable-wrist-curl', 'ケーブル リスト カール', 'Cable Wrist Curl', 'ケーブル リスト カールは、ケーブルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Cable Wrist Curl is an effective exercise targeting the biceps using cable.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0247-LrV4s90.jpg', 'videos/0247-LrV4s90.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1407', 'calf-push-stretch-with-hands-against-wall', 'カーフ Push ストレッチ With Hands Against Wall', 'Calf Push Stretch With Hands Against Wall', 'カーフ Push ストレッチ With Hands Against Wallは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Calf Push Stretch With Hands Against Wall is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', 'images/1407-PzNxakt.jpg', 'videos/1407-PzNxakt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1377', 'calf-stretch-with-hands-against-wall', 'カーフ ストレッチ With Hands Against Wall', 'Calf Stretch With Hands Against Wall', 'カーフ ストレッチ With Hands Against Wallは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Calf Stretch With Hands Against Wall is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', 'images/1377-m0tCHqc.jpg', 'videos/1377-m0tCHqc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1378', 'calf-stretch-with-rope', 'カーフ ストレッチ With Rope', 'Calf Stretch With Rope', 'カーフ ストレッチ With Ropeは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Calf Stretch With Rope is an effective exercise targeting the hamstrings using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."]', 'images/1378-1LVFcEn.jpg', 'videos/1378-1LVFcEn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0248', 'cambered-bar-lying-row', 'Cambered Bar ライイング ロー', 'Cambered Bar Lying Row', 'Cambered Bar ライイング ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Cambered Bar Lying Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0248-R5swFnc.jpg', 'videos/0248-R5swFnc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2963', 'captains-chair-straight-leg-raise', 'Captains Chair Straight Leg レイズ', 'Captains Chair Straight Leg Raise', 'Captains Chair Straight Leg レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Captains Chair Straight Leg Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2963-weoDEpH.jpg', 'videos/2963-weoDEpH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1548', 'chair-leg-extended-stretch', 'Chair Leg Extended ストレッチ', 'Chair Leg Extended Stretch', 'Chair Leg Extended ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Chair Leg Extended Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."]', 'images/1548-xGgAGPm.jpg', 'videos/1548-xGgAGPm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1271', 'chest-and-front-of-shoulder-stretch', 'チェスト And フロント Of Shoulder ストレッチ', 'Chest And Front Of Shoulder Stretch', 'チェスト And フロント Of Shoulder ストレッチは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest And Front Of Shoulder Stretch is an effective exercise targeting the deltoids using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."]', 'images/1271-Uto7l43.jpg', 'videos/1271-Uto7l43.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0251', 'chest-dip', 'チェスト ディップス', 'Chest Dip', 'チェスト ディップスは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest Dip is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0251-9WTm7dq.jpg', 'videos/0251-9WTm7dq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1430', 'chest-dip-on-dip-pull-up-cage', 'チェスト ディップス (on ディップス-プルアップ Cage)', 'Chest Dip (on Dip-pull-up Cage)', 'チェスト ディップス (on ディップス-プルアップ Cage)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest Dip (on Dip-pull-up Cage) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1430-XgWyAiA.jpg', 'videos/1430-XgWyAiA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2462', 'chest-dip-on-straight-bar', 'チェスト ディップス On Straight Bar', 'Chest Dip On Straight Bar', 'チェスト ディップス On Straight Barは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest Dip On Straight Bar is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/2462-LQFOrMn.jpg', 'videos/2462-LQFOrMn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1272', 'chest-stretch-with-exercise-ball', 'チェスト ストレッチ With Exercise Ball', 'Chest Stretch With Exercise Ball', 'チェスト ストレッチ With Exercise Ballは、スタビリティボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest Stretch With Exercise Ball is an effective exercise targeting the shoulders using stability ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1272-ykA5tU7.jpg', 'videos/1272-ykA5tU7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3216', 'chest-tap-push-up-male', 'チェスト Tap プッシュアップ (male)', 'Chest Tap Push-up (male)', 'チェスト Tap プッシュアップ (male)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Chest Tap Push-up (male) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."]', 'images/3216-7E06s6d.jpg', 'videos/3216-7E06s6d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1326', 'chin-up', 'チンアップ', 'Chin-up', 'チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Chin-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1326-T2mxWqc.jpg', 'videos/1326-T2mxWqc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0253', 'chin-ups-narrow-parallel-grip', 'チンアップ-ups (narrow Parallel Grip)', 'Chin-ups (narrow Parallel Grip)', 'チンアップ-ups (narrow Parallel Grip)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Chin-ups (narrow Parallel Grip) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0253-G70mEAJ.jpg', 'videos/0253-G70mEAJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0257', 'circles-knee-stretch', 'Circles Knee ストレッチ', 'Circles Knee Stretch', 'Circles Knee ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Circles Knee Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."]', 'images/0257-X7jbxra.jpg', 'videos/0257-X7jbxra.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1273', 'clap-push-up', 'Clap Push Up', 'Clap Push Up', 'Clap Push Upは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Clap Push Up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."]', 'images/1273-wigSg76.jpg', 'videos/1273-wigSg76.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0258', 'clock-push-up', 'Clock プッシュアップ', 'Clock Push-up', 'Clock プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Clock Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."]', 'images/0258-CMAxnsG.jpg', 'videos/0258-CMAxnsG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1327', 'close-grip-chin-up', 'Close Grip チンアップ', 'Close Grip Chin-up', 'Close Grip チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Close Grip Chin-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1327-VnfUNW7.jpg', 'videos/1327-VnfUNW7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0259', 'close-grip-push-up', 'ナローグリップ プッシュアップ', 'Close-grip Push-up', 'ナローグリップ プッシュアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Close-grip Push-up is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0259-x6KpKpq.jpg', 'videos/0259-x6KpKpq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2398', 'close-grip-push-up-on-knees', 'ナローグリップ プッシュアップ (on Knees)', 'Close-grip Push-up (on Knees)', 'ナローグリップ プッシュアップ (on Knees)は、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Close-grip Push-up (on Knees) is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2398-v3vLFW0.jpg', 'videos/2398-v3vLFW0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0260', 'cocoons', 'Cocoons', 'Cocoons', 'Cocoonsは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cocoons is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0260-SLKj2pX.jpg', 'videos/0260-SLKj2pX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1468', 'crab-twist-toe-touch', 'Crab ツイスト Toe Touch', 'Crab Twist Toe Touch', 'Crab ツイスト Toe Touchは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Crab Twist Toe Touch is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1468-xgsGFVM.jpg', 'videos/1468-xgsGFVM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0262', 'cross-body-crunch', 'Cross Body クランチ', 'Cross Body Crunch', 'Cross Body クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Cross Body Crunch is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."]', 'images/0262-rbu5UUb.jpg', 'videos/0262-rbu5UUb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0267', 'crunch-hands-overhead', 'クランチ (hands オーバーヘッド)', 'Crunch (hands Overhead)', 'クランチ (hands オーバーヘッド)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Crunch (hands Overhead) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0267-kjJ3VoQ.jpg', 'videos/0267-kjJ3VoQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0271', 'crunch-on-stability-ball', 'クランチ (on Stability Ball)', 'Crunch (on Stability Ball)', 'クランチ (on Stability Ball)は、スタビリティボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Crunch (on Stability Ball) is an effective exercise targeting the hip flexors using stability ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0271-MCUhf1F.jpg', 'videos/0271-MCUhf1F.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0272', 'crunch-on-stability-ball-arms-straight', 'クランチ (on Stability Ball, Arms Straight)', 'Crunch (on Stability Ball, Arms Straight)', 'クランチ (on Stability Ball, Arms Straight)は、スタビリティボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Crunch (on Stability Ball, Arms Straight) is an effective exercise targeting the hip flexors using stability ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0272-Sn8wxAI.jpg', 'videos/0272-Sn8wxAI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0274', 'crunch-floor', 'クランチ Floor', 'Crunch Floor', 'クランチ Floorは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Crunch Floor is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0274-TFqbd8t.jpg', 'videos/0274-TFqbd8t.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3016', 'curl-up', 'カール-up', 'Curl-up', 'カール-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Curl-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3016-g2oKspu.jpg', 'videos/3016-g2oKspu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3769', 'curtsey-squat', 'Curtsey スクワット', 'Curtsey Squat', 'Curtsey スクワットは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Curtsey Squat is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."]', 'images/3769-gUjqdei.jpg', 'videos/3769-gUjqdei.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2331', 'cycle-cross-trainer', 'Cycle Cross Trainer', 'Cycle Cross Trainer', 'Cycle Cross Trainerは、レバレッジマシンを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Cycle Cross Trainer is an effective exercise targeting the quadriceps using leverage machine.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."]', 'images/2331-XSCHmiI.jpg', 'videos/2331-XSCHmiI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0276', 'dead-bug', 'Dead Bug', 'Dead Bug', 'Dead Bugは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Dead Bug is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]', 'images/0276-iny3m5y.jpg', 'videos/0276-iny3m5y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0277', 'decline-crunch', 'デクライン クランチ', 'Decline Crunch', 'デクライン クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Decline Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0277-9Ap7miY.jpg', 'videos/0277-9Ap7miY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0279', 'decline-push-up', 'デクライン プッシュアップ', 'Decline Push-up', 'デクライン プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Decline Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0279-i5cEhka.jpg', 'videos/0279-i5cEhka.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0282', 'decline-sit-up', 'デクライン Sit-up', 'Decline Sit-up', 'デクライン Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Decline Sit-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0282-QLL2gdc.jpg', 'videos/0282-QLL2gdc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1274', 'deep-push-up', 'Deep Push Up', 'Deep Push Up', 'Deep Push Upは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Deep Push Up is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1274-vptOQ4N.jpg', 'videos/1274-vptOQ4N.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0283', 'diamond-push-up', 'Diamond プッシュアップ', 'Diamond Push-up', 'Diamond プッシュアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Diamond Push-up is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0283-soIB2rj.jpg', 'videos/0283-soIB2rj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0284', 'donkey-calf-raise', 'Donkey カーフ レイズ', 'Donkey Calf Raise', 'Donkey カーフ レイズは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Donkey Calf Raise is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0284-u5ESqzH.jpg', 'videos/0284-u5ESqzH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1275', 'drop-push-up', 'Drop Push Up', 'Drop Push Up', 'Drop Push Upは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Drop Push Up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/1275-Q497lAE.jpg', 'videos/1275-Q497lAE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0285', 'dumbbell-alternate-biceps-curl', 'ダンベル Alternate バイセップス カール', 'Dumbbell Alternate Biceps Curl', 'ダンベル Alternate バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', 'images/0285-BU15nH4.jpg', 'videos/0285-BU15nH4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2403', 'dumbbell-alternate-biceps-curl-with-arm-blaster', 'ダンベル Alternate バイセップス カール (with Arm Blaster)', 'Dumbbell Alternate Biceps Curl (with Arm Blaster)', 'ダンベル Alternate バイセップス カール (with Arm Blaster)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Biceps Curl (with Arm Blaster) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', 'images/2403-CfKsRbG.jpg', 'videos/2403-CfKsRbG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1646', 'dumbbell-alternate-hammer-preacher-curl', 'ダンベル Alternate ハンマー Preacher カール', 'Dumbbell Alternate Hammer Preacher Curl', 'ダンベル Alternate ハンマー Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Hammer Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', 'images/1646-fy7Tgy4.jpg', 'videos/1646-fy7Tgy4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1647', 'dumbbell-alternate-preacher-curl', 'ダンベル Alternate Preacher カール', 'Dumbbell Alternate Preacher Curl', 'ダンベル Alternate Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1647-NlfIbzq.jpg', 'videos/1647-NlfIbzq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1648', 'dumbbell-alternate-seated-hammer-curl', 'ダンベル Alternate シーテッド ハンマー カール', 'Dumbbell Alternate Seated Hammer Curl', 'ダンベル Alternate シーテッド ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Seated Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1648-6em2Dxj.jpg', 'videos/1648-6em2Dxj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0286', 'dumbbell-alternate-side-press', 'ダンベル Alternate Side プレス', 'Dumbbell Alternate Side Press', 'ダンベル Alternate Side プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternate Side Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."]', 'images/0286-izMnLqz.jpg', 'videos/0286-izMnLqz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1649', 'dumbbell-alternating-bicep-curl-with-leg-raised-on-exercise-ball', 'ダンベル Alternating Bicep カール With Leg Raised On Exercise Ball', 'Dumbbell Alternating Bicep Curl With Leg Raised On Exercise Ball', 'ダンベル Alternating Bicep カール With Leg Raised On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternating Bicep Curl With Leg Raised On Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1649-Zwiw7XR.jpg', 'videos/1649-Zwiw7XR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1650', 'dumbbell-alternating-seated-bicep-curl-on-exercise-ball', 'ダンベル Alternating シーテッド Bicep カール On Exercise Ball', 'Dumbbell Alternating Seated Bicep Curl On Exercise Ball', 'ダンベル Alternating シーテッド Bicep カール On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Alternating Seated Bicep Curl On Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."]', 'images/1650-J74XlNf.jpg', 'videos/1650-J74XlNf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2137', 'dumbbell-arnold-press', 'ダンベル Arnold プレス', 'Dumbbell Arnold Press', 'ダンベル Arnold プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Arnold Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2137-Xy4jlWA.jpg', 'videos/2137-Xy4jlWA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0287', 'dumbbell-arnold-press-v-2', 'ダンベル Arnold プレス V. 2', 'Dumbbell Arnold Press V. 2', 'ダンベル Arnold プレス V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Arnold Press V. 2 is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0287-eOrFCnx.jpg', 'videos/0287-eOrFCnx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0288', 'dumbbell-around-pullover', 'ダンベル Around プルオーバー', 'Dumbbell Around Pullover', 'ダンベル Around プルオーバーは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Around Pullover is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0288-vi8EhoE.jpg', 'videos/0288-vi8EhoE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0289', 'dumbbell-bench-press', 'ダンベル ベンチプレス', 'Dumbbell Bench Press', 'ダンベル ベンチプレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bench Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0289-SpYC0Kp.jpg', 'videos/0289-SpYC0Kp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0290', 'dumbbell-bench-seated-press', 'ダンベル ベンチ シーテッド プレス', 'Dumbbell Bench Seated Press', 'ダンベル ベンチ シーテッド プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bench Seated Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0290-3d7wHyd.jpg', 'videos/0290-3d7wHyd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0291', 'dumbbell-bench-squat', 'ダンベル ベンチ スクワット', 'Dumbbell Bench Squat', 'ダンベル ベンチ スクワットは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bench Squat is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0291-mnzcrIB.jpg', 'videos/0291-mnzcrIB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0293', 'dumbbell-bent-over-row', 'ダンベル Bent Over ロー', 'Dumbbell Bent Over Row', 'ダンベル Bent Over ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bent Over Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0293-BJ0Hz5L.jpg', 'videos/0293-BJ0Hz5L.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1651', 'dumbbell-bicep-curl-lunge-with-bowling-motion', 'ダンベル Bicep カール ランジ With Bowling Motion', 'Dumbbell Bicep Curl Lunge With Bowling Motion', 'ダンベル Bicep カール ランジ With Bowling Motionは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bicep Curl Lunge With Bowling Motion is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."]', 'images/1651-1VpF8db.jpg', 'videos/1651-1VpF8db.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1652', 'dumbbell-bicep-curl-on-exercise-ball-with-leg-raised', 'ダンベル Bicep カール On Exercise Ball With Leg Raised', 'Dumbbell Bicep Curl On Exercise Ball With Leg Raised', 'ダンベル Bicep カール On Exercise Ball With Leg Raisedは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bicep Curl On Exercise Ball With Leg Raised is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1652-2NImIAG.jpg', 'videos/1652-2NImIAG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1653', 'dumbbell-bicep-curl-with-stork-stance', 'ダンベル Bicep カール With Stork Stance', 'Dumbbell Bicep Curl With Stork Stance', 'ダンベル Bicep カール With Stork Stanceは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Bicep Curl With Stork Stance is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1653-uSkDMYl.jpg', 'videos/1653-uSkDMYl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0294', 'dumbbell-biceps-curl', 'ダンベル バイセップス カール', 'Dumbbell Biceps Curl', 'ダンベル バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0294-NbVPDMW.jpg', 'videos/0294-NbVPDMW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2401', 'dumbbell-biceps-curl-with-arm-blaster', 'ダンベル バイセップス カール (with Arm Blaster)', 'Dumbbell Biceps Curl (with Arm Blaster)', 'ダンベル バイセップス カール (with Arm Blaster)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Biceps Curl (with Arm Blaster) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2401-nlJsbkW.jpg', 'videos/2401-nlJsbkW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1654', 'dumbbell-biceps-curl-reverse', 'ダンベル バイセップス カール Reverse', 'Dumbbell Biceps Curl Reverse', 'ダンベル バイセップス カール Reverseは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Biceps Curl Reverse is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1654-nFc4FyV.jpg', 'videos/1654-nFc4FyV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1655', 'dumbbell-biceps-curl-squat', 'ダンベル バイセップス カール スクワット', 'Dumbbell Biceps Curl Squat', 'ダンベル バイセップス カール スクワットは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Biceps Curl Squat is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1655-niXESDw.jpg', 'videos/1655-niXESDw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1656', 'dumbbell-biceps-curl-v-sit-on-bosu-ball', 'ダンベル バイセップス カール V Sit On Bosu Ball', 'Dumbbell Biceps Curl V Sit On Bosu Ball', 'ダンベル バイセップス カール V Sit On Bosu Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Biceps Curl V Sit On Bosu Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1656-H1XAdpk.jpg', 'videos/1656-H1XAdpk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1201', 'dumbbell-burpee', 'ダンベル Burpee', 'Dumbbell Burpee', 'ダンベル Burpeeは、ダンベルを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Burpee is an effective exercise targeting the quadriceps using dumbbell.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."]', 'images/1201-0JtKWum.jpg', 'videos/1201-0JtKWum.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0295', 'dumbbell-clean', 'ダンベル Clean', 'Dumbbell Clean', 'ダンベル Cleanは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Clean is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', 'images/0295-7Hg55JG.jpg', 'videos/0295-7Hg55JG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1731', 'dumbbell-close-grip-press', 'ダンベル Close Grip プレス', 'Dumbbell Close Grip Press', 'ダンベル Close Grip プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Close Grip Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', 'images/1731-7jGOBF3.jpg', 'videos/1731-7jGOBF3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0296', 'dumbbell-close-grip-press-0296', 'ダンベル ナローグリップ プレス', 'Dumbbell Close-grip Press', 'ダンベル ナローグリップ プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Close-grip Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0296-RxayqAZ.jpg', 'videos/0296-RxayqAZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0297', 'dumbbell-concentration-curl', 'ダンベル Concentration カール', 'Dumbbell Concentration Curl', 'ダンベル Concentration カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Concentration Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0297-gvsWLQw.jpg', 'videos/0297-gvsWLQw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3635', 'dumbbell-contralateral-forward-lunge', 'ダンベル Contralateral Forward ランジ', 'Dumbbell Contralateral Forward Lunge', 'ダンベル Contralateral Forward ランジは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Contralateral Forward Lunge is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', 'images/3635-ecl28tP.jpg', 'videos/3635-ecl28tP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0298', 'dumbbell-cross-body-hammer-curl', 'ダンベル Cross Body ハンマー カール', 'Dumbbell Cross Body Hammer Curl', 'ダンベル Cross Body ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Cross Body Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0298-Qyk5J3p.jpg', 'videos/0298-Qyk5J3p.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1657', 'dumbbell-cross-body-hammer-curl-v-2', 'ダンベル Cross Body ハンマー カール V. 2', 'Dumbbell Cross Body Hammer Curl V. 2', 'ダンベル Cross Body ハンマー カール V. 2は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Cross Body Hammer Curl V. 2 is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1657-HDYiZcY.jpg', 'videos/1657-HDYiZcY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0299', 'dumbbell-cuban-press', 'ダンベル Cuban プレス', 'Dumbbell Cuban Press', 'ダンベル Cuban プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Cuban Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]', 'images/0299-QfAKy1G.jpg', 'videos/0299-QfAKy1G.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2136', 'dumbbell-cuban-press-v-2', 'ダンベル Cuban プレス V. 2', 'Dumbbell Cuban Press V. 2', 'ダンベル Cuban プレス V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Cuban Press V. 2 is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2136-BqgCRif.jpg', 'videos/2136-BqgCRif.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0300', 'dumbbell-deadlift', 'ダンベル デッドリフト', 'Dumbbell Deadlift', 'ダンベル デッドリフトは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Deadlift is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0300-nUwVh7b.jpg', 'videos/0300-nUwVh7b.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0301', 'dumbbell-decline-bench-press', 'ダンベル デクライン ベンチプレス', 'Dumbbell Decline Bench Press', 'ダンベル デクライン ベンチプレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Bench Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0301-DwhEmmE.jpg', 'videos/0301-DwhEmmE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0302', 'dumbbell-decline-fly', 'ダンベル デクライン フライ', 'Dumbbell Decline Fly', 'ダンベル デクライン フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0302-xXm4nYq.jpg', 'videos/0302-xXm4nYq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0303', 'dumbbell-decline-hammer-press', 'ダンベル デクライン ハンマー プレス', 'Dumbbell Decline Hammer Press', 'ダンベル デクライン ハンマー プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Hammer Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0303-1qrWgZ2.jpg', 'videos/0303-1qrWgZ2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1276', 'dumbbell-decline-one-arm-fly', 'ダンベル デクライン ワンハンド フライ', 'Dumbbell Decline One Arm Fly', 'ダンベル デクライン ワンハンド フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline One Arm Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1276-NL6YBwN.jpg', 'videos/1276-NL6YBwN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1617', 'dumbbell-decline-one-arm-hammer-press', 'ダンベル デクライン ワンハンド ハンマー プレス', 'Dumbbell Decline One Arm Hammer Press', 'ダンベル デクライン ワンハンド ハンマー プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline One Arm Hammer Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1617-SHUMp5H.jpg', 'videos/1617-SHUMp5H.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0305', 'dumbbell-decline-shrug', 'ダンベル デクライン シュラッグ', 'Dumbbell Decline Shrug', 'ダンベル デクライン シュラッグは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Shrug is an effective exercise targeting the shoulders using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0305-cwsAI4G.jpg', 'videos/0305-cwsAI4G.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0304', 'dumbbell-decline-shrug-v-2', 'ダンベル デクライン シュラッグ V. 2', 'Dumbbell Decline Shrug V. 2', 'ダンベル デクライン シュラッグ V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Shrug V. 2 is an effective exercise targeting the shoulders using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0304-bRlbdjK.jpg', 'videos/0304-bRlbdjK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0306', 'dumbbell-decline-triceps-extension', 'ダンベル デクライン トライセップス エクステンション', 'Dumbbell Decline Triceps Extension', 'ダンベル デクライン トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0306-OTgkHwR.jpg', 'videos/0306-OTgkHwR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0307', 'dumbbell-decline-twist-fly', 'ダンベル デクライン ツイスト フライ', 'Dumbbell Decline Twist Fly', 'ダンベル デクライン ツイスト フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Decline Twist Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."]', 'images/0307-reFHapa.jpg', 'videos/0307-reFHapa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1437', 'dumbbell-finger-curls', 'ダンベル Finger Curls', 'Dumbbell Finger Curls', 'ダンベル Finger Curlsは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Finger Curls is an effective exercise targeting the wrist flexors using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."]', 'images/1437-mtXengz.jpg', 'videos/1437-mtXengz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0308', 'dumbbell-fly', 'ダンベル フライ', 'Dumbbell Fly', 'ダンベル フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0308-yz9nUhF.jpg', 'videos/0308-yz9nUhF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1277', 'dumbbell-fly-on-exercise-ball', 'ダンベル フライ On Exercise Ball', 'Dumbbell Fly On Exercise Ball', 'ダンベル フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1277-Lt3iWnf.jpg', 'videos/1277-Lt3iWnf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1732', 'dumbbell-forward-lunge-triceps-extension', 'ダンベル Forward ランジ トライセップス エクステンション', 'Dumbbell Forward Lunge Triceps Extension', 'ダンベル Forward ランジ トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Forward Lunge Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."]', 'images/1732-XalXcvM.jpg', 'videos/1732-XalXcvM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0310', 'dumbbell-front-raise', 'ダンベル フロント レイズ', 'Dumbbell Front Raise', 'ダンベル フロント レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Front Raise is an effective exercise targeting the biceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0310-3eGE2JC.jpg', 'videos/0310-3eGE2JC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0309', 'dumbbell-front-raise-v-2', 'ダンベル フロント レイズ V. 2', 'Dumbbell Front Raise V. 2', 'ダンベル フロント レイズ V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Front Raise V. 2 is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0309-Rr7S3yg.jpg', 'videos/0309-Rr7S3yg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0311', 'dumbbell-full-can-lateral-raise', 'ダンベル Full Can サイド レイズ', 'Dumbbell Full Can Lateral Raise', 'ダンベル Full Can サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Full Can Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0311-AQ0mC4Y.jpg', 'videos/0311-AQ0mC4Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1760', 'dumbbell-goblet-squat', 'ダンベル Goblet スクワット', 'Dumbbell Goblet Squat', 'ダンベル Goblet スクワットは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Goblet Squat is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1760-yn8yg1r.jpg', 'videos/1760-yn8yg1r.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0313', 'dumbbell-hammer-curl', 'ダンベル ハンマー カール', 'Dumbbell Hammer Curl', 'ダンベル ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', 'images/0313-slDvUAU.jpg', 'videos/0313-slDvUAU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1659', 'dumbbell-hammer-curl-on-exercise-ball', 'ダンベル ハンマー カール On Exercise Ball', 'Dumbbell Hammer Curl On Exercise Ball', 'ダンベル ハンマー カール On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Hammer Curl On Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1659-fY68AyX.jpg', 'videos/1659-fY68AyX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0312', 'dumbbell-hammer-curl-v-2', 'ダンベル ハンマー カール V. 2', 'Dumbbell Hammer Curl V. 2', 'ダンベル ハンマー カール V. 2は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Hammer Curl V. 2 is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', 'images/0312-2NpxjC1.jpg', 'videos/0312-2NpxjC1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2402', 'dumbbell-hammer-curls-with-arm-blaster', 'ダンベル ハンマー Curls (with Arm Blaster)', 'Dumbbell Hammer Curls (with Arm Blaster)', 'ダンベル ハンマー Curls (with Arm Blaster)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Hammer Curls (with Arm Blaster) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', 'images/2402-GNhAeJ0.jpg', 'videos/2402-GNhAeJ0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1664', 'dumbbell-high-curl', 'ダンベル High カール', 'Dumbbell High Curl', 'ダンベル High カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell High Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1664-qAmNMJY.jpg', 'videos/1664-qAmNMJY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3545', 'dumbbell-incline-alternate-press', 'ダンベル インクライン Alternate プレス', 'Dumbbell Incline Alternate Press', 'ダンベル インクライン Alternate プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Alternate Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."]', 'images/3545-TVdivgY.jpg', 'videos/3545-TVdivgY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0314', 'dumbbell-incline-bench-press', 'ダンベル インクライン ベンチプレス', 'Dumbbell Incline Bench Press', 'ダンベル インクライン ベンチプレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Bench Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0314-ns0SIbU.jpg', 'videos/0314-ns0SIbU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0315', 'dumbbell-incline-biceps-curl', 'ダンベル インクライン バイセップス カール', 'Dumbbell Incline Biceps Curl', 'ダンベル インクライン バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0315-F3xgbjF.jpg', 'videos/0315-F3xgbjF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0316', 'dumbbell-incline-breeding', 'ダンベル インクライン Breeding', 'Dumbbell Incline Breeding', 'ダンベル インクライン Breedingは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Breeding is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0316-B3Rxp6L.jpg', 'videos/0316-B3Rxp6L.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0318', 'dumbbell-incline-curl', 'ダンベル インクライン カール', 'Dumbbell Incline Curl', 'ダンベル インクライン カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0318-ae9UoXQ.jpg', 'videos/0318-ae9UoXQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0317', 'dumbbell-incline-curl-v-2', 'ダンベル インクライン カール V. 2', 'Dumbbell Incline Curl V. 2', 'ダンベル インクライン カール V. 2は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Curl V. 2 is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0317-RaflbWD.jpg', 'videos/0317-RaflbWD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0319', 'dumbbell-incline-fly', 'ダンベル インクライン フライ', 'Dumbbell Incline Fly', 'ダンベル インクライン フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0319-ESOd5Pl.jpg', 'videos/0319-ESOd5Pl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1278', 'dumbbell-incline-fly-on-exercise-ball', 'ダンベル インクライン フライ On Exercise Ball', 'Dumbbell Incline Fly On Exercise Ball', 'ダンベル インクライン フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1278-HYe1ZqR.jpg', 'videos/1278-HYe1ZqR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0320', 'dumbbell-incline-hammer-curl', 'ダンベル インクライン ハンマー カール', 'Dumbbell Incline Hammer Curl', 'ダンベル インクライン ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0320-ByX0WxV.jpg', 'videos/0320-ByX0WxV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0321', 'dumbbell-incline-hammer-press', 'ダンベル インクライン ハンマー プレス', 'Dumbbell Incline Hammer Press', 'ダンベル インクライン ハンマー プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Hammer Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0321-PG1kcIb.jpg', 'videos/0321-PG1kcIb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1618', 'dumbbell-incline-hammer-press-on-exercise-ball', 'ダンベル インクライン ハンマー プレス On Exercise Ball', 'Dumbbell Incline Hammer Press On Exercise Ball', 'ダンベル インクライン ハンマー プレス On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Hammer Press On Exercise Ball is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1618-wkgnGfb.jpg', 'videos/1618-wkgnGfb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0322', 'dumbbell-incline-inner-biceps-curl', 'ダンベル インクライン Inner バイセップス カール', 'Dumbbell Incline Inner Biceps Curl', 'ダンベル インクライン Inner バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Inner Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0322-LCtQPn8.jpg', 'videos/0322-LCtQPn8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1279', 'dumbbell-incline-one-arm-fly', 'ダンベル インクライン ワンハンド フライ', 'Dumbbell Incline One Arm Fly', 'ダンベル インクライン ワンハンド フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Fly is an effective exercise targeting the deltoids using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1279-Gw2HFvW.jpg', 'videos/1279-Gw2HFvW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1280', 'dumbbell-incline-one-arm-fly-on-exercise-ball', 'ダンベル インクライン ワンハンド フライ On Exercise Ball', 'Dumbbell Incline One Arm Fly On Exercise Ball', 'ダンベル インクライン ワンハンド フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1280-LLNh6q5.jpg', 'videos/1280-LLNh6q5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1619', 'dumbbell-incline-one-arm-hammer-press', 'ダンベル インクライン ワンハンド ハンマー プレス', 'Dumbbell Incline One Arm Hammer Press', 'ダンベル インクライン ワンハンド ハンマー プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Hammer Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1619-LL1UiTX.jpg', 'videos/1619-LL1UiTX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1620', 'dumbbell-incline-one-arm-hammer-press-on-exercise-ball', 'ダンベル インクライン ワンハンド ハンマー プレス On Exercise Ball', 'Dumbbell Incline One Arm Hammer Press On Exercise Ball', 'ダンベル インクライン ワンハンド ハンマー プレス On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Hammer Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1620-jDnrkar.jpg', 'videos/1620-jDnrkar.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0323', 'dumbbell-incline-one-arm-lateral-raise', 'ダンベル インクライン ワンハンド サイド レイズ', 'Dumbbell Incline One Arm Lateral Raise', 'ダンベル インクライン ワンハンド サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Lateral Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0323-aTNKZiC.jpg', 'videos/0323-aTNKZiC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1281', 'dumbbell-incline-one-arm-press', 'ダンベル インクライン ワンハンド プレス', 'Dumbbell Incline One Arm Press', 'ダンベル インクライン ワンハンド プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1281-rDAiRf9.jpg', 'videos/1281-rDAiRf9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1282', 'dumbbell-incline-one-arm-press-on-exercise-ball', 'ダンベル インクライン ワンハンド プレス On Exercise Ball', 'Dumbbell Incline One Arm Press On Exercise Ball', 'ダンベル インクライン ワンハンド プレス On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline One Arm Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1282-Bg5JKSH.jpg', 'videos/1282-Bg5JKSH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0324', 'dumbbell-incline-palm-in-press', 'ダンベル インクライン Palm-in プレス', 'Dumbbell Incline Palm-in Press', 'ダンベル インクライン Palm-in プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Palm-in Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0324-OVLmUuL.jpg', 'videos/0324-OVLmUuL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1283', 'dumbbell-incline-press-on-exercise-ball', 'ダンベル インクライン プレス On Exercise Ball', 'Dumbbell Incline Press On Exercise Ball', 'ダンベル インクライン プレス On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1283-bfiHMpI.jpg', 'videos/1283-bfiHMpI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0325', 'dumbbell-incline-raise', 'ダンベル インクライン レイズ', 'Dumbbell Incline Raise', 'ダンベル インクライン レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0325-nxW6BkN.jpg', 'videos/0325-nxW6BkN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0326', 'dumbbell-incline-rear-lateral-raise', 'ダンベル インクライン リア サイド レイズ', 'Dumbbell Incline Rear Lateral Raise', 'ダンベル インクライン リア サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Rear Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0326-vYk8lqw.jpg', 'videos/0326-vYk8lqw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0327', 'dumbbell-incline-row', 'ダンベル インクライン ロー', 'Dumbbell Incline Row', 'ダンベル インクライン ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0327-7vG5o25.jpg', 'videos/0327-7vG5o25.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0328', 'dumbbell-incline-shoulder-raise', 'ダンベル インクライン Shoulder レイズ', 'Dumbbell Incline Shoulder Raise', 'ダンベル インクライン Shoulder レイズは、ダンベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Shoulder Raise is an effective exercise targeting the deltoids using dumbbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0328-6e2DcYX.jpg', 'videos/0328-6e2DcYX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0329', 'dumbbell-incline-shrug', 'ダンベル インクライン シュラッグ', 'Dumbbell Incline Shrug', 'ダンベル インクライン シュラッグは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Shrug is an effective exercise targeting the shoulders using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0329-JymLInS.jpg', 'videos/0329-JymLInS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3542', 'dumbbell-incline-t-raise', 'ダンベル インクライン T-レイズ', 'Dumbbell Incline T-raise', 'ダンベル インクライン T-レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline T-raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3542-jgbvVJ0.jpg', 'videos/3542-jgbvVJ0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0330', 'dumbbell-incline-triceps-extension', 'ダンベル インクライン トライセップス エクステンション', 'Dumbbell Incline Triceps Extension', 'ダンベル インクライン トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0330-OVIKwsd.jpg', 'videos/0330-OVIKwsd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0331', 'dumbbell-incline-twisted-flyes', 'ダンベル インクライン Twisted Flyes', 'Dumbbell Incline Twisted Flyes', 'ダンベル インクライン Twisted Flyesは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Twisted Flyes is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."]', 'images/0331-1PLE8e9.jpg', 'videos/0331-1PLE8e9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1733', 'dumbbell-incline-two-arm-extension', 'ダンベル インクライン Two Arm エクステンション', 'Dumbbell Incline Two Arm Extension', 'ダンベル インクライン Two Arm エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Two Arm Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1733-U7D9Fx3.jpg', 'videos/1733-U7D9Fx3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3541', 'dumbbell-incline-y-raise', 'ダンベル インクライン Y-レイズ', 'Dumbbell Incline Y-raise', 'ダンベル インクライン Y-レイズは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Incline Y-raise is an effective exercise targeting the shoulders using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3541-PbzNu7c.jpg', 'videos/3541-PbzNu7c.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0332', 'dumbbell-iron-cross', 'ダンベル Iron Cross', 'Dumbbell Iron Cross', 'ダンベル Iron Crossは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Iron Cross is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0332-cALkHHX.jpg', 'videos/0332-cALkHHX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0333', 'dumbbell-kickback', 'ダンベル キックバック', 'Dumbbell Kickback', 'ダンベル キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0333-W6PxUkg.jpg', 'videos/0333-W6PxUkg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1734', 'dumbbell-kickbacks-on-exercise-ball', 'ダンベル Kickbacks On Exercise Ball', 'Dumbbell Kickbacks On Exercise Ball', 'ダンベル Kickbacks On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Kickbacks On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1734-cAvTaSg.jpg', 'videos/1734-cAvTaSg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1660', 'dumbbell-kneeling-bicep-curl-exercise-ball', 'ダンベル ニーリング Bicep カール Exercise Ball', 'Dumbbell Kneeling Bicep Curl Exercise Ball', 'ダンベル ニーリング Bicep カール Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Kneeling Bicep Curl Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1660-2JCuFTU.jpg', 'videos/1660-2JCuFTU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0334', 'dumbbell-lateral-raise', 'ダンベル サイド レイズ', 'Dumbbell Lateral Raise', 'ダンベル サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0334-DsgkuIt.jpg', 'videos/0334-DsgkuIt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0335', 'dumbbell-lateral-to-front-raise', 'ダンベル サイド To フロント レイズ', 'Dumbbell Lateral To Front Raise', 'ダンベル サイド To フロント レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lateral To Front Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0335-xMjBKwn.jpg', 'videos/0335-xMjBKwn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0336', 'dumbbell-lunge', 'ダンベル ランジ', 'Dumbbell Lunge', 'ダンベル ランジは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lunge is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', 'images/0336-RRWFUcw.jpg', 'videos/0336-RRWFUcw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1658', 'dumbbell-lunge-with-bicep-curl', 'ダンベル ランジ With Bicep カール', 'Dumbbell Lunge With Bicep Curl', 'ダンベル ランジ With Bicep カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lunge With Bicep Curl is an effective exercise targeting the quadriceps using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."]', 'images/1658-Mz6lLcW.jpg', 'videos/1658-Mz6lLcW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0337', 'dumbbell-lying-extension-across-face', 'ダンベル ライイング エクステンション (across Face)', 'Dumbbell Lying Extension (across Face)', 'ダンベル ライイング エクステンション (across Face)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Extension (across Face) is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0337-L2V5Nan.jpg', 'videos/0337-L2V5Nan.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1729', 'dumbbell-lying-alternate-extension', 'ダンベル ライイング Alternate エクステンション', 'Dumbbell Lying Alternate Extension', 'ダンベル ライイング Alternate エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Alternate Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."]', 'images/1729-NfP83rA.jpg', 'videos/1729-NfP83rA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0338', 'dumbbell-lying-elbow-press', 'ダンベル ライイング Elbow プレス', 'Dumbbell Lying Elbow Press', 'ダンベル ライイング Elbow プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Elbow Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', 'images/0338-eOCOwIR.jpg', 'videos/0338-eOCOwIR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0863', 'dumbbell-lying-external-shoulder-rotation', 'ダンベル ライイング External Shoulder Rotation', 'Dumbbell Lying External Shoulder Rotation', 'ダンベル ライイング External Shoulder Rotationは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying External Shoulder Rotation is an effective exercise targeting the rotator cuff using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0863-bmBf7LN.jpg', 'videos/0863-bmBf7LN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0339', 'dumbbell-lying-femoral', 'ダンベル ライイング Femoral', 'Dumbbell Lying Femoral', 'ダンベル ライイング Femoralは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Femoral is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0339-FkBIE6a.jpg', 'videos/0339-FkBIE6a.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0340', 'dumbbell-lying-hammer-press', 'ダンベル ライイング ハンマー プレス', 'Dumbbell Lying Hammer Press', 'ダンベル ライイング ハンマー プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Hammer Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0340-7gdLIXa.jpg', 'videos/0340-7gdLIXa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2470', 'dumbbell-lying-on-floor-rear-delt-raise', 'ダンベル ライイング On Floor リア Delt レイズ', 'Dumbbell Lying On Floor Rear Delt Raise', 'ダンベル ライイング On Floor リア Delt レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying On Floor Rear Delt Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2470-Ion0XWz.jpg', 'videos/2470-Ion0XWz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0341', 'dumbbell-lying-one-arm-deltoid-rear', 'ダンベル ライイング ワンハンド Deltoid リア', 'Dumbbell Lying One Arm Deltoid Rear', 'ダンベル ライイング ワンハンド Deltoid リアは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Deltoid Rear is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0341-gSw59a4.jpg', 'videos/0341-gSw59a4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0343', 'dumbbell-lying-one-arm-press', 'ダンベル ライイング ワンハンド プレス', 'Dumbbell Lying One Arm Press', 'ダンベル ライイング ワンハンド プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0343-zGSIWQi.jpg', 'videos/0343-zGSIWQi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0342', 'dumbbell-lying-one-arm-press-v-2', 'ダンベル ライイング ワンハンド プレス V. 2', 'Dumbbell Lying One Arm Press V. 2', 'ダンベル ライイング ワンハンド プレス V. 2は、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Press V. 2 is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0342-K3dIO25.jpg', 'videos/0342-K3dIO25.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0344', 'dumbbell-lying-one-arm-pronated-triceps-extension', 'ダンベル ライイング ワンハンド Pronated トライセップス エクステンション', 'Dumbbell Lying One Arm Pronated Triceps Extension', 'ダンベル ライイング ワンハンド Pronated トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Pronated Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0344-wyaqzOS.jpg', 'videos/0344-wyaqzOS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0345', 'dumbbell-lying-one-arm-rear-lateral-raise', 'ダンベル ライイング ワンハンド リア サイド レイズ', 'Dumbbell Lying One Arm Rear Lateral Raise', 'ダンベル ライイング ワンハンド リア サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Rear Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0345-KwFGiEP.jpg', 'videos/0345-KwFGiEP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0346', 'dumbbell-lying-one-arm-supinated-triceps-extension', 'ダンベル ライイング ワンハンド Supinated トライセップス エクステンション', 'Dumbbell Lying One Arm Supinated Triceps Extension', 'ダンベル ライイング ワンハンド Supinated トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying One Arm Supinated Triceps Extension is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0346-zZlORz6.jpg', 'videos/0346-zZlORz6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0347', 'dumbbell-lying-pronation', 'ダンベル ライイング Pronation', 'Dumbbell Lying Pronation', 'ダンベル ライイング Pronationは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Pronation is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0347-mym4hJo.jpg', 'videos/0347-mym4hJo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2705', 'dumbbell-lying-pronation-on-floor', 'ダンベル ライイング Pronation On Floor', 'Dumbbell Lying Pronation On Floor', 'ダンベル ライイング Pronation On Floorは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Pronation On Floor is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2705-7RWNjiB.jpg', 'videos/2705-7RWNjiB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1284', 'dumbbell-lying-pullover-on-exercise-ball', 'ダンベル ライイング プルオーバー On Exercise Ball', 'Dumbbell Lying Pullover On Exercise Ball', 'ダンベル ライイング プルオーバー On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Pullover On Exercise Ball is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1284-iK59oEA.jpg', 'videos/1284-iK59oEA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1328', 'dumbbell-lying-rear-delt-row', 'ダンベル ライイング リア Delt ロー', 'Dumbbell Lying Rear Delt Row', 'ダンベル ライイング リア Delt ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Rear Delt Row is an effective exercise targeting the shoulders using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1328-XUUD0Fs.jpg', 'videos/1328-XUUD0Fs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0348', 'dumbbell-lying-rear-lateral-raise', 'ダンベル ライイング リア サイド レイズ', 'Dumbbell Lying Rear Lateral Raise', 'ダンベル ライイング リア サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Rear Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0348-53Ttlck.jpg', 'videos/0348-53Ttlck.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1735', 'dumbbell-lying-single-extension', 'ダンベル ライイング Single エクステンション', 'Dumbbell Lying Single Extension', 'ダンベル ライイング Single エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Single Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1735-6MfS53i.jpg', 'videos/1735-6MfS53i.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0349', 'dumbbell-lying-supination', 'ダンベル ライイング Supination', 'Dumbbell Lying Supination', 'ダンベル ライイング Supinationは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Supination is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0349-M2Pm3zj.jpg', 'videos/0349-M2Pm3zj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2706', 'dumbbell-lying-supination-on-floor', 'ダンベル ライイング Supination On Floor', 'Dumbbell Lying Supination On Floor', 'ダンベル ライイング Supination On Floorは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Supination On Floor is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2706-rEhi2o5.jpg', 'videos/2706-rEhi2o5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1661', 'dumbbell-lying-supine-biceps-curl', 'ダンベル ライイング Supine バイセップス カール', 'Dumbbell Lying Supine Biceps Curl', 'ダンベル ライイング Supine バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Supine Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1661-XVzF3iZ.jpg', 'videos/1661-XVzF3iZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0350', 'dumbbell-lying-supine-curl', 'ダンベル ライイング Supine カール', 'Dumbbell Lying Supine Curl', 'ダンベル ライイング Supine カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Supine Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0350-KUaZst7.jpg', 'videos/0350-KUaZst7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0351', 'dumbbell-lying-triceps-extension', 'ダンベル ライイング トライセップス エクステンション', 'Dumbbell Lying Triceps Extension', 'ダンベル ライイング トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0351-mpKZGWz.jpg', 'videos/0351-mpKZGWz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1662', 'dumbbell-lying-wide-curl', 'ダンベル ライイング Wide カール', 'Dumbbell Lying Wide Curl', 'ダンベル ライイング Wide カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Lying Wide Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1662-qm9veZw.jpg', 'videos/1662-qm9veZw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0352', 'dumbbell-neutral-grip-bench-press', 'ダンベル Neutral Grip ベンチプレス', 'Dumbbell Neutral Grip Bench Press', 'ダンベル Neutral Grip ベンチプレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Neutral Grip Bench Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0352-pP8wP2P.jpg', 'videos/0352-pP8wP2P.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1285', 'dumbbell-one-arm-bench-fly', 'ダンベル ワンハンド ベンチ フライ', 'Dumbbell One Arm Bench Fly', 'ダンベル ワンハンド ベンチ フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Bench Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', 'images/1285-o5Jsk92.jpg', 'videos/1285-o5Jsk92.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0292', 'dumbbell-one-arm-bent-over-row', 'ダンベル ワンハンド Bent-over ロー', 'Dumbbell One Arm Bent-over Row', 'ダンベル ワンハンド Bent-over ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Bent-over Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0292-C0MA9bC.jpg', 'videos/0292-C0MA9bC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1286', 'dumbbell-one-arm-chest-fly-on-exercise-ball', 'ダンベル ワンハンド チェスト フライ On Exercise Ball', 'Dumbbell One Arm Chest Fly On Exercise Ball', 'ダンベル ワンハンド チェスト フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Chest Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1286-Bpkf41o.jpg', 'videos/1286-Bpkf41o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0353', 'dumbbell-one-arm-concentration-curl-on-stability-ball', 'ダンベル ワンハンド Concentration カール (on Stability Ball)', 'Dumbbell One Arm Concentration Curl (on Stability Ball)', 'ダンベル ワンハンド Concentration カール (on Stability Ball)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Concentration Curl (on Stability Ball) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', 'images/0353-k5IpyHg.jpg', 'videos/0353-k5IpyHg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1287', 'dumbbell-one-arm-decline-chest-press', 'ダンベル ワンハンド デクライン チェスト プレス', 'Dumbbell One Arm Decline Chest Press', 'ダンベル ワンハンド デクライン チェスト プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Decline Chest Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1287-REGM1dE.jpg', 'videos/1287-REGM1dE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1288', 'dumbbell-one-arm-fly-on-exercise-ball', 'ダンベル ワンハンド フライ On Exercise Ball', 'Dumbbell One Arm Fly On Exercise Ball', 'ダンベル ワンハンド フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1288-Am02iPd.jpg', 'videos/1288-Am02iPd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1736', 'dumbbell-one-arm-french-press-on-exercise-ball', 'ダンベル ワンハンド French プレス On Exercise Ball', 'Dumbbell One Arm French Press On Exercise Ball', 'ダンベル ワンハンド French プレス On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm French Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1736-ziFKQXP.jpg', 'videos/1736-ziFKQXP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1663', 'dumbbell-one-arm-hammer-preacher-curl', 'ダンベル ワンハンド ハンマー Preacher カール', 'Dumbbell One Arm Hammer Preacher Curl', 'ダンベル ワンハンド ハンマー Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Hammer Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1663-4dF3maG.jpg', 'videos/1663-4dF3maG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1621', 'dumbbell-one-arm-hammer-press-on-exercise-ball', 'ダンベル ワンハンド ハンマー プレス On Exercise Ball', 'Dumbbell One Arm Hammer Press On Exercise Ball', 'ダンベル ワンハンド ハンマー プレス On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Hammer Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1621-VYmYxK5.jpg', 'videos/1621-VYmYxK5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1289', 'dumbbell-one-arm-incline-chest-press', 'ダンベル ワンハンド インクライン チェスト プレス', 'Dumbbell One Arm Incline Chest Press', 'ダンベル ワンハンド インクライン チェスト プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Incline Chest Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1289-PDaMuyV.jpg', 'videos/1289-PDaMuyV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0354', 'dumbbell-one-arm-kickback', 'ダンベル ワンハンド キックバック', 'Dumbbell One Arm Kickback', 'ダンベル ワンハンド キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0354-bQy2Eni.jpg', 'videos/0354-bQy2Eni.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0355', 'dumbbell-one-arm-lateral-raise', 'ダンベル ワンハンド サイド レイズ', 'Dumbbell One Arm Lateral Raise', 'ダンベル ワンハンド サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Lateral Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0355-n5cWCsI.jpg', 'videos/0355-n5cWCsI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0356', 'dumbbell-one-arm-lateral-raise-with-support', 'ダンベル ワンハンド サイド レイズ With Support', 'Dumbbell One Arm Lateral Raise With Support', 'ダンベル ワンハンド サイド レイズ With Supportは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Lateral Raise With Support is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0356-Yg7MJAT.jpg', 'videos/0356-Yg7MJAT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1290', 'dumbbell-one-arm-press-on-exercise-ball', 'ダンベル ワンハンド プレス On Exercise Ball', 'Dumbbell One Arm Press On Exercise Ball', 'ダンベル ワンハンド プレス On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1290-QZFv5ui.jpg', 'videos/1290-QZFv5ui.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1665', 'dumbbell-one-arm-prone-curl', 'ダンベル ワンハンド プローン カール', 'Dumbbell One Arm Prone Curl', 'ダンベル ワンハンド プローン カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Prone Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1665-JWjujiY.jpg', 'videos/1665-JWjujiY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1666', 'dumbbell-one-arm-prone-hammer-curl', 'ダンベル ワンハンド プローン ハンマー カール', 'Dumbbell One Arm Prone Hammer Curl', 'ダンベル ワンハンド プローン ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Prone Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1666-LIGZSTA.jpg', 'videos/1666-LIGZSTA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1291', 'dumbbell-one-arm-pullover-on-exercise-ball', 'ダンベル ワンハンド プルオーバー On Exercise Ball', 'Dumbbell One Arm Pullover On Exercise Ball', 'ダンベル ワンハンド プルオーバー On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Pullover On Exercise Ball is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1291-bQHPBU3.jpg', 'videos/1291-bQHPBU3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0358', 'dumbbell-one-arm-reverse-wrist-curl', 'ダンベル ワンハンド Reverse リスト カール', 'Dumbbell One Arm Reverse Wrist Curl', 'ダンベル ワンハンド Reverse リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Reverse Wrist Curl is an effective exercise targeting the wrist extensors using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0358-BwSNDGt.jpg', 'videos/0358-BwSNDGt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0359', 'dumbbell-one-arm-reverse-fly-with-support', 'ダンベル ワンハンド Reverse フライ (with Support)', 'Dumbbell One Arm Reverse Fly (with Support)', 'ダンベル ワンハンド Reverse フライ (with Support)は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Reverse Fly (with Support) is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0359-e25F58f.jpg', 'videos/0359-e25F58f.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1622', 'dumbbell-one-arm-reverse-grip-press', 'ダンベル ワンハンド Reverse Grip プレス', 'Dumbbell One Arm Reverse Grip Press', 'ダンベル ワンハンド Reverse Grip プレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Reverse Grip Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1622-Ze7MoIb.jpg', 'videos/1622-Ze7MoIb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1414', 'dumbbell-one-arm-reverse-preacher-curl', 'ダンベル ワンハンド Reverse Preacher カール', 'Dumbbell One Arm Reverse Preacher Curl', 'ダンベル ワンハンド Reverse Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Reverse Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1414-bWxq4op.jpg', 'videos/1414-bWxq4op.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1667', 'dumbbell-one-arm-reverse-spider-curl', 'ダンベル ワンハンド Reverse Spider カール', 'Dumbbell One Arm Reverse Spider Curl', 'ダンベル ワンハンド Reverse Spider カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Reverse Spider Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1667-VdLZ3nB.jpg', 'videos/1667-VdLZ3nB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1668', 'dumbbell-one-arm-seated-bicep-curl-on-exercise-ball', 'ダンベル ワンハンド シーテッド Bicep カール On Exercise Ball', 'Dumbbell One Arm Seated Bicep Curl On Exercise Ball', 'ダンベル ワンハンド シーテッド Bicep カール On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Seated Bicep Curl On Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1668-s999Hdo.jpg', 'videos/1668-s999Hdo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1669', 'dumbbell-one-arm-seated-hammer-curl', 'ダンベル ワンハンド シーテッド ハンマー カール', 'Dumbbell One Arm Seated Hammer Curl', 'ダンベル ワンハンド シーテッド ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Seated Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1669-jK2hZ6n.jpg', 'videos/1669-jK2hZ6n.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1415', 'dumbbell-one-arm-seated-neutral-wrist-curl', 'ダンベル ワンハンド シーテッド Neutral リスト カール', 'Dumbbell One Arm Seated Neutral Wrist Curl', 'ダンベル ワンハンド シーテッド Neutral リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Seated Neutral Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."]', 'images/1415-YtaCTYl.jpg', 'videos/1415-YtaCTYl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0361', 'dumbbell-one-arm-shoulder-press', 'ダンベル ワンハンド Shoulder プレス', 'Dumbbell One Arm Shoulder Press', 'ダンベル ワンハンド Shoulder プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Shoulder Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0361-84RyJf8.jpg', 'videos/0361-84RyJf8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0360', 'dumbbell-one-arm-shoulder-press-v-2', 'ダンベル ワンハンド Shoulder プレス V. 2', 'Dumbbell One Arm Shoulder Press V. 2', 'ダンベル ワンハンド Shoulder プレス V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Shoulder Press V. 2 is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0360-1TkiAFK.jpg', 'videos/0360-1TkiAFK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3888', 'dumbbell-one-arm-snatch', 'ダンベル ワンハンド Snatch', 'Dumbbell One Arm Snatch', 'ダンベル ワンハンド Snatchは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Snatch is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/3888-6pTkI99.jpg', 'videos/3888-6pTkI99.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1670', 'dumbbell-one-arm-standing-curl', 'ダンベル ワンハンド スタンディング カール', 'Dumbbell One Arm Standing Curl', 'ダンベル ワンハンド スタンディング カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Standing Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1670-ffQsyBj.jpg', 'videos/1670-ffQsyBj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1671', 'dumbbell-one-arm-standing-hammer-curl', 'ダンベル ワンハンド スタンディング ハンマー カール', 'Dumbbell One Arm Standing Hammer Curl', 'ダンベル ワンハンド スタンディング ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Standing Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1671-2sQGZ5b.jpg', 'videos/1671-2sQGZ5b.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0362', 'dumbbell-one-arm-triceps-extension-on-bench', 'ダンベル ワンハンド トライセップス エクステンション (on ベンチ)', 'Dumbbell One Arm Triceps Extension (on Bench)', 'ダンベル ワンハンド トライセップス エクステンション (on ベンチ)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Triceps Extension (on Bench) is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0362-nAuHPcD.jpg', 'videos/0362-nAuHPcD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0363', 'dumbbell-one-arm-upright-row', 'ダンベル ワンハンド Upright ロー', 'Dumbbell One Arm Upright Row', 'ダンベル ワンハンド Upright ローは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Upright Row is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0363-6cKQC5E.jpg', 'videos/0363-6cKQC5E.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0364', 'dumbbell-one-arm-wrist-curl', 'ダンベル ワンハンド リスト カール', 'Dumbbell One Arm Wrist Curl', 'ダンベル ワンハンド リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."]', 'images/0364-q8aHNoF.jpg', 'videos/0364-q8aHNoF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1672', 'dumbbell-one-arm-zottman-preacher-curl', 'ダンベル ワンハンド Zottman Preacher カール', 'Dumbbell One Arm Zottman Preacher Curl', 'ダンベル ワンハンド Zottman Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Arm Zottman Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1672-sxY5Biu.jpg', 'videos/1672-sxY5Biu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1292', 'dumbbell-one-leg-fly-on-exercise-ball', 'ダンベル One Leg フライ On Exercise Ball', 'Dumbbell One Leg Fly On Exercise Ball', 'ダンベル One Leg フライ On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell One Leg Fly On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1292-pH2x2jj.jpg', 'videos/1292-pH2x2jj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0365', 'dumbbell-over-bench-neutral-wrist-curl', 'ダンベル Over ベンチ Neutral リスト カール', 'Dumbbell Over Bench Neutral Wrist Curl', 'ダンベル Over ベンチ Neutral リスト カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench Neutral Wrist Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0365-BKa8dmT.jpg', 'videos/0365-BKa8dmT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0366', 'dumbbell-over-bench-one-arm-neutral-wrist-curl', 'ダンベル Over ベンチ ワンハンド Neutral リスト カール', 'Dumbbell Over Bench One Arm Neutral Wrist Curl', 'ダンベル Over ベンチ ワンハンド Neutral リスト カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench One Arm Neutral Wrist Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0366-IvV6C9M.jpg', 'videos/0366-IvV6C9M.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1441', 'dumbbell-over-bench-one-arm-reverse-wrist-curl', 'ダンベル Over ベンチ ワンハンド Reverse リスト カール', 'Dumbbell Over Bench One Arm Reverse Wrist Curl', 'ダンベル Over ベンチ ワンハンド Reverse リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench One Arm Reverse Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1441-4Jc36XM.jpg', 'videos/1441-4Jc36XM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0367', 'dumbbell-over-bench-one-arm-wrist-curl', 'ダンベル Over ベンチ ワンハンド リスト カール', 'Dumbbell Over Bench One Arm Wrist Curl', 'ダンベル Over ベンチ ワンハンド リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench One Arm Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0367-KI1DjNN.jpg', 'videos/0367-KI1DjNN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0368', 'dumbbell-over-bench-revers-wrist-curl', 'ダンベル Over ベンチ Revers リスト カール', 'Dumbbell Over Bench Revers Wrist Curl', 'ダンベル Over ベンチ Revers リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench Revers Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0368-3tAXPQ6.jpg', 'videos/0368-3tAXPQ6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0369', 'dumbbell-over-bench-wrist-curl', 'ダンベル Over ベンチ リスト カール', 'Dumbbell Over Bench Wrist Curl', 'ダンベル Over ベンチ リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Over Bench Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0369-D1xYJAU.jpg', 'videos/0369-D1xYJAU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1329', 'dumbbell-palm-rotational-bent-over-row', 'ダンベル Palm Rotational Bent Over ロー', 'Dumbbell Palm Rotational Bent Over Row', 'ダンベル Palm Rotational Bent Over ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Palm Rotational Bent Over Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1329-wt6rwjk.jpg', 'videos/1329-wt6rwjk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1623', 'dumbbell-palms-in-incline-bench-press', 'ダンベル Palms In インクライン ベンチプレス', 'Dumbbell Palms In Incline Bench Press', 'ダンベル Palms In インクライン ベンチプレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Palms In Incline Bench Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1623-8eqjhOl.jpg', 'videos/1623-8eqjhOl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0370', 'dumbbell-peacher-hammer-curl', 'ダンベル Peacher ハンマー カール', 'Dumbbell Peacher Hammer Curl', 'ダンベル Peacher ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Peacher Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', 'images/0370-F1KxjBa.jpg', 'videos/0370-F1KxjBa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0371', 'dumbbell-plyo-squat', 'ダンベル Plyo スクワット', 'Dumbbell Plyo Squat', 'ダンベル Plyo スクワットは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Plyo Squat is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."]', 'images/0371-S4pwGlc.jpg', 'videos/0371-S4pwGlc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0372', 'dumbbell-preacher-curl', 'ダンベル Preacher カール', 'Dumbbell Preacher Curl', 'ダンベル Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0372-jivWf8n.jpg', 'videos/0372-jivWf8n.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1673', 'dumbbell-preacher-curl-over-exercise-ball', 'ダンベル Preacher カール Over Exercise Ball', 'Dumbbell Preacher Curl Over Exercise Ball', 'ダンベル Preacher カール Over Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Preacher Curl Over Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1673-hwygydB.jpg', 'videos/1673-hwygydB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1293', 'dumbbell-press-on-exercise-ball', 'ダンベル プレス On Exercise Ball', 'Dumbbell Press On Exercise Ball', 'ダンベル プレス On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Press On Exercise Ball is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1293-O8o7q4d.jpg', 'videos/1293-O8o7q4d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0373', 'dumbbell-pronate-grip-triceps-extension', 'ダンベル Pronate-grip トライセップス エクステンション', 'Dumbbell Pronate-grip Triceps Extension', 'ダンベル Pronate-grip トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Pronate-grip Triceps Extension is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0373-bpJL2Qs.jpg', 'videos/0373-bpJL2Qs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0374', 'dumbbell-prone-incline-curl', 'ダンベル プローン インクライン カール', 'Dumbbell Prone Incline Curl', 'ダンベル プローン インクライン カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Prone Incline Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0374-mwpPcr1.jpg', 'videos/0374-mwpPcr1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1674', 'dumbbell-prone-incline-hammer-curl', 'ダンベル プローン インクライン ハンマー カール', 'Dumbbell Prone Incline Hammer Curl', 'ダンベル プローン インクライン ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Prone Incline Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1674-cWemPG8.jpg', 'videos/1674-cWemPG8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0375', 'dumbbell-pullover', 'ダンベル プルオーバー', 'Dumbbell Pullover', 'ダンベル プルオーバーは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Pullover is an effective exercise targeting the latissimus dorsi using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0375-9XjtHvS.jpg', 'videos/0375-9XjtHvS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1294', 'dumbbell-pullover-hip-extension-on-exercise-ball', 'ダンベル プルオーバー ヒップ エクステンション On Exercise Ball', 'Dumbbell Pullover Hip Extension On Exercise Ball', 'ダンベル プルオーバー ヒップ エクステンション On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Pullover Hip Extension On Exercise Ball is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1294-lI7easp.jpg', 'videos/1294-lI7easp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1295', 'dumbbell-pullover-on-exercise-ball', 'ダンベル プルオーバー On Exercise Ball', 'Dumbbell Pullover On Exercise Ball', 'ダンベル プルオーバー On Exercise Ballは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Pullover On Exercise Ball is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1295-FSD6PGL.jpg', 'videos/1295-FSD6PGL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1700', 'dumbbell-push-press', 'ダンベル Push プレス', 'Dumbbell Push Press', 'ダンベル Push プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Push Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."]', 'images/1700-FS63wTN.jpg', 'videos/1700-FS63wTN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0376', 'dumbbell-raise', 'ダンベル レイズ', 'Dumbbell Raise', 'ダンベル レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0376-c9MnDRp.jpg', 'videos/0376-c9MnDRp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2292', 'dumbbell-rear-delt-raise', 'ダンベル リア Delt レイズ', 'Dumbbell Rear Delt Raise', 'ダンベル リア Delt レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Delt Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2292-mu5Guxt.jpg', 'videos/2292-mu5Guxt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0377', 'dumbbell-rear-delt-row_shoulder', 'ダンベル リア Delt Row_shoulder', 'Dumbbell Rear Delt Row_shoulder', 'ダンベル リア Delt Row_shoulderは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Delt Row_shoulder is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0377-EKXOMEh.jpg', 'videos/0377-EKXOMEh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0378', 'dumbbell-rear-fly', 'ダンベル リア フライ', 'Dumbbell Rear Fly', 'ダンベル リア フライは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Fly is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0378-8DiFDVA.jpg', 'videos/0378-8DiFDVA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0380', 'dumbbell-rear-lateral-raise', 'ダンベル リア サイド レイズ', 'Dumbbell Rear Lateral Raise', 'ダンベル リア サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0380-v1qBec9.jpg', 'videos/0380-v1qBec9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0379', 'dumbbell-rear-lateral-raise-support-head', 'ダンベル リア サイド レイズ (support Head)', 'Dumbbell Rear Lateral Raise (support Head)', 'ダンベル リア サイド レイズ (support Head)は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Lateral Raise (support Head) is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0379-UzkLrem.jpg', 'videos/0379-UzkLrem.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0381', 'dumbbell-rear-lunge', 'ダンベル リア ランジ', 'Dumbbell Rear Lunge', 'ダンベル リア ランジは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rear Lunge is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."]', 'images/0381-SSsBDwB.jpg', 'videos/0381-SSsBDwB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0382', 'dumbbell-revers-grip-biceps-curl', 'ダンベル Revers Grip バイセップス カール', 'Dumbbell Revers Grip Biceps Curl', 'ダンベル Revers Grip バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Revers Grip Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0382-e4ojVhP.jpg', 'videos/0382-e4ojVhP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1624', 'dumbbell-reverse-bench-press', 'ダンベル Reverse ベンチプレス', 'Dumbbell Reverse Bench Press', 'ダンベル Reverse ベンチプレスは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Bench Press is an effective exercise targeting the triceps using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1624-UIbGx6H.jpg', 'videos/1624-UIbGx6H.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0383', 'dumbbell-reverse-fly', 'ダンベル Reverse フライ', 'Dumbbell Reverse Fly', 'ダンベル Reverse フライは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Fly is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0383-EAs3xL9.jpg', 'videos/0383-EAs3xL9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1330', 'dumbbell-reverse-grip-incline-bench-one-arm-row', 'ダンベル Reverse Grip インクライン ベンチ ワンハンド ロー', 'Dumbbell Reverse Grip Incline Bench One Arm Row', 'ダンベル Reverse Grip インクライン ベンチ ワンハンド ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Grip Incline Bench One Arm Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."]', 'images/1330-ZIViNh1.jpg', 'videos/1330-ZIViNh1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1331', 'dumbbell-reverse-grip-incline-bench-two-arm-row', 'ダンベル Reverse Grip インクライン ベンチ Two Arm ロー', 'Dumbbell Reverse Grip Incline Bench Two Arm Row', 'ダンベル Reverse Grip インクライン ベンチ Two Arm ローは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Grip Incline Bench Two Arm Row is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1331-9pQSkH8.jpg', 'videos/1331-9pQSkH8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2327', 'dumbbell-reverse-grip-row-female', 'ダンベル Reverse Grip ロー (female)', 'Dumbbell Reverse Grip Row (female)', 'ダンベル Reverse Grip ロー (female)は、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Grip Row (female) is an effective exercise targeting the biceps using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2327-Nh3mvOO.jpg', 'videos/2327-Nh3mvOO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0384', 'dumbbell-reverse-preacher-curl', 'ダンベル Reverse Preacher カール', 'Dumbbell Reverse Preacher Curl', 'ダンベル Reverse Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0384-O8Aq69u.jpg', 'videos/0384-O8Aq69u.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1675', 'dumbbell-reverse-spider-curl', 'ダンベル Reverse Spider カール', 'Dumbbell Reverse Spider Curl', 'ダンベル Reverse Spider カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Spider Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1675-6sMAmNv.jpg', 'videos/1675-6sMAmNv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0385', 'dumbbell-reverse-wrist-curl', 'ダンベル Reverse リスト カール', 'Dumbbell Reverse Wrist Curl', 'ダンベル Reverse リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Reverse Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0385-BLCvwr2.jpg', 'videos/0385-BLCvwr2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1459', 'dumbbell-romanian-deadlift', 'ダンベル Romanian デッドリフト', 'Dumbbell Romanian Deadlift', 'ダンベル Romanian デッドリフトは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Romanian Deadlift is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1459-rR0LJzx.jpg', 'videos/1459-rR0LJzx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0386', 'dumbbell-rotation-reverse-fly', 'ダンベル Rotation Reverse フライ', 'Dumbbell Rotation Reverse Fly', 'ダンベル Rotation Reverse フライは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Rotation Reverse Fly is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0386-prbWx1D.jpg', 'videos/0386-prbWx1D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2397', 'dumbbell-scott-press', 'ダンベル Scott プレス', 'Dumbbell Scott Press', 'ダンベル Scott プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Scott Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2397-5vfAI0I.jpg', 'videos/2397-5vfAI0I.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0387', 'dumbbell-seated-alternate-front-raise', 'ダンベル シーテッド Alternate フロント レイズ', 'Dumbbell Seated Alternate Front Raise', 'ダンベル シーテッド Alternate フロント レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Alternate Front Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', 'images/0387-gH5fRsC.jpg', 'videos/0387-gH5fRsC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1676', 'dumbbell-seated-alternate-hammer-curl-on-exercise-ball', 'ダンベル シーテッド Alternate ハンマー カール On Exercise Ball', 'Dumbbell Seated Alternate Hammer Curl On Exercise Ball', 'ダンベル シーテッド Alternate ハンマー カール On Exercise Ballは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Alternate Hammer Curl On Exercise Ball is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1676-QLRmNeT.jpg', 'videos/1676-QLRmNeT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0388', 'dumbbell-seated-alternate-press', 'ダンベル シーテッド Alternate プレス', 'Dumbbell Seated Alternate Press', 'ダンベル シーテッド Alternate プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Alternate Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0388-QT5Q0nK.jpg', 'videos/0388-QT5Q0nK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3546', 'dumbbell-seated-alternate-shoulder', 'ダンベル シーテッド Alternate Shoulder', 'Dumbbell Seated Alternate Shoulder', 'ダンベル シーテッド Alternate Shoulderは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Alternate Shoulder is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."]', 'images/3546-q7qkONO.jpg', 'videos/3546-q7qkONO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0389', 'dumbbell-seated-bench-extension', 'ダンベル シーテッド ベンチ エクステンション', 'Dumbbell Seated Bench Extension', 'ダンベル シーテッド ベンチ エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Bench Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0389-JhYSVwT.jpg', 'videos/0389-JhYSVwT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2317', 'dumbbell-seated-bent-arm-lateral-raise', 'ダンベル シーテッド Bent Arm サイド レイズ', 'Dumbbell Seated Bent Arm Lateral Raise', 'ダンベル シーテッド Bent Arm サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Bent Arm Lateral Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2317-JzQbv7J.jpg', 'videos/2317-JzQbv7J.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1730', 'dumbbell-seated-bent-over-alternate-kickback', 'ダンベル シーテッド Bent Over Alternate キックバック', 'Dumbbell Seated Bent Over Alternate Kickback', 'ダンベル シーテッド Bent Over Alternate キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Bent Over Alternate Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1730-x0lwvfq.jpg', 'videos/1730-x0lwvfq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1737', 'dumbbell-seated-bent-over-triceps-extension', 'ダンベル シーテッド Bent Over トライセップス エクステンション', 'Dumbbell Seated Bent Over Triceps Extension', 'ダンベル シーテッド Bent Over トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Bent Over Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1737-4ievMJ9.jpg', 'videos/1737-4ievMJ9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1677', 'dumbbell-seated-bicep-curl', 'ダンベル シーテッド Bicep カール', 'Dumbbell Seated Bicep Curl', 'ダンベル シーテッド Bicep カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Bicep Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1677-xiA6lRr.jpg', 'videos/1677-xiA6lRr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0390', 'dumbbell-seated-biceps-curl-on-stability-ball', 'ダンベル シーテッド バイセップス カール (on Stability Ball)', 'Dumbbell Seated Biceps Curl (on Stability Ball)', 'ダンベル シーテッド バイセップス カール (on Stability Ball)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Biceps Curl (on Stability Ball) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0390-WgJnBH5.jpg', 'videos/0390-WgJnBH5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3547', 'dumbbell-seated-biceps-curl-to-shoulder-press', 'ダンベル シーテッド バイセップス カール To Shoulder プレス', 'Dumbbell Seated Biceps Curl To Shoulder Press', 'ダンベル シーテッド バイセップス カール To Shoulder プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Biceps Curl To Shoulder Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', 'images/3547-OeL23VY.jpg', 'videos/3547-OeL23VY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1379', 'dumbbell-seated-calf-raise', 'ダンベル シーテッド カーフ レイズ', 'Dumbbell Seated Calf Raise', 'ダンベル シーテッド カーフ レイズは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Calf Raise is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1379-r29jP7S.jpg', 'videos/1379-r29jP7S.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0391', 'dumbbell-seated-curl', 'ダンベル シーテッド カール', 'Dumbbell Seated Curl', 'ダンベル シーテッド カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0391-TiaZTxx.jpg', 'videos/0391-TiaZTxx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0392', 'dumbbell-seated-front-raise', 'ダンベル シーテッド フロント レイズ', 'Dumbbell Seated Front Raise', 'ダンベル シーテッド フロント レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Front Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0392-Ys97II0.jpg', 'videos/0392-Ys97II0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1678', 'dumbbell-seated-hammer-curl', 'ダンベル シーテッド ハンマー カール', 'Dumbbell Seated Hammer Curl', 'ダンベル シーテッド ハンマー カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Hammer Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1678-IGtBdNT.jpg', 'videos/1678-IGtBdNT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0393', 'dumbbell-seated-inner-biceps-curl', 'ダンベル シーテッド Inner バイセップス カール', 'Dumbbell Seated Inner Biceps Curl', 'ダンベル シーテッド Inner バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Inner Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0393-KXyoEtA.jpg', 'videos/0393-KXyoEtA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0394', 'dumbbell-seated-kickback', 'ダンベル シーテッド キックバック', 'Dumbbell Seated Kickback', 'ダンベル シーテッド キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0394-en550rk.jpg', 'videos/0394-en550rk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0396', 'dumbbell-seated-lateral-raise', 'ダンベル シーテッド サイド レイズ', 'Dumbbell Seated Lateral Raise', 'ダンベル シーテッド サイド レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Lateral Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0396-hxyTtWj.jpg', 'videos/0396-hxyTtWj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0395', 'dumbbell-seated-lateral-raise-v-2', 'ダンベル シーテッド サイド レイズ V. 2', 'Dumbbell Seated Lateral Raise V. 2', 'ダンベル シーテッド サイド レイズ V. 2は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Lateral Raise V. 2 is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0395-hrrS0Ed.jpg', 'videos/0395-hrrS0Ed.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0397', 'dumbbell-seated-neutral-wrist-curl', 'ダンベル シーテッド Neutral リスト カール', 'Dumbbell Seated Neutral Wrist Curl', 'ダンベル シーテッド Neutral リスト カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Neutral Wrist Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0397-uJmK7Z1.jpg', 'videos/0397-uJmK7Z1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1679', 'dumbbell-seated-one-arm-bicep-curl-on-exercise-ball-with-leg-raised', 'ダンベル シーテッド ワンハンド Bicep カール On Exercise Ball With Leg Raised', 'Dumbbell Seated One Arm Bicep Curl On Exercise Ball With Leg Raised', 'ダンベル シーテッド ワンハンド Bicep カール On Exercise Ball With Leg Raisedは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Arm Bicep Curl On Exercise Ball With Leg Raised is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', 'images/1679-84sESNy.jpg', 'videos/1679-84sESNy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0398', 'dumbbell-seated-one-arm-kickback', 'ダンベル シーテッド ワンハンド キックバック', 'Dumbbell Seated One Arm Kickback', 'ダンベル シーテッド ワンハンド キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Arm Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0398-VQ3sNCn.jpg', 'videos/0398-VQ3sNCn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0399', 'dumbbell-seated-one-arm-rotate', 'ダンベル シーテッド ワンハンド Rotate', 'Dumbbell Seated One Arm Rotate', 'ダンベル シーテッド ワンハンド Rotateは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Arm Rotate is an effective exercise targeting the shoulders using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0399-7f2jsqP.jpg', 'videos/0399-7f2jsqP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0400', 'dumbbell-seated-one-leg-calf-raise', 'ダンベル シーテッド One Leg カーフ レイズ', 'Dumbbell Seated One Leg Calf Raise', 'ダンベル シーテッド One Leg カーフ レイズは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Leg Calf Raise is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0400-Ia7tumC.jpg', 'videos/0400-Ia7tumC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1380', 'dumbbell-seated-one-leg-calf-raise-hammer-grip', 'ダンベル シーテッド One Leg カーフ レイズ - ハンマー Grip', 'Dumbbell Seated One Leg Calf Raise - Hammer Grip', 'ダンベル シーテッド One Leg カーフ レイズ - ハンマー Gripは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Leg Calf Raise - Hammer Grip is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', 'images/1380-FxhcxUW.jpg', 'videos/1380-FxhcxUW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1381', 'dumbbell-seated-one-leg-calf-raise-palm-up', 'ダンベル シーテッド One Leg カーフ レイズ - Palm Up', 'Dumbbell Seated One Leg Calf Raise - Palm Up', 'ダンベル シーテッド One Leg カーフ レイズ - Palm Upは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated One Leg Calf Raise - Palm Up is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1381-VW88JNd.jpg', 'videos/1381-VW88JNd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0401', 'dumbbell-seated-palms-up-wrist-curl', 'ダンベル シーテッド Palms Up リスト カール', 'Dumbbell Seated Palms Up Wrist Curl', 'ダンベル シーテッド Palms Up リスト カールは、ダンベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Palms Up Wrist Curl is an effective exercise targeting the biceps using dumbbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0401-2dImyQ8.jpg', 'videos/0401-2dImyQ8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0402', 'dumbbell-seated-preacher-curl', 'ダンベル シーテッド Preacher カール', 'Dumbbell Seated Preacher Curl', 'ダンベル シーテッド Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0402-7D5bgLT.jpg', 'videos/0402-7D5bgLT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0403', 'dumbbell-seated-revers-grip-concentration-curl', 'ダンベル シーテッド Revers Grip Concentration カール', 'Dumbbell Seated Revers Grip Concentration Curl', 'ダンベル シーテッド Revers Grip Concentration カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Revers Grip Concentration Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0403-lyKCLmK.jpg', 'videos/0403-lyKCLmK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1738', 'dumbbell-seated-reverse-grip-one-arm-overhead-tricep-extension', 'ダンベル シーテッド Reverse Grip ワンハンド オーバーヘッド Tricep エクステンション', 'Dumbbell Seated Reverse Grip One Arm Overhead Tricep Extension', 'ダンベル シーテッド Reverse Grip ワンハンド オーバーヘッド Tricep エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Reverse Grip One Arm Overhead Tricep Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1738-5fKX7wi.jpg', 'videos/1738-5fKX7wi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0405', 'dumbbell-seated-shoulder-press', 'ダンベル シーテッド Shoulder プレス', 'Dumbbell Seated Shoulder Press', 'ダンベル シーテッド Shoulder プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Shoulder Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0405-znQUdHY.jpg', 'videos/0405-znQUdHY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0404', 'dumbbell-seated-shoulder-press-parallel-grip', 'ダンベル シーテッド Shoulder プレス (parallel Grip)', 'Dumbbell Seated Shoulder Press (parallel Grip)', 'ダンベル シーテッド Shoulder プレス (parallel Grip)は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Shoulder Press (parallel Grip) is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0404-f1jf47L.jpg', 'videos/0404-f1jf47L.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2188', 'dumbbell-seated-triceps-extension', 'ダンベル シーテッド トライセップス エクステンション', 'Dumbbell Seated Triceps Extension', 'ダンベル シーテッド トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Seated Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2188-kont8Ut.jpg', 'videos/2188-kont8Ut.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0406', 'dumbbell-shrug', 'ダンベル シュラッグ', 'Dumbbell Shrug', 'ダンベル シュラッグは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Shrug is an effective exercise targeting the shoulders using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0406-NJzBsGJ.jpg', 'videos/0406-NJzBsGJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0407', 'dumbbell-side-bend', 'ダンベル Side Bend', 'Dumbbell Side Bend', 'ダンベル Side Bendは、ダンベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Side Bend is an effective exercise targeting the obliques using dumbbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."]', 'images/0407-IpONWYv.jpg', 'videos/0407-IpONWYv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0408', 'dumbbell-side-lying-one-hand-raise', 'ダンベル Side ライイング One Hand レイズ', 'Dumbbell Side Lying One Hand Raise', 'ダンベル Side ライイング One Hand レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Side Lying One Hand Raise is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0408-fTlkJop.jpg', 'videos/0408-fTlkJop.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3664', 'dumbbell-side-plank-with-rear-fly', 'ダンベル Side プランク With リア フライ', 'Dumbbell Side Plank With Rear Fly', 'ダンベル Side プランク With リア フライは、ダンベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Side Plank With Rear Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/3664-X6ytgYZ.jpg', 'videos/3664-X6ytgYZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3548', 'dumbbell-single-arm-overhead-carry', 'ダンベル シングルアーム オーバーヘッド Carry', 'Dumbbell Single Arm Overhead Carry', 'ダンベル シングルアーム オーバーヘッド Carryは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Arm Overhead Carry is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."]', 'images/3548-mWBtgmb.jpg', 'videos/3548-mWBtgmb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0409', 'dumbbell-single-leg-calf-raise', 'ダンベル シングルレッグ カーフ レイズ', 'Dumbbell Single Leg Calf Raise', 'ダンベル シングルレッグ カーフ レイズは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Leg Calf Raise is an effective exercise targeting the ankles using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."]', 'images/0409-1kB3Wmk.jpg', 'videos/0409-1kB3Wmk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1757', 'dumbbell-single-leg-deadlift', 'ダンベル シングルレッグ デッドリフト', 'Dumbbell Single Leg Deadlift', 'ダンベル シングルレッグ デッドリフトは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Leg Deadlift is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1757-gKozT8X.jpg', 'videos/1757-gKozT8X.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2805', 'dumbbell-single-leg-deadlift-with-stepbox-support', 'ダンベル シングルレッグ デッドリフト With Stepbox Support', 'Dumbbell Single Leg Deadlift With Stepbox Support', 'ダンベル シングルレッグ デッドリフト With Stepbox Supportは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Leg Deadlift With Stepbox Support is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/2805-daBmy1Y.jpg', 'videos/2805-daBmy1Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0410', 'dumbbell-single-leg-split-squat', 'ダンベル シングルレッグ Split スクワット', 'Dumbbell Single Leg Split Squat', 'ダンベル シングルレッグ Split スクワットは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Leg Split Squat is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/0410-qx4fgX7.jpg', 'videos/0410-qx4fgX7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0411', 'dumbbell-single-leg-squat', 'ダンベル シングルレッグ スクワット', 'Dumbbell Single Leg Squat', 'ダンベル シングルレッグ スクワットは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Single Leg Squat is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0411-H6ybluc.jpg', 'videos/0411-H6ybluc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0413', 'dumbbell-squat', 'ダンベル スクワット', 'Dumbbell Squat', 'ダンベル スクワットは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Squat is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0413-HsvHqgf.jpg', 'videos/0413-HsvHqgf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3560', 'dumbbell-standing-alternate-hammer-curl-and-press', 'ダンベル スタンディング Alternate ハンマー カール And プレス', 'Dumbbell Standing Alternate Hammer Curl And Press', 'ダンベル スタンディング Alternate ハンマー カール And プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Alternate Hammer Curl And Press is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."]', 'images/3560-LeaZOIz.jpg', 'videos/3560-LeaZOIz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0414', 'dumbbell-standing-alternate-overhead-press', 'ダンベル スタンディング Alternate オーバーヘッド プレス', 'Dumbbell Standing Alternate Overhead Press', 'ダンベル スタンディング Alternate オーバーヘッド プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Alternate Overhead Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0414-bBi35y3.jpg', 'videos/0414-bBi35y3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0415', 'dumbbell-standing-alternate-raise', 'ダンベル スタンディング Alternate レイズ', 'Dumbbell Standing Alternate Raise', 'ダンベル スタンディング Alternate レイズは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Alternate Raise is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', 'images/0415-SxHteRW.jpg', 'videos/0415-SxHteRW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1739', 'dumbbell-standing-alternating-tricep-kickback', 'ダンベル スタンディング Alternating Tricep キックバック', 'Dumbbell Standing Alternating Tricep Kickback', 'ダンベル スタンディング Alternating Tricep キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Alternating Tricep Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."]', 'images/1739-Gi2BXfK.jpg', 'videos/1739-Gi2BXfK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2143', 'dumbbell-standing-around-world', 'ダンベル スタンディング Around World', 'Dumbbell Standing Around World', 'ダンベル スタンディング Around Worldは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Around World is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2143-RSOsp5d.jpg', 'videos/2143-RSOsp5d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1740', 'dumbbell-standing-bent-over-one-arm-triceps-extension', 'ダンベル スタンディング Bent Over ワンハンド トライセップス エクステンション', 'Dumbbell Standing Bent Over One Arm Triceps Extension', 'ダンベル スタンディング Bent Over ワンハンド トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Bent Over One Arm Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1740-CJwa0vD.jpg', 'videos/1740-CJwa0vD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1741', 'dumbbell-standing-bent-over-two-arm-triceps-extension', 'ダンベル スタンディング Bent Over Two Arm トライセップス エクステンション', 'Dumbbell Standing Bent Over Two Arm Triceps Extension', 'ダンベル スタンディング Bent Over Two Arm トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Bent Over Two Arm Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1741-3T12T87.jpg', 'videos/1741-3T12T87.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0416', 'dumbbell-standing-biceps-curl', 'ダンベル スタンディング バイセップス カール', 'Dumbbell Standing Biceps Curl', 'ダンベル スタンディング バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0416-3s4NnTh.jpg', 'videos/0416-3s4NnTh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0417', 'dumbbell-standing-calf-raise', 'ダンベル スタンディング カーフ レイズ', 'Dumbbell Standing Calf Raise', 'ダンベル スタンディング カーフ レイズは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Calf Raise is an effective exercise targeting the ankles using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0417-dPmaUaU.jpg', 'videos/0417-dPmaUaU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0418', 'dumbbell-standing-concentration-curl', 'ダンベル スタンディング Concentration カール', 'Dumbbell Standing Concentration Curl', 'ダンベル スタンディング Concentration カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Concentration Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0418-7inpWch.jpg', 'videos/0418-7inpWch.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0419', 'dumbbell-standing-front-raise-above-head', 'ダンベル スタンディング フロント レイズ Above Head', 'Dumbbell Standing Front Raise Above Head', 'ダンベル スタンディング フロント レイズ Above Headは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Front Raise Above Head is an effective exercise targeting the trapezius using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0419-laVRfDf.jpg', 'videos/0419-laVRfDf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2321', 'dumbbell-standing-inner-biceps-curl-v-2', 'ダンベル スタンディング Inner バイセップス カール V. 2', 'Dumbbell Standing Inner Biceps Curl V. 2', 'ダンベル スタンディング Inner バイセップス カール V. 2は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Inner Biceps Curl V. 2 is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', 'images/2321-vKilzz3.jpg', 'videos/2321-vKilzz3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0420', 'dumbbell-standing-kickback', 'ダンベル スタンディング キックバック', 'Dumbbell Standing Kickback', 'ダンベル スタンディング キックバックは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Kickback is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0420-UmpPAAe.jpg', 'videos/0420-UmpPAAe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0421', 'dumbbell-standing-one-arm-concentration-curl', 'ダンベル スタンディング ワンハンド Concentration カール', 'Dumbbell Standing One Arm Concentration Curl', 'ダンベル スタンディング ワンハンド Concentration カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Concentration Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0421-8fgqP5a.jpg', 'videos/0421-8fgqP5a.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0422', 'dumbbell-standing-one-arm-curl-over-incline-bench', 'ダンベル スタンディング ワンハンド カール (over インクライン ベンチ)', 'Dumbbell Standing One Arm Curl (over Incline Bench)', 'ダンベル スタンディング ワンハンド カール (over インクライン ベンチ)は、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Curl (over Incline Bench) is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/0422-BIb1tGo.jpg', 'videos/0422-BIb1tGo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1680', 'dumbbell-standing-one-arm-curl-over-incline-bench-1680', 'ダンベル スタンディング ワンハンド カール Over インクライン ベンチ', 'Dumbbell Standing One Arm Curl Over Incline Bench', 'ダンベル スタンディング ワンハンド カール Over インクライン ベンチは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Curl Over Incline Bench is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1680-EmlJR2y.jpg', 'videos/1680-EmlJR2y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0423', 'dumbbell-standing-one-arm-extension', 'ダンベル スタンディング ワンハンド エクステンション', 'Dumbbell Standing One Arm Extension', 'ダンベル スタンディング ワンハンド エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0423-BCUR88E.jpg', 'videos/0423-BCUR88E.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0424', 'dumbbell-standing-one-arm-palm-in-press', 'ダンベル スタンディング ワンハンド Palm In プレス', 'Dumbbell Standing One Arm Palm In Press', 'ダンベル スタンディング ワンハンド Palm In プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Palm In Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0424-ocYc6Db.jpg', 'videos/0424-ocYc6Db.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0425', 'dumbbell-standing-one-arm-reverse-curl', 'ダンベル スタンディング ワンハンド Reverse カール', 'Dumbbell Standing One Arm Reverse Curl', 'ダンベル スタンディング ワンハンド Reverse カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing One Arm Reverse Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0425-DU5Kkj2.jpg', 'videos/0425-DU5Kkj2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0426', 'dumbbell-standing-overhead-press', 'ダンベル スタンディング オーバーヘッド プレス', 'Dumbbell Standing Overhead Press', 'ダンベル スタンディング オーバーヘッド プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Overhead Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0426-A6wtbuL.jpg', 'videos/0426-A6wtbuL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0427', 'dumbbell-standing-palms-in-press', 'ダンベル スタンディング Palms In プレス', 'Dumbbell Standing Palms In Press', 'ダンベル スタンディング Palms In プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Palms In Press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0427-UilDHSs.jpg', 'videos/0427-UilDHSs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0428', 'dumbbell-standing-preacher-curl', 'ダンベル スタンディング Preacher カール', 'Dumbbell Standing Preacher Curl', 'ダンベル スタンディング Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0428-hq2hyDH.jpg', 'videos/0428-hq2hyDH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0429', 'dumbbell-standing-reverse-curl', 'ダンベル スタンディング Reverse カール', 'Dumbbell Standing Reverse Curl', 'ダンベル スタンディング Reverse カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Reverse Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0429-0IgNjSM.jpg', 'videos/0429-0IgNjSM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0430', 'dumbbell-standing-triceps-extension', 'ダンベル スタンディング トライセップス エクステンション', 'Dumbbell Standing Triceps Extension', 'ダンベル スタンディング トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0430-PdmaD0N.jpg', 'videos/0430-PdmaD0N.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2293', 'dumbbell-standing-zottman-preacher-curl', 'ダンベル スタンディング Zottman Preacher カール', 'Dumbbell Standing Zottman Preacher Curl', 'ダンベル スタンディング Zottman Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Standing Zottman Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."]', 'images/2293-P2nRiUa.jpg', 'videos/2293-P2nRiUa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1684', 'dumbbell-step-up-single-leg-balance-with-bicep-curl', 'ダンベル Step Up シングルレッグ Balance With Bicep カール', 'Dumbbell Step Up Single Leg Balance With Bicep Curl', 'ダンベル Step Up シングルレッグ Balance With Bicep カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Step Up Single Leg Balance With Bicep Curl is an effective exercise targeting the quadriceps using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."]', 'images/1684-76vfTdU.jpg', 'videos/1684-76vfTdU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0431', 'dumbbell-step-up', 'ダンベル Step-up', 'Dumbbell Step-up', 'ダンベル Step-upは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Step-up is an effective exercise targeting the quadriceps using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0431-aXtJhlg.jpg', 'videos/0431-aXtJhlg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2796', 'dumbbell-step-up-lunge', 'ダンベル Step-up ランジ', 'Dumbbell Step-up Lunge', 'ダンベル Step-up ランジは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Step-up Lunge is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."]', 'images/2796-gFyFj9z.jpg', 'videos/2796-gFyFj9z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2812', 'dumbbell-step-up-split-squat', 'ダンベル Step-up Split スクワット', 'Dumbbell Step-up Split Squat', 'ダンベル Step-up Split スクワットは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Step-up Split Squat is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."]', 'images/2812-QjE2DcA.jpg', 'videos/2812-QjE2DcA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0432', 'dumbbell-stiff-leg-deadlift', 'ダンベル Stiff Leg デッドリフト', 'Dumbbell Stiff Leg Deadlift', 'ダンベル Stiff Leg デッドリフトは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Stiff Leg Deadlift is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0432-5eLRITT.jpg', 'videos/0432-5eLRITT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0433', 'dumbbell-straight-arm-pullover', 'ダンベル Straight Arm プルオーバー', 'Dumbbell Straight Arm Pullover', 'ダンベル Straight Arm プルオーバーは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Straight Arm Pullover is an effective exercise targeting the latissimus dorsi using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0433-i8BdLTK.jpg', 'videos/0433-i8BdLTK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0434', 'dumbbell-straight-leg-deadlift', 'ダンベル Straight Leg デッドリフト', 'Dumbbell Straight Leg Deadlift', 'ダンベル Straight Leg デッドリフトは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Straight Leg Deadlift is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0434-oom75KC.jpg', 'videos/0434-oom75KC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2808', 'dumbbell-sumo-pull-through', 'ダンベル Sumo Pull Through', 'Dumbbell Sumo Pull Through', 'ダンベル Sumo Pull Throughは、ダンベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Sumo Pull Through is an effective exercise targeting the hamstrings using dumbbell.', 'mg-glutes', 'Beginner', 'compound', 'pull', 'lower', '["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."]', 'images/2808-BmrwWzo.jpg', 'videos/2808-BmrwWzo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2803', 'dumbbell-supported-squat', 'ダンベル Supported スクワット', 'Dumbbell Supported Squat', 'ダンベル Supported スクワットは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Supported Squat is an effective exercise targeting the glutes using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2803-r5DgrW9.jpg', 'videos/2803-r5DgrW9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0436', 'dumbbell-tate-press', 'ダンベル Tate プレス', 'Dumbbell Tate Press', 'ダンベル Tate プレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Tate Press is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."]', 'images/0436-s5PdDyY.jpg', 'videos/0436-s5PdDyY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1742', 'dumbbell-tricep-kickback-with-stork-stance', 'ダンベル Tricep キックバック With Stork Stance', 'Dumbbell Tricep Kickback With Stork Stance', 'ダンベル Tricep キックバック With Stork Stanceは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Tricep Kickback With Stork Stance is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1742-wOLmCXc.jpg', 'videos/1742-wOLmCXc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1743', 'dumbbell-twisting-bench-press', 'ダンベル Twisting ベンチプレス', 'Dumbbell Twisting Bench Press', 'ダンベル Twisting ベンチプレスは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Twisting Bench Press is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."]', 'images/1743-z6TAHoT.jpg', 'videos/1743-z6TAHoT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0437', 'dumbbell-upright-row', 'ダンベル Upright ロー', 'Dumbbell Upright Row', 'ダンベル Upright ローは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Upright Row is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0437-ainizkb.jpg', 'videos/0437-ainizkb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1765', 'dumbbell-upright-row-back-pov', 'ダンベル Upright ロー (バック Pov)', 'Dumbbell Upright Row (back Pov)', 'ダンベル Upright ロー (バック Pov)は、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Upright Row (back Pov) is an effective exercise targeting the traps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1765-Iptlv6x.jpg', 'videos/1765-Iptlv6x.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0864', 'dumbbell-upright-shoulder-external-rotation', 'ダンベル Upright Shoulder External Rotation', 'Dumbbell Upright Shoulder External Rotation', 'ダンベル Upright Shoulder External Rotationは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Upright Shoulder External Rotation is an effective exercise targeting the rotator cuff using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0864-x306lCW.jpg', 'videos/0864-x306lCW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('5201', 'dumbbell-waiter-biceps-curl', 'ダンベル Waiter バイセップス カール', 'Dumbbell Waiter Biceps Curl', 'ダンベル Waiter バイセップス カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Waiter Biceps Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/5201-KOpzGBL.jpg', 'videos/5201-KOpzGBL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0438', 'dumbbell-w-press', 'ダンベル W-プレス', 'Dumbbell W-press', 'ダンベル W-プレスは、ダンベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Dumbbell W-press is an effective exercise targeting the triceps using dumbbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0438-vmwLyCg.jpg', 'videos/0438-vmwLyCg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0439', 'dumbbell-zottman-curl', 'ダンベル Zottman カール', 'Dumbbell Zottman Curl', 'ダンベル Zottman カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Zottman Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."]', 'images/0439-kXaIn5A.jpg', 'videos/0439-kXaIn5A.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2294', 'dumbbell-zottman-preacher-curl', 'ダンベル Zottman Preacher カール', 'Dumbbell Zottman Preacher Curl', 'ダンベル Zottman Preacher カールは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbell Zottman Preacher Curl is an effective exercise targeting the forearms using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]', 'images/2294-y5U5B9Y.jpg', 'videos/2294-y5U5B9Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2189', 'dumbbells-seated-triceps-extension', 'Dumbbells シーテッド トライセップス エクステンション', 'Dumbbells Seated Triceps Extension', 'Dumbbells シーテッド トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Dumbbells Seated Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2189-FQXdXzY.jpg', 'videos/2189-FQXdXzY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1167', 'dynamic-chest-stretch-male', 'Dynamic チェスト ストレッチ (male)', 'Dynamic Chest Stretch (male)', 'Dynamic チェスト ストレッチ (male)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Dynamic Chest Stretch (male) is an effective exercise targeting the shoulders using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."]', 'images/1167-3uj0Ozg.jpg', 'videos/1167-3uj0Ozg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3287', 'elbow-dips', 'Elbow ディップス', 'Elbow Dips', 'Elbow ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Elbow Dips is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3287-LkoAWAE.jpg', 'videos/3287-LkoAWAE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1772', 'elbow-lift-reverse-push-up', 'Elbow Lift - Reverse プッシュアップ', 'Elbow Lift - Reverse Push-up', 'Elbow Lift - Reverse プッシュアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Elbow Lift - Reverse Push-up is an effective exercise targeting the triceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1772-wbUYILZ.jpg', 'videos/1772-wbUYILZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0443', 'elbow-to-knee', 'Elbow-to-knee', 'Elbow-to-knee', 'Elbow-to-kneeは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Elbow-to-knee is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]', 'images/0443-jvp6DiD.jpg', 'videos/0443-jvp6DiD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3292', 'elevator', 'Elevator', 'Elevator', 'Elevatorは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Elevator is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3292-zYmNaoY.jpg', 'videos/3292-zYmNaoY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1332', 'exercise-ball-alternating-arm-ups', 'Exercise Ball Alternating Arm Ups', 'Exercise Ball Alternating Arm Ups', 'Exercise Ball Alternating Arm Upsは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Alternating Arm Ups is an effective exercise targeting the shoulders using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/1332-EyLrNC2.jpg', 'videos/1332-EyLrNC2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1333', 'exercise-ball-back-extension-with-arms-extended', 'Exercise Ball バック エクステンション With Arms Extended', 'Exercise Ball Back Extension With Arms Extended', 'Exercise Ball バック エクステンション With Arms Extendedは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Back Extension With Arms Extended is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1333-PERjVm8.jpg', 'videos/1333-PERjVm8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1334', 'exercise-ball-back-extension-with-hands-behind-head', 'Exercise Ball バック エクステンション With Hands Behind Head', 'Exercise Ball Back Extension With Hands Behind Head', 'Exercise Ball バック エクステンション With Hands Behind Headは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Back Extension With Hands Behind Head is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1334-o1HGDSq.jpg', 'videos/1334-o1HGDSq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1335', 'exercise-ball-back-extension-with-knees-off-ground', 'Exercise Ball バック エクステンション With Knees Off Ground', 'Exercise Ball Back Extension With Knees Off Ground', 'Exercise Ball バック エクステンション With Knees Off Groundは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Back Extension With Knees Off Ground is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1335-WME869U.jpg', 'videos/1335-WME869U.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1336', 'exercise-ball-back-extension-with-rotation', 'Exercise Ball バック エクステンション With Rotation', 'Exercise Ball Back Extension With Rotation', 'Exercise Ball バック エクステンション With Rotationは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Back Extension With Rotation is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]', 'images/1336-WVD66ff.jpg', 'videos/1336-WVD66ff.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1744', 'exercise-ball-dip', 'Exercise Ball ディップス', 'Exercise Ball Dip', 'Exercise Ball ディップスは、スタビリティボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Dip is an effective exercise targeting the chest using stability ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."]', 'images/1744-kprile3.jpg', 'videos/1744-kprile3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1559', 'exercise-ball-hip-flexor-stretch', 'Exercise Ball ヒップ Flexor ストレッチ', 'Exercise Ball Hip Flexor Stretch', 'Exercise Ball ヒップ Flexor ストレッチは、スタビリティボールを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Hip Flexor Stretch is an effective exercise targeting the quadriceps using stability ball.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', 'images/1559-2LQkNPW.jpg', 'videos/1559-2LQkNPW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1338', 'exercise-ball-hug', 'Exercise Ball Hug', 'Exercise Ball Hug', 'Exercise Ball Hugは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Hug is an effective exercise targeting the shoulders using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1338-d7z1Y7V.jpg', 'videos/1338-d7z1Y7V.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1339', 'exercise-ball-lat-stretch', 'Exercise Ball Lat ストレッチ', 'Exercise Ball Lat Stretch', 'Exercise Ball Lat ストレッチは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Lat Stretch is an effective exercise targeting the shoulders using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]', 'images/1339-sM84pE4.jpg', 'videos/1339-sM84pE4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1341', 'exercise-ball-lower-back-stretch-pyramid', 'Exercise Ball Lower バック ストレッチ (pyramid)', 'Exercise Ball Lower Back Stretch (pyramid)', 'Exercise Ball Lower バック ストレッチ (pyramid)は、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Lower Back Stretch (pyramid) is an effective exercise targeting the glutes using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1341-yU7w7CA.jpg', 'videos/1341-yU7w7CA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1342', 'exercise-ball-lying-side-lat-stretch', 'Exercise Ball ライイング Side Lat ストレッチ', 'Exercise Ball Lying Side Lat Stretch', 'Exercise Ball ライイング Side Lat ストレッチは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Lying Side Lat Stretch is an effective exercise targeting the shoulders using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', 'images/1342-rTbyBYV.jpg', 'videos/1342-rTbyBYV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1382', 'exercise-ball-on-the-wall-calf-raise', 'Exercise Ball On The Wall カーフ レイズ', 'Exercise Ball On The Wall Calf Raise', 'Exercise Ball On The Wall カーフ レイズは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball On The Wall Calf Raise is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1382-xo6sENf.jpg', 'videos/1382-xo6sENf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3241', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-ankles', 'Exercise Ball On The Wall カーフ レイズ (tennis Ball Between Ankles)', 'Exercise Ball On The Wall Calf Raise (tennis Ball Between Ankles)', 'Exercise Ball On The Wall カーフ レイズ (tennis Ball Between Ankles)は、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball On The Wall Calf Raise (tennis Ball Between Ankles) is an effective exercise targeting the hamstrings using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3241-FY3UdNT.jpg', 'videos/3241-FY3UdNT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3240', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-knees', 'Exercise Ball On The Wall カーフ レイズ (tennis Ball Between Knees)', 'Exercise Ball On The Wall Calf Raise (tennis Ball Between Knees)', 'Exercise Ball On The Wall カーフ レイズ (tennis Ball Between Knees)は、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball On The Wall Calf Raise (tennis Ball Between Knees) is an effective exercise targeting the quadriceps using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3240-j74M6Zn.jpg', 'videos/3240-j74M6Zn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1416', 'exercise-ball-one-leg-prone-lower-body-rotation', 'Exercise Ball One Leg プローン Lower Body Rotation', 'Exercise Ball One Leg Prone Lower Body Rotation', 'Exercise Ball One Leg プローン Lower Body Rotationは、スタビリティボールを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball One Leg Prone Lower Body Rotation is an effective exercise targeting the hamstrings using stability ball.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/1416-M72BExt.jpg', 'videos/1416-M72BExt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1417', 'exercise-ball-one-legged-diagonal-kick-hamstring-curl', 'Exercise Ball One Legged Diagonal Kick Hamstring カール', 'Exercise Ball One Legged Diagonal Kick Hamstring Curl', 'Exercise Ball One Legged Diagonal Kick Hamstring カールは、スタビリティボールを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball One Legged Diagonal Kick Hamstring Curl is an effective exercise targeting the hamstrings using stability ball.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]', 'images/1417-GOJKFfO.jpg', 'videos/1417-GOJKFfO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1296', 'exercise-ball-pike-push-up', 'Exercise Ball Pike Push Up', 'Exercise Ball Pike Push Up', 'Exercise Ball Pike Push Upは、スタビリティボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Pike Push Up is an effective exercise targeting the shoulders using stability ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1296-sVvXT5J.jpg', 'videos/1296-sVvXT5J.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1343', 'exercise-ball-prone-leg-raise', 'Exercise Ball プローン Leg レイズ', 'Exercise Ball Prone Leg Raise', 'Exercise Ball プローン Leg レイズは、スタビリティボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Prone Leg Raise is an effective exercise targeting the abdominals using stability ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1343-lCKm4Rs.jpg', 'videos/1343-lCKm4Rs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1560', 'exercise-ball-seated-hamstring-stretch', 'Exercise Ball シーテッド Hamstring ストレッチ', 'Exercise Ball Seated Hamstring Stretch', 'Exercise Ball シーテッド Hamstring ストレッチは、スタビリティボールを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Seated Hamstring Stretch is an effective exercise targeting the glutes using stability ball.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."]', 'images/1560-yRYyfdA.jpg', 'videos/1560-yRYyfdA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1745', 'exercise-ball-seated-triceps-stretch', 'Exercise Ball シーテッド トライセップス ストレッチ', 'Exercise Ball Seated Triceps Stretch', 'Exercise Ball シーテッド トライセップス ストレッチは、スタビリティボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Seated Triceps Stretch is an effective exercise targeting the shoulders using stability ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."]', 'images/1745-7ePTw4B.jpg', 'videos/1745-7ePTw4B.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1746', 'exercise-ball-supine-triceps-extension', 'Exercise Ball Supine トライセップス エクステンション', 'Exercise Ball Supine Triceps Extension', 'Exercise Ball Supine トライセップス エクステンションは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Exercise Ball Supine Triceps Extension is an effective exercise targeting the shoulders using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1746-Gm2Uv1z.jpg', 'videos/1746-Gm2Uv1z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1747', 'ez-bar-french-press-on-exercise-ball', 'Ez Bar French プレス On Exercise Ball', 'Ez Bar French Press On Exercise Ball', 'Ez Bar French プレス On Exercise Ballは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Bar French Press On Exercise Ball is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1747-CFN9P8G.jpg', 'videos/1747-CFN9P8G.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3010', 'ez-bar-lying-bent-arms-pullover', 'Ez Bar ライイング Bent Arms プルオーバー', 'Ez Bar Lying Bent Arms Pullover', 'Ez Bar ライイング Bent Arms プルオーバーは、ez barbellを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Ez Bar Lying Bent Arms Pullover is an effective exercise targeting the triceps using ez barbell.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."]', 'images/3010-nDK1HJ0.jpg', 'videos/3010-nDK1HJ0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1748', 'ez-bar-lying-close-grip-triceps-extension-behind-head', 'Ez Bar ライイング Close Grip トライセップス エクステンション Behind Head', 'Ez Bar Lying Close Grip Triceps Extension Behind Head', 'Ez Bar ライイング Close Grip トライセップス エクステンション Behind Headは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Bar Lying Close Grip Triceps Extension Behind Head is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1748-6CKUx7o.jpg', 'videos/1748-6CKUx7o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1344', 'ez-bar-reverse-grip-bent-over-row', 'Ez Bar Reverse Grip Bent Over ロー', 'Ez Bar Reverse Grip Bent Over Row', 'Ez Bar Reverse Grip Bent Over ローは、ez barbellを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Ez Bar Reverse Grip Bent Over Row is an effective exercise targeting the biceps using ez barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1344-G8dXpNG.jpg', 'videos/1344-G8dXpNG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1682', 'ez-bar-seated-close-grip-concentration-curl', 'Ez Bar シーテッド Close Grip Concentration カール', 'Ez Bar Seated Close Grip Concentration Curl', 'Ez Bar シーテッド Close Grip Concentration カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Bar Seated Close Grip Concentration Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1682-Dsfz0Id.jpg', 'videos/1682-Dsfz0Id.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1749', 'ez-bar-standing-french-press', 'Ez Bar スタンディング French プレス', 'Ez Bar Standing French Press', 'Ez Bar スタンディング French プレスは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Bar Standing French Press is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1749-1cTf2Ux.jpg', 'videos/1749-1cTf2Ux.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0445', 'ez-barbell-anti-gravity-press', 'Ez バーベル Anti Gravity プレス', 'Ez Barbell Anti Gravity Press', 'Ez バーベル Anti Gravity プレスは、ez barbellを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Anti Gravity Press is an effective exercise targeting the triceps using ez barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', 'images/0445-fprd84i.jpg', 'videos/0445-fprd84i.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1627', 'ez-barbell-close-grip-preacher-curl', 'Ez バーベル Close Grip Preacher カール', 'Ez Barbell Close Grip Preacher Curl', 'Ez バーベル Close Grip Preacher カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Close Grip Preacher Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1627-hacCyUv.jpg', 'videos/1627-hacCyUv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0446', 'ez-barbell-close-grip-curl', 'Ez バーベル ナローグリップ カール', 'Ez Barbell Close-grip Curl', 'Ez バーベル ナローグリップ カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Close-grip Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0446-V4ryaZa.jpg', 'videos/0446-V4ryaZa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0447', 'ez-barbell-curl', 'Ez バーベル カール', 'Ez Barbell Curl', 'Ez バーベル カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0447-6TG6x2w.jpg', 'videos/0447-6TG6x2w.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0448', 'ez-barbell-decline-close-grip-face-press', 'Ez バーベル デクライン Close Grip Face プレス', 'Ez Barbell Decline Close Grip Face Press', 'Ez バーベル デクライン Close Grip Face プレスは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Decline Close Grip Face Press is an effective exercise targeting the chest using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0448-DgZQ11d.jpg', 'videos/0448-DgZQ11d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2186', 'ez-barbell-decline-triceps-extension', 'Ez バーベル デクライン トライセップス エクステンション', 'Ez Barbell Decline Triceps Extension', 'Ez バーベル デクライン トライセップス エクステンションは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Decline Triceps Extension is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2186-CQHoDm0.jpg', 'videos/2186-CQHoDm0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0449', 'ez-barbell-incline-triceps-extension', 'Ez バーベル インクライン トライセップス エクステンション', 'Ez Barbell Incline Triceps Extension', 'Ez バーベル インクライン トライセップス エクステンションは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Incline Triceps Extension is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0449-KyLtiLT.jpg', 'videos/0449-KyLtiLT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0450', 'ez-barbell-jm-bench-press', 'Ez バーベル Jm ベンチプレス', 'Ez Barbell Jm Bench Press', 'Ez バーベル Jm ベンチプレスは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Jm Bench Press is an effective exercise targeting the chest using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0450-hnOYgH3.jpg', 'videos/0450-hnOYgH3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0451', 'ez-barbell-reverse-grip-curl', 'Ez バーベル Reverse Grip カール', 'Ez Barbell Reverse Grip Curl', 'Ez バーベル Reverse Grip カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Reverse Grip Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."]', 'images/0451-Y5X65IB.jpg', 'videos/0451-Y5X65IB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0452', 'ez-barbell-reverse-grip-preacher-curl', 'Ez バーベル Reverse Grip Preacher カール', 'Ez Barbell Reverse Grip Preacher Curl', 'Ez バーベル Reverse Grip Preacher カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Reverse Grip Preacher Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0452-vBNyir7.jpg', 'videos/0452-vBNyir7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1458', 'ez-barbell-seated-curls', 'Ez バーベル シーテッド Curls', 'Ez Barbell Seated Curls', 'Ez バーベル シーテッド Curlsは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Seated Curls is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1458-jtFKbt5.jpg', 'videos/1458-jtFKbt5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0453', 'ez-barbell-seated-triceps-extension', 'Ez バーベル シーテッド トライセップス エクステンション', 'Ez Barbell Seated Triceps Extension', 'Ez バーベル シーテッド トライセップス エクステンションは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Seated Triceps Extension is an effective exercise targeting the shoulders using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0453-iaapw0g.jpg', 'videos/0453-iaapw0g.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0454', 'ez-barbell-spider-curl', 'Ez バーベル Spider カール', 'Ez Barbell Spider Curl', 'Ez バーベル Spider カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Spider Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0454-Ye5Qxb0.jpg', 'videos/0454-Ye5Qxb0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1628', 'ez-barbell-spider-curl-1628', 'Ez バーベル Spider カール', 'Ez Barbell Spider Curl', 'Ez バーベル Spider カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez Barbell Spider Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1628-2kattbR.jpg', 'videos/1628-2kattbR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2404', 'ez-bar-biceps-curl-with-arm-blaster', 'Ez-bar バイセップス カール (with Arm Blaster)', 'Ez-bar Biceps Curl (with Arm Blaster)', 'Ez-bar バイセップス カール (with Arm Blaster)は、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez-bar Biceps Curl (with Arm Blaster) is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/2404-tJ5nYqo.jpg', 'videos/2404-tJ5nYqo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2432', 'ez-bar-close-grip-bench-press', 'Ez-bar ナローグリップ ベンチプレス', 'Ez-bar Close-grip Bench Press', 'Ez-bar ナローグリップ ベンチプレスは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez-bar Close-grip Bench Press is an effective exercise targeting the chest using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/2432-da4cXST.jpg', 'videos/2432-da4cXST.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2741', 'ez-barbell-standing-wide-grip-biceps-curl', 'Ez-バーベル スタンディング Wide Grip バイセップス カール', 'Ez-barbell Standing Wide Grip Biceps Curl', 'Ez-バーベル スタンディング Wide Grip バイセップス カールは、ez barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ez-barbell Standing Wide Grip Biceps Curl is an effective exercise targeting the forearms using ez barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2741-OVTZ65k.jpg', 'videos/2741-OVTZ65k.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2133', 'farmers-walk', 'Farmers Walk', 'Farmers Walk', 'Farmers Walkは、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Farmers Walk is an effective exercise targeting the calves using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."]', 'images/2133-qPEzJjA.jpg', 'videos/2133-qPEzJjA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0455', 'finger-curls', 'Finger Curls', 'Finger Curls', 'Finger Curlsは、バーベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Finger Curls is an effective exercise targeting the wrist flexors using barbell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0455-awG04cF.jpg', 'videos/0455-awG04cF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3303', 'flag', 'Flag', 'Flag', 'Flagは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Flag is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3303-pQ0Mx1Z.jpg', 'videos/3303-pQ0Mx1Z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0456', 'flexion-leg-sit-up-bent-knee', 'Flexion Leg Sit Up (bent Knee)', 'Flexion Leg Sit Up (bent Knee)', 'Flexion Leg Sit Up (bent Knee)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Flexion Leg Sit Up (bent Knee) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0456-AR0ig3o.jpg', 'videos/0456-AR0ig3o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0457', 'flexion-leg-sit-up-straight-arm', 'Flexion Leg Sit Up (straight Arm)', 'Flexion Leg Sit Up (straight Arm)', 'Flexion Leg Sit Up (straight Arm)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Flexion Leg Sit Up (straight Arm) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0457-KZn52RC.jpg', 'videos/0457-KZn52RC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0458', 'floor-fly-with-barbell', 'Floor フライ (with バーベル)', 'Floor Fly (with Barbell)', 'Floor フライ (with バーベル)は、バーベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Floor Fly (with Barbell) is an effective exercise targeting the deltoids using barbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0458-neonEDL.jpg', 'videos/0458-neonEDL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0459', 'flutter-kicks', 'Flutter Kicks', 'Flutter Kicks', 'Flutter Kicksは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Flutter Kicks is an effective exercise targeting the hip flexors using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."]', 'images/0459-UVo2Qs2.jpg', 'videos/0459-UVo2Qs2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1472', 'forward-jump', 'Forward Jump', 'Forward Jump', 'Forward Jumpは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Forward Jump is an effective exercise targeting the calves using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."]', 'images/1472-uZKq7lo.jpg', 'videos/1472-uZKq7lo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3470', 'forward-lunge-male', 'Forward ランジ (male)', 'Forward Lunge (male)', 'Forward ランジ (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Forward Lunge (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."]', 'images/3470-kMzUs9Y.jpg', 'videos/3470-kMzUs9Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3194', 'frankenstein-squat', 'Frankenstein スクワット', 'Frankenstein Squat', 'Frankenstein スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Frankenstein Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3194-bdWcbaU.jpg', 'videos/3194-bdWcbaU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2429', 'frog-crunch', 'Frog クランチ', 'Frog Crunch', 'Frog クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Frog Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2429-FFRP97T.jpg', 'videos/2429-FFRP97T.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3301', 'frog-planche', 'Frog Planche', 'Frog Planche', 'Frog Plancheは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Frog Planche is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3301-rQhGcin.jpg', 'videos/3301-rQhGcin.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3296', 'front-lever', 'フロント Lever', 'Front Lever', 'フロント Leverは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Front Lever is an effective exercise targeting the lats using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3296-PkCN2lv.jpg', 'videos/3296-PkCN2lv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3295', 'front-lever-reps', 'フロント Lever Reps', 'Front Lever Reps', 'フロント Lever Repsは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Front Lever Reps is an effective exercise targeting the core using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3295-hbY9wqG.jpg', 'videos/3295-hbY9wqG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0464', 'front-plank-with-twist', 'フロント プランク With ツイスト', 'Front Plank With Twist', 'フロント プランク With ツイストは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Front Plank With Twist is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."]', 'images/0464-CosupLu.jpg', 'videos/0464-CosupLu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3315', 'full-maltese', 'Full Maltese', 'Full Maltese', 'Full Malteseは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Full Maltese is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."]', 'images/3315-YRaCa5Y.jpg', 'videos/3315-YRaCa5Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3299', 'full-planche', 'Full Planche', 'Full Planche', 'Full Plancheは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Full Planche is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3299-YZ4961r.jpg', 'videos/3299-YZ4961r.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3327', 'full-planche-push-up', 'Full Planche プッシュアップ', 'Full Planche Push-up', 'Full Planche プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Full Planche Push-up is an effective exercise targeting the shoulders using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."]', 'images/3327-gw9PqGk.jpg', 'videos/3327-gw9PqGk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0466', 'gironda-sternum-chin', 'Gironda Sternum チンアップ', 'Gironda Sternum Chin', 'Gironda Sternum チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Gironda Sternum Chin is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0466-IL0JUxR.jpg', 'videos/0466-IL0JUxR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3561', 'glute-bridge-march', 'グルート Bridge March', 'Glute Bridge March', 'グルート Bridge Marchは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Glute Bridge March is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."]', 'images/3561-GibBPPg.jpg', 'videos/3561-GibBPPg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3523', 'glute-bridge-two-legs-on-bench-male', 'グルート Bridge Two Legs On ベンチ (male)', 'Glute Bridge Two Legs On Bench (male)', 'グルート Bridge Two Legs On ベンチ (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Glute Bridge Two Legs On Bench (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3523-aWedzZX.jpg', 'videos/3523-aWedzZX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3193', 'glute-ham-raise', 'グルート-ham レイズ', 'Glute-ham Raise', 'グルート-ham レイズは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Glute-ham Raise is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3193-Vvwjz6N.jpg', 'videos/3193-Vvwjz6N.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0467', 'gorilla-chin', 'Gorilla チンアップ', 'Gorilla Chin', 'Gorilla チンアップは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Gorilla Chin is an effective exercise targeting the forearms using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0467-bmwlYvD.jpg', 'videos/0467-bmwlYvD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0469', 'groin-crunch', 'Groin クランチ', 'Groin Crunch', 'Groin クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Groin Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0469-mWppALS.jpg', 'videos/0469-mWppALS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1383', 'hack-calf-raise', 'ハック カーフ レイズ', 'Hack Calf Raise', 'ハック カーフ レイズは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Hack Calf Raise is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1383-2ORFMoR.jpg', 'videos/1383-2ORFMoR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1384', 'hack-one-leg-calf-raise', 'ハック One Leg カーフ レイズ', 'Hack One Leg Calf Raise', 'ハック One Leg カーフ レイズは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Hack One Leg Calf Raise is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."]', 'images/1384-AxFoqAD.jpg', 'videos/1384-AxFoqAD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3221', 'half-knee-bends-male', 'Half Knee Bends (male)', 'Half Knee Bends (male)', 'Half Knee Bends (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Half Knee Bends (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3221-ia6kIIl.jpg', 'videos/3221-ia6kIIl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3202', 'half-sit-up-male', 'Half Sit-up (male)', 'Half Sit-up (male)', 'Half Sit-up (male)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Half Sit-up (male) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3202-iQ241UP.jpg', 'videos/3202-iQ241UP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1511', 'hamstring-stretch', 'Hamstring ストレッチ', 'Hamstring Stretch', 'Hamstring ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Hamstring Stretch is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]', 'images/1511-99rWm7w.jpg', 'videos/1511-99rWm7w.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2139', 'hands-bike', 'Hands Bike', 'Hands Bike', 'Hands Bikeは、upper body ergometerを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Hands Bike is an effective exercise targeting the triceps using upper body ergometer.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."]', 'images/2139-pAIWRGu.jpg', 'videos/2139-pAIWRGu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3218', 'hands-clasped-circular-toe-touch-male', 'Hands Clasped Circular Toe Touch (male)', 'Hands Clasped Circular Toe Touch (male)', 'Hands Clasped Circular Toe Touch (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Hands Clasped Circular Toe Touch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3218-B5xca8s.jpg', 'videos/3218-B5xca8s.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3215', 'hands-reversed-clasped-circular-toe-touch-male', 'Hands Reversed Clasped Circular Toe Touch (male)', 'Hands Reversed Clasped Circular Toe Touch (male)', 'Hands Reversed Clasped Circular Toe Touch (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Hands Reversed Clasped Circular Toe Touch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3215-yq3GAJX.jpg', 'videos/3215-yq3GAJX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3302', 'handstand', 'Handstand', 'Handstand', 'Handstandは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Handstand is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."]', 'images/3302-XooAdhl.jpg', 'videos/3302-XooAdhl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0471', 'handstand-push-up', 'Handstand プッシュアップ', 'Handstand Push-up', 'Handstand プッシュアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Handstand Push-up is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0471-rQxwMxO.jpg', 'videos/0471-rQxwMxO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1764', 'hanging-leg-hip-raise', 'Hanging Leg ヒップ レイズ', 'Hanging Leg Hip Raise', 'Hanging Leg ヒップ レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Leg Hip Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1764-VEcJRo2.jpg', 'videos/1764-VEcJRo2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0472', 'hanging-leg-raise', 'Hanging Leg レイズ', 'Hanging Leg Raise', 'Hanging Leg レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Leg Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0472-I3tsCnC.jpg', 'videos/0472-I3tsCnC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1761', 'hanging-oblique-knee-raise', 'Hanging オブリーク Knee レイズ', 'Hanging Oblique Knee Raise', 'Hanging オブリーク Knee レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Oblique Knee Raise is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."]', 'images/1761-BaE7O6U.jpg', 'videos/1761-BaE7O6U.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0473', 'hanging-pike', 'Hanging Pike', 'Hanging Pike', 'Hanging Pikeは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Pike is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0473-nuBF9MO.jpg', 'videos/0473-nuBF9MO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0474', 'hanging-straight-leg-hip-raise', 'Hanging Straight Leg ヒップ レイズ', 'Hanging Straight Leg Hip Raise', 'Hanging Straight Leg ヒップ レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Straight Leg Hip Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0474-pj0X0tF.jpg', 'videos/0474-pj0X0tF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0475', 'hanging-straight-leg-raise', 'Hanging Straight Leg レイズ', 'Hanging Straight Leg Raise', 'Hanging Straight Leg レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Straight Leg Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0475-4Ml7QFO.jpg', 'videos/0475-4Ml7QFO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0476', 'hanging-straight-twisting-leg-hip-raise', 'Hanging Straight Twisting Leg ヒップ レイズ', 'Hanging Straight Twisting Leg Hip Raise', 'Hanging Straight Twisting Leg ヒップ レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hanging Straight Twisting Leg Hip Raise is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0476-Q6bvyen.jpg', 'videos/0476-Q6bvyen.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3636', 'high-knee-against-wall', 'High Knee Against Wall', 'High Knee Against Wall', 'High Knee Against Wallは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'High Knee Against Wall is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."]', 'images/3636-ealLwvX.jpg', 'videos/3636-ealLwvX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0484', 'hip-raise-bent-knee', 'ヒップ レイズ (bent Knee)', 'Hip Raise (bent Knee)', 'ヒップ レイズ (bent Knee)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Hip Raise (bent Knee) is an effective exercise targeting the glutes using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0484-196HJGw.jpg', 'videos/0484-196HJGw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1418', 'hug-keens-to-chest', 'Hug Keens To チェスト', 'Hug Keens To Chest', 'Hug Keens To チェストは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Hug Keens To Chest is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1418-znP9SIh.jpg', 'videos/1418-znP9SIh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3234', 'hyght-dumbbell-fly', 'Hyght ダンベル フライ', 'Hyght Dumbbell Fly', 'Hyght ダンベル フライは、ダンベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Hyght Dumbbell Fly is an effective exercise targeting the shoulders using dumbbell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3234-P9ZRyLT.jpg', 'videos/3234-P9ZRyLT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0489', 'hyperextension', 'Hyperextension', 'Hyperextension', 'Hyperextensionは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Hyperextension is an effective exercise targeting the glutes using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]', 'images/0489-zhMwOwE.jpg', 'videos/0489-zhMwOwE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0488', 'hyperextension-on-bench', 'Hyperextension (on ベンチ)', 'Hyperextension (on Bench)', 'Hyperextension (on ベンチ)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Hyperextension (on Bench) is an effective exercise targeting the glutes using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]', 'images/0488-zkgRrbK.jpg', 'videos/0488-zkgRrbK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3289', 'impossible-dips', 'Impossible ディップス', 'Impossible Dips', 'Impossible ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Impossible Dips is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/3289-05Cf2v8.jpg', 'videos/3289-05Cf2v8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1471', 'inchworm', 'Inchworm', 'Inchworm', 'Inchwormは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Inchworm is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1471-ZgsNQ6d.jpg', 'videos/1471-ZgsNQ6d.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3698', 'inchworm-v-2', 'Inchworm V. 2', 'Inchworm V. 2', 'Inchworm V. 2は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Inchworm V. 2 is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."]', 'images/3698-TV87DNB.jpg', 'videos/3698-TV87DNB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0490', 'incline-close-grip-push-up', 'インクライン ナローグリップ プッシュアップ', 'Incline Close-grip Push-up', 'インクライン ナローグリップ プッシュアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Incline Close-grip Push-up is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0490-1YB40kg.jpg', 'videos/0490-1YB40kg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0491', 'incline-leg-hip-raise-leg-straight', 'インクライン Leg ヒップ レイズ (leg Straight)', 'Incline Leg Hip Raise (leg Straight)', 'インクライン Leg ヒップ レイズ (leg Straight)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Incline Leg Hip Raise (leg Straight) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0491-eVxAzgz.jpg', 'videos/0491-eVxAzgz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0492', 'incline-push-up-depth-jump', 'インクライン Push Up Depth Jump', 'Incline Push Up Depth Jump', 'インクライン Push Up Depth Jumpは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Incline Push Up Depth Jump is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."]', 'images/0492-CB8WET1.jpg', 'videos/0492-CB8WET1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0493', 'incline-push-up', 'インクライン プッシュアップ', 'Incline Push-up', 'インクライン プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Incline Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0493-B1EVP9F.jpg', 'videos/0493-B1EVP9F.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3785', 'incline-push-up-on-box', 'インクライン プッシュアップ (on Box)', 'Incline Push-up (on Box)', 'インクライン プッシュアップ (on Box)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Incline Push-up (on Box) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/3785-F7vjXqT.jpg', 'videos/3785-F7vjXqT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0494', 'incline-reverse-grip-push-up', 'インクライン Reverse Grip プッシュアップ', 'Incline Reverse Grip Push-up', 'インクライン Reverse Grip プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Incline Reverse Grip Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0494-XaaRnRn.jpg', 'videos/0494-XaaRnRn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3011', 'incline-scapula-push-up', 'インクライン Scapula Push Up', 'Incline Scapula Push Up', 'インクライン Scapula Push Upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Incline Scapula Push Up is an effective exercise targeting the triceps using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3011-GdMa1ET.jpg', 'videos/3011-GdMa1ET.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0495', 'incline-twisting-sit-up', 'インクライン Twisting Sit-up', 'Incline Twisting Sit-up', 'インクライン Twisting Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Incline Twisting Sit-up is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0495-9ZGZuOD.jpg', 'videos/0495-9ZGZuOD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1564', 'intermediate-hip-flexor-and-quad-stretch', 'Intermediate ヒップ Flexor And クアッド ストレッチ', 'Intermediate Hip Flexor And Quad Stretch', 'Intermediate ヒップ Flexor And クアッド ストレッチは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Intermediate Hip Flexor And Quad Stretch is an effective exercise targeting the hamstrings using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."]', 'images/1564-tFGKm99.jpg', 'videos/1564-tFGKm99.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0496', 'inverse-leg-curl-bench-support', 'Inverse Leg カール (ベンチ Support)', 'Inverse Leg Curl (bench Support)', 'Inverse Leg カール (ベンチ Support)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Inverse Leg Curl (bench Support) is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0496-ms7tjSG.jpg', 'videos/0496-ms7tjSG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2400', 'inverse-leg-curl-on-pull-up-cable-machine', 'Inverse Leg カール (on プルアップ ケーブル マシン)', 'Inverse Leg Curl (on Pull-up Cable Machine)', 'Inverse Leg カール (on プルアップ ケーブル マシン)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Inverse Leg Curl (on Pull-up Cable Machine) is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'pull', 'lower', '["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2400-0rHfvy9.jpg', 'videos/2400-0rHfvy9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0499', 'inverted-row', 'Inverted ロー', 'Inverted Row', 'Inverted ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Inverted Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0499-bZGHsAZ.jpg', 'videos/0499-bZGHsAZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2300', 'inverted-row-bent-knees', 'Inverted ロー Bent Knees', 'Inverted Row Bent Knees', 'Inverted ロー Bent Kneesは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Inverted Row Bent Knees is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2300-VPPtusI.jpg', 'videos/2300-VPPtusI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2298', 'inverted-row-on-bench', 'Inverted ロー On ベンチ', 'Inverted Row On Bench', 'Inverted ロー On ベンチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Inverted Row On Bench is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2298-Mxa7Cr8.jpg', 'videos/2298-Mxa7Cr8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0497', 'inverted-row-v-2', 'Inverted ロー V. 2', 'Inverted Row V. 2', 'Inverted ロー V. 2は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Inverted Row V. 2 is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0497-uX3sUBz.jpg', 'videos/0497-uX3sUBz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0498', 'inverted-row-with-straps', 'Inverted ロー With Straps', 'Inverted Row With Straps', 'Inverted ロー With Strapsは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Inverted Row With Straps is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0498-jdiExfW.jpg', 'videos/0498-jdiExfW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1419', 'iron-cross-stretch', 'Iron Cross ストレッチ', 'Iron Cross Stretch', 'Iron Cross ストレッチは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Iron Cross Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1419-pZwUsKB.jpg', 'videos/1419-pZwUsKB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1297', 'isometric-chest-squeeze', 'Isometric チェスト Squeeze', 'Isometric Chest Squeeze', 'Isometric チェスト Squeezeは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Isometric Chest Squeeze is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."]', 'images/1297-HbSG1Pw.jpg', 'videos/1297-HbSG1Pw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0500', 'isometric-wipers', 'Isometric Wipers', 'Isometric Wipers', 'Isometric Wipersは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Isometric Wipers is an effective exercise targeting the shoulders using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0500-11wrviz.jpg', 'videos/0500-11wrviz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0501', 'jack-burpee', 'Jack Burpee', 'Jack Burpee', 'Jack Burpeeは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Jack Burpee is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."]', 'images/0501-mr7pkqP.jpg', 'videos/0501-mr7pkqP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3224', 'jack-jump-male', 'Jack Jump (male)', 'Jack Jump (male)', 'Jack Jump (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Jack Jump (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3224-1g5bPpA.jpg', 'videos/3224-1g5bPpA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0507', 'jackknife-sit-up', 'Jackknife Sit-up', 'Jackknife Sit-up', 'Jackknife Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Jackknife Sit-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0507-mbkgB44.jpg', 'videos/0507-mbkgB44.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0508', 'janda-sit-up', 'Janda Sit-up', 'Janda Sit-up', 'Janda Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Janda Sit-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0508-1GPHRyK.jpg', 'videos/0508-1GPHRyK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2612', 'jump-rope', 'Jump Rope', 'Jump Rope', 'Jump Ropeは、ロープを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Jump Rope is an effective exercise targeting the calves using rope.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."]', 'images/2612-e1e76I2.jpg', 'videos/2612-e1e76I2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0514', 'jump-squat', 'Jump スクワット', 'Jump Squat', 'Jump スクワットは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Jump Squat is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]', 'images/0514-LIlE5Tn.jpg', 'videos/0514-LIlE5Tn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0513', 'jump-squat-v-2', 'Jump スクワット V. 2', 'Jump Squat V. 2', 'Jump スクワット V. 2は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Jump Squat V. 2 is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."]', 'images/0513-TDYiji6.jpg', 'videos/0513-TDYiji6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0517', 'kettlebell-advanced-windmill', 'ケトルベル Advanced Windmill', 'Kettlebell Advanced Windmill', 'ケトルベル Advanced Windmillは、ケトルベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Advanced Windmill is an effective exercise targeting the obliques using kettlebell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0517-Kal9cQQ.jpg', 'videos/0517-Kal9cQQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0518', 'kettlebell-alternating-hang-clean', 'ケトルベル Alternating Hang Clean', 'Kettlebell Alternating Hang Clean', 'ケトルベル Alternating Hang Cleanは、ケトルベルを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Alternating Hang Clean is an effective exercise targeting the shoulders using kettlebell.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0518-I4tibZG.jpg', 'videos/0518-I4tibZG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0520', 'kettlebell-alternating-press', 'ケトルベル Alternating プレス', 'Kettlebell Alternating Press', 'ケトルベル Alternating プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Alternating Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0520-5KLbZWx.jpg', 'videos/0520-5KLbZWx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0519', 'kettlebell-alternating-press-on-floor', 'ケトルベル Alternating プレス On Floor', 'Kettlebell Alternating Press On Floor', 'ケトルベル Alternating プレス On Floorは、ケトルベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Alternating Press On Floor is an effective exercise targeting the shoulders using kettlebell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."]', 'images/0519-7w6i0vE.jpg', 'videos/0519-7w6i0vE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0521', 'kettlebell-alternating-renegade-row', 'ケトルベル Alternating Renegade ロー', 'Kettlebell Alternating Renegade Row', 'ケトルベル Alternating Renegade ローは、ケトルベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Alternating Renegade Row is an effective exercise targeting the core using kettlebell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0521-b9kqlBy.jpg', 'videos/0521-b9kqlBy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0522', 'kettlebell-alternating-row', 'ケトルベル Alternating ロー', 'Kettlebell Alternating Row', 'ケトルベル Alternating ローは、ケトルベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Alternating Row is an effective exercise targeting the biceps using kettlebell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', 'images/0522-Ca76jUE.jpg', 'videos/0522-Ca76jUE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0523', 'kettlebell-arnold-press', 'ケトルベル Arnold プレス', 'Kettlebell Arnold Press', 'ケトルベル Arnold プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Arnold Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0523-UM8mgyG.jpg', 'videos/0523-UM8mgyG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0524', 'kettlebell-bent-press', 'ケトルベル Bent プレス', 'Kettlebell Bent Press', 'ケトルベル Bent プレスは、ケトルベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Bent Press is an effective exercise targeting the shoulders using kettlebell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0524-kjE55n5.jpg', 'videos/0524-kjE55n5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0525', 'kettlebell-bottoms-up-clean-from-the-hang-position', 'ケトルベル Bottoms Up Clean From The Hang Position', 'Kettlebell Bottoms Up Clean From The Hang Position', 'ケトルベル Bottoms Up Clean From The Hang Positionは、ケトルベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Bottoms Up Clean From The Hang Position is an effective exercise targeting the forearms using kettlebell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0525-4KJEpzb.jpg', 'videos/0525-4KJEpzb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0526', 'kettlebell-double-alternating-hang-clean', 'ケトルベル Double Alternating Hang Clean', 'Kettlebell Double Alternating Hang Clean', 'ケトルベル Double Alternating Hang Cleanは、ケトルベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Double Alternating Hang Clean is an effective exercise targeting the forearms using kettlebell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', 'images/0526-a4F9Oyc.jpg', 'videos/0526-a4F9Oyc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0527', 'kettlebell-double-jerk', 'ケトルベル Double Jerk', 'Kettlebell Double Jerk', 'ケトルベル Double Jerkは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Double Jerk is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0527-tznL2Ad.jpg', 'videos/0527-tznL2Ad.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0528', 'kettlebell-double-push-press', 'ケトルベル Double Push プレス', 'Kettlebell Double Push Press', 'ケトルベル Double Push プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Double Push Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0528-I4KkPdl.jpg', 'videos/0528-I4KkPdl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0529', 'kettlebell-double-snatch', 'ケトルベル Double Snatch', 'Kettlebell Double Snatch', 'ケトルベル Double Snatchは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Double Snatch is an effective exercise targeting the trapezius using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', 'images/0529-M74kdvm.jpg', 'videos/0529-M74kdvm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0530', 'kettlebell-double-windmill', 'ケトルベル Double Windmill', 'Kettlebell Double Windmill', 'ケトルベル Double Windmillは、ケトルベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Double Windmill is an effective exercise targeting the shoulders using kettlebell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0530-OaE7CpD.jpg', 'videos/0530-OaE7CpD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0531', 'kettlebell-extended-range-one-arm-press-on-floor', 'ケトルベル Extended Range ワンハンド プレス On Floor', 'Kettlebell Extended Range One Arm Press On Floor', 'ケトルベル Extended Range ワンハンド プレス On Floorは、ケトルベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Extended Range One Arm Press On Floor is an effective exercise targeting the triceps using kettlebell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0531-rseLfH3.jpg', 'videos/0531-rseLfH3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0532', 'kettlebell-figure-8', 'ケトルベル Figure 8', 'Kettlebell Figure 8', 'ケトルベル Figure 8は、ケトルベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Figure 8 is an effective exercise targeting the shoulders using kettlebell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."]', 'images/0532-L4ay0PW.jpg', 'videos/0532-L4ay0PW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0533', 'kettlebell-front-squat', 'ケトルベル フロント スクワット', 'Kettlebell Front Squat', 'ケトルベル フロント スクワットは、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Front Squat is an effective exercise targeting the quadriceps using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', 'images/0533-DB0n8AG.jpg', 'videos/0533-DB0n8AG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0534', 'kettlebell-goblet-squat', 'ケトルベル Goblet スクワット', 'Kettlebell Goblet Squat', 'ケトルベル Goblet スクワットは、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Goblet Squat is an effective exercise targeting the quadriceps using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0534-ZA8b5hc.jpg', 'videos/0534-ZA8b5hc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0535', 'kettlebell-hang-clean', 'ケトルベル Hang Clean', 'Kettlebell Hang Clean', 'ケトルベル Hang Cleanは、ケトルベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Hang Clean is an effective exercise targeting the glutes using kettlebell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."]', 'images/0535-LHWF7us.jpg', 'videos/0535-LHWF7us.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0536', 'kettlebell-lunge-pass-through', 'ケトルベル ランジ Pass Through', 'Kettlebell Lunge Pass Through', 'ケトルベル ランジ Pass Throughは、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Lunge Pass Through is an effective exercise targeting the quadriceps using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]', 'images/0536-WKMQzCD.jpg', 'videos/0536-WKMQzCD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0537', 'kettlebell-one-arm-clean-and-jerk', 'ケトルベル ワンハンド Clean And Jerk', 'Kettlebell One Arm Clean And Jerk', 'ケトルベル ワンハンド Clean And Jerkは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Clean And Jerk is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0537-vzAxBtt.jpg', 'videos/0537-vzAxBtt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1298', 'kettlebell-one-arm-floor-press', 'ケトルベル ワンハンド Floor プレス', 'Kettlebell One Arm Floor Press', 'ケトルベル ワンハンド Floor プレスは、ケトルベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Floor Press is an effective exercise targeting the triceps using kettlebell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1298-rg59QCH.jpg', 'videos/1298-rg59QCH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0538', 'kettlebell-one-arm-jerk', 'ケトルベル ワンハンド Jerk', 'Kettlebell One Arm Jerk', 'ケトルベル ワンハンド Jerkは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Jerk is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]', 'images/0538-S37C94C.jpg', 'videos/0538-S37C94C.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0539', 'kettlebell-one-arm-military-press-to-the-side', 'ケトルベル ワンハンド Military プレス To The Side', 'Kettlebell One Arm Military Press To The Side', 'ケトルベル ワンハンド Military プレス To The Sideは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Military Press To The Side is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0539-yCvYdi7.jpg', 'videos/0539-yCvYdi7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0540', 'kettlebell-one-arm-push-press', 'ケトルベル ワンハンド Push プレス', 'Kettlebell One Arm Push Press', 'ケトルベル ワンハンド Push プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Push Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0540-osdXT3K.jpg', 'videos/0540-osdXT3K.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0541', 'kettlebell-one-arm-row', 'ケトルベル ワンハンド ロー', 'Kettlebell One Arm Row', 'ケトルベル ワンハンド ローは、ケトルベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Row is an effective exercise targeting the biceps using kettlebell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', 'images/0541-g9AsZ8P.jpg', 'videos/0541-g9AsZ8P.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0542', 'kettlebell-one-arm-snatch', 'ケトルベル ワンハンド Snatch', 'Kettlebell One Arm Snatch', 'ケトルベル ワンハンド Snatchは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell One Arm Snatch is an effective exercise targeting the trapezius using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]', 'images/0542-aXcUyKb.jpg', 'videos/0542-aXcUyKb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0543', 'kettlebell-pirate-supper-legs', 'ケトルベル Pirate Supper Legs', 'Kettlebell Pirate Supper Legs', 'ケトルベル Pirate Supper Legsは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Pirate Supper Legs is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0543-kuXhl0o.jpg', 'videos/0543-kuXhl0o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0544', 'kettlebell-pistol-squat', 'ケトルベル Pistol スクワット', 'Kettlebell Pistol Squat', 'ケトルベル Pistol スクワットは、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Pistol Squat is an effective exercise targeting the quadriceps using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0544-5bpPTHv.jpg', 'videos/0544-5bpPTHv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0545', 'kettlebell-plyo-push-up', 'ケトルベル Plyo プッシュアップ', 'Kettlebell Plyo Push-up', 'ケトルベル Plyo プッシュアップは、ケトルベルを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Plyo Push-up is an effective exercise targeting the triceps using kettlebell.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."]', 'images/0545-ktf3nvW.jpg', 'videos/0545-ktf3nvW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0546', 'kettlebell-seated-press', 'ケトルベル シーテッド プレス', 'Kettlebell Seated Press', 'ケトルベル シーテッド プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Seated Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."]', 'images/0546-BkxB8LW.jpg', 'videos/0546-BkxB8LW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1438', 'kettlebell-seated-two-arm-military-press', 'ケトルベル シーテッド Two Arm Military プレス', 'Kettlebell Seated Two Arm Military Press', 'ケトルベル シーテッド Two Arm Military プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Seated Two Arm Military Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."]', 'images/1438-ZEkjZDi.jpg', 'videos/1438-ZEkjZDi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0547', 'kettlebell-seesaw-press', 'ケトルベル Seesaw プレス', 'Kettlebell Seesaw Press', 'ケトルベル Seesaw プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Seesaw Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."]', 'images/0547-UDm6cGl.jpg', 'videos/0547-UDm6cGl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0548', 'kettlebell-sumo-high-pull', 'ケトルベル Sumo High Pull', 'Kettlebell Sumo High Pull', 'ケトルベル Sumo High Pullは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Sumo High Pull is an effective exercise targeting the shoulders using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'pull', 'upper', '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0548-8ARQ9Hw.jpg', 'videos/0548-8ARQ9Hw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0549', 'kettlebell-swing', 'ケトルベル Swing', 'Kettlebell Swing', 'ケトルベル Swingは、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Swing is an effective exercise targeting the hamstrings using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."]', 'images/0549-UHJlbu3.jpg', 'videos/0549-UHJlbu3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0550', 'kettlebell-thruster', 'ケトルベル Thruster', 'Kettlebell Thruster', 'ケトルベル Thrusterは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Thruster is an effective exercise targeting the quadriceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."]', 'images/0550-yWxMvB5.jpg', 'videos/0550-yWxMvB5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0551', 'kettlebell-turkish-get-up-squat-style', 'ケトルベル Turkish Get Up (スクワット Style)', 'Kettlebell Turkish Get Up (squat Style)', 'ケトルベル Turkish Get Up (スクワット Style)は、ケトルベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Turkish Get Up (squat Style) is an effective exercise targeting the quadriceps using kettlebell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."]', 'images/0551-Ha7SZ3y.jpg', 'videos/0551-Ha7SZ3y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0552', 'kettlebell-two-arm-clean', 'ケトルベル Two Arm Clean', 'Kettlebell Two Arm Clean', 'ケトルベル Two Arm Cleanは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Two Arm Clean is an effective exercise targeting the traps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', 'images/0552-7Ba7bQ2.jpg', 'videos/0552-7Ba7bQ2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0553', 'kettlebell-two-arm-military-press', 'ケトルベル Two Arm Military プレス', 'Kettlebell Two Arm Military Press', 'ケトルベル Two Arm Military プレスは、ケトルベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Two Arm Military Press is an effective exercise targeting the triceps using kettlebell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0553-blBXysN.jpg', 'videos/0553-blBXysN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1345', 'kettlebell-two-arm-row', 'ケトルベル Two Arm ロー', 'Kettlebell Two Arm Row', 'ケトルベル Two Arm ローは、ケトルベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Two Arm Row is an effective exercise targeting the biceps using kettlebell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1345-wf24o8S.jpg', 'videos/1345-wf24o8S.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0554', 'kettlebell-windmill', 'ケトルベル Windmill', 'Kettlebell Windmill', 'ケトルベル Windmillは、ケトルベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kettlebell Windmill is an effective exercise targeting the obliques using kettlebell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0554-9Tkqa9O.jpg', 'videos/0554-9Tkqa9O.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0555', 'kick-out-sit', 'Kick Out Sit', 'Kick Out Sit', 'Kick Out Sitは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Kick Out Sit is an effective exercise targeting the quadriceps using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."]', 'images/0555-v7p5bYl.jpg', 'videos/0555-v7p5bYl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0558', 'kipping-muscle-up', 'Kipping Muscle Up', 'Kipping Muscle Up', 'Kipping Muscle Upは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kipping Muscle Up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."]', 'images/0558-pM07UxU.jpg', 'videos/0558-pM07UxU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3640', 'knee-touch-crunch', 'Knee Touch クランチ', 'Knee Touch Crunch', 'Knee Touch クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Knee Touch Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."]', 'images/3640-dTg95eZ.jpg', 'videos/3640-dTg95eZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1420', 'kneeling-jump-squat', 'ニーリング Jump スクワット', 'Kneeling Jump Squat', 'ニーリング Jump スクワットは、バーベルを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Kneeling Jump Squat is an effective exercise targeting the quadriceps using barbell.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."]', 'images/1420-UgDm3oy.jpg', 'videos/1420-UgDm3oy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1346', 'kneeling-lat-stretch', 'ニーリング Lat ストレッチ', 'Kneeling Lat Stretch', 'ニーリング Lat ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Kneeling Lat Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."]', 'images/1346-f38OEuO.jpg', 'videos/1346-f38OEuO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3239', 'kneeling-plank-tap-shoulder-male', 'ニーリング プランク Tap Shoulder (male)', 'Kneeling Plank Tap Shoulder (male)', 'ニーリング プランク Tap Shoulder (male)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Kneeling Plank Tap Shoulder (male) is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."]', 'images/3239-h1ezqSu.jpg', 'videos/3239-h1ezqSu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3211', 'kneeling-push-up-male', 'ニーリング プッシュアップ (male)', 'Kneeling Push-up (male)', 'ニーリング プッシュアップ (male)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Kneeling Push-up (male) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/3211-ZOuKWir.jpg', 'videos/3211-ZOuKWir.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3288', 'korean-dips', 'Korean ディップス', 'Korean Dips', 'Korean ディップスは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Korean Dips is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/3288-rWoBmi5.jpg', 'videos/3288-rWoBmi5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3418', 'l-pull-up', 'L-プルアップ', 'L-pull-up', 'L-プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'L-pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3418-d1GgzTU.jpg', 'videos/3418-d1GgzTU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3419', 'l-sit-on-floor', 'L-sit On Floor', 'L-sit On Floor', 'L-sit On Floorは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'L-sit On Floor is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an ''L'' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3419-UpWmA5E.jpg', 'videos/3419-UpWmA5E.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0562', 'landmine-180', 'Landmine 180', 'Landmine 180', 'Landmine 180は、バーベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Landmine 180 is an effective exercise targeting the obliques using barbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."]', 'images/0562-QYysSLV.jpg', 'videos/0562-QYysSLV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3237', 'landmine-lateral-raise', 'Landmine サイド レイズ', 'Landmine Lateral Raise', 'Landmine サイド レイズは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Landmine Lateral Raise is an effective exercise targeting the traps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3237-eXMFHww.jpg', 'videos/3237-eXMFHww.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3300', 'lean-planche', 'Lean Planche', 'Lean Planche', 'Lean Plancheは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lean Planche is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3300-LYJodFS.jpg', 'videos/3300-LYJodFS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2271', 'left-hook-boxing', 'Left Hook. Boxing', 'Left Hook. Boxing', 'Left Hook. Boxingは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Left Hook. Boxing is an effective exercise targeting the biceps using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."]', 'images/2271-hoXt6wv.jpg', 'videos/2271-hoXt6wv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0570', 'leg-pull-in-flat-bench', 'Leg Pull In Flat ベンチ', 'Leg Pull In Flat Bench', 'Leg Pull In Flat ベンチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Leg Pull In Flat Bench is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'pull', 'core', '["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0570-OyoZ3Pu.jpg', 'videos/0570-OyoZ3Pu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1576', 'leg-up-hamstring-stretch', 'Leg Up Hamstring ストレッチ', 'Leg Up Hamstring Stretch', 'Leg Up Hamstring ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Leg Up Hamstring Stretch is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."]', 'images/1576-sU5BrfP.jpg', 'videos/1576-sU5BrfP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2287', 'lever-alternate-leg-press', 'Lever Alternate Leg プレス', 'Lever Alternate Leg Press', 'Lever Alternate Leg プレスは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Alternate Leg Press is an effective exercise targeting the hamstrings using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/2287-V07qpXy.jpg', 'videos/2287-V07qpXy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0571', 'lever-alternating-narrow-grip-seated-row', 'Lever Alternating Narrow Grip シーテッド ロー', 'Lever Alternating Narrow Grip Seated Row', 'Lever Alternating Narrow Grip シーテッド ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Alternating Narrow Grip Seated Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0571-w2oRpuH.jpg', 'videos/0571-w2oRpuH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0572', 'lever-assisted-chin-up', 'Lever アシスト チンアップ', 'Lever Assisted Chin-up', 'Lever アシスト チンアップは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Assisted Chin-up is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0572-MaMuGH6.jpg', 'videos/0572-MaMuGH6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0573', 'lever-back-extension', 'Lever バック エクステンション', 'Lever Back Extension', 'Lever バック エクステンションは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Back Extension is an effective exercise targeting the glutes using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0573-rUXfn3R.jpg', 'videos/0573-rUXfn3R.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0574', 'lever-bent-over-row', 'Lever Bent Over ロー', 'Lever Bent Over Row', 'Lever Bent Over ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Bent Over Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0574-X3cqyXz.jpg', 'videos/0574-X3cqyXz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3200', 'lever-bent-over-row-with-v-bar', 'Lever Bent-over ロー With V-bar', 'Lever Bent-over Row With V-bar', 'Lever Bent-over ロー With V-barは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Bent-over Row With V-bar is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3200-LuBEORI.jpg', 'videos/3200-LuBEORI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0575', 'lever-bicep-curl', 'Lever Bicep カール', 'Lever Bicep Curl', 'Lever Bicep カールは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Bicep Curl is an effective exercise targeting the forearms using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0575-q6y3OhV.jpg', 'videos/0575-q6y3OhV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2289', 'lever-calf-press', 'Lever カーフ プレス', 'Lever Calf Press', 'Lever カーフ プレスは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Calf Press is an effective exercise targeting the hamstrings using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."]', 'images/2289-7B4F5nZ.jpg', 'videos/2289-7B4F5nZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0577', 'lever-chest-press', 'Lever チェスト プレス', 'Lever Chest Press', 'Lever チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Chest Press is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', 'images/0577-T0yTjgW.jpg', 'videos/0577-T0yTjgW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0576', 'lever-chest-press-0576', 'Lever チェスト プレス', 'Lever Chest Press', 'Lever チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Chest Press is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', 'images/0576-DOoWcnA.jpg', 'videos/0576-DOoWcnA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0578', 'lever-deadlift', 'Lever デッドリフト', 'Lever Deadlift', 'Lever デッドリフトは、レバレッジマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lever Deadlift is an effective exercise targeting the hamstrings using leverage machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."]', 'images/0578-GUT8I22.jpg', 'videos/0578-GUT8I22.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1300', 'lever-decline-chest-press', 'Lever デクライン チェスト プレス', 'Lever Decline Chest Press', 'Lever デクライン チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Decline Chest Press is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1300-vsVoPHt.jpg', 'videos/1300-vsVoPHt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1253', 'lever-donkey-calf-raise', 'Lever Donkey カーフ レイズ', 'Lever Donkey Calf Raise', 'Lever Donkey カーフ レイズは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Donkey Calf Raise is an effective exercise targeting the hamstrings using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1253-C9LuR4A.jpg', 'videos/1253-C9LuR4A.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0579', 'lever-front-pulldown', 'Lever フロント プルダウン', 'Lever Front Pulldown', 'Lever フロント プルダウンは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Front Pulldown is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0579-7F1DVzn.jpg', 'videos/0579-7F1DVzn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0580', 'lever-gripless-shrug', 'Lever Gripless シュラッグ', 'Lever Gripless Shrug', 'Lever Gripless シュラッグは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Gripless Shrug is an effective exercise targeting the shoulders using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0580-f91FwXG.jpg', 'videos/0580-f91FwXG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1439', 'lever-gripless-shrug-v-2', 'Lever Gripless シュラッグ V. 2', 'Lever Gripless Shrug V. 2', 'Lever Gripless シュラッグ V. 2は、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Gripless Shrug V. 2 is an effective exercise targeting the shoulders using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1439-cbuFJrn.jpg', 'videos/1439-cbuFJrn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2288', 'lever-gripper-hands', 'Lever Gripper Hands', 'Lever Gripper Hands', 'Lever Gripper Handsは、レバレッジマシンを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Lever Gripper Hands is an effective exercise targeting the biceps using leverage machine.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2288-mKwcrHn.jpg', 'videos/2288-mKwcrHn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1615', 'lever-hammer-grip-preacher-curl', 'Lever ハンマー Grip Preacher カール', 'Lever Hammer Grip Preacher Curl', 'Lever ハンマー Grip Preacher カールは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Hammer Grip Preacher Curl is an effective exercise targeting the forearms using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1615-OAguZoG.jpg', 'videos/1615-OAguZoG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0581', 'lever-high-row', 'Lever High ロー', 'Lever High Row', 'Lever High ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever High Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0581-nZZZy9m.jpg', 'videos/0581-nZZZy9m.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2286', 'lever-hip-extension-v-2', 'Lever ヒップ エクステンション V. 2', 'Lever Hip Extension V. 2', 'Lever ヒップ エクステンション V. 2は、レバレッジマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lever Hip Extension V. 2 is an effective exercise targeting the hamstrings using leverage machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2286-OPqShYN.jpg', 'videos/2286-OPqShYN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2611', 'lever-horizontal-one-leg-press', 'Lever Horizontal One Leg プレス', 'Lever Horizontal One Leg Press', 'Lever Horizontal One Leg プレスは、レバレッジマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lever Horizontal One Leg Press is an effective exercise targeting the quadriceps using leverage machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/2611-9KU9TYF.jpg', 'videos/2611-9KU9TYF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1299', 'lever-incline-chest-press', 'Lever インクライン チェスト プレス', 'Lever Incline Chest Press', 'Lever インクライン チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Incline Chest Press is an effective exercise targeting the shoulders using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]', 'images/1299-jHAnWmT.jpg', 'videos/1299-jHAnWmT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1479', 'lever-incline-chest-press-v-2', 'Lever インクライン チェスト プレス V. 2', 'Lever Incline Chest Press V. 2', 'Lever インクライン チェスト プレス V. 2は、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Incline Chest Press V. 2 is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]', 'images/1479-o17Jfkt.jpg', 'videos/1479-o17Jfkt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0582', 'lever-kneeling-leg-curl', 'Lever ニーリング Leg カール', 'Lever Kneeling Leg Curl', 'Lever ニーリング Leg カールは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Kneeling Leg Curl is an effective exercise targeting the glutes using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."]', 'images/0582-nnmCTLN.jpg', 'videos/0582-nnmCTLN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0583', 'lever-kneeling-twist', 'Lever ニーリング ツイスト', 'Lever Kneeling Twist', 'Lever ニーリング ツイストは、レバレッジマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lever Kneeling Twist is an effective exercise targeting the obliques using leverage machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0583-sZOR9EV.jpg', 'videos/0583-sZOR9EV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0584', 'lever-lateral-raise', 'Lever サイド レイズ', 'Lever Lateral Raise', 'Lever サイド レイズは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Lateral Raise is an effective exercise targeting the traps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0584-dRTfGZT.jpg', 'videos/0584-dRTfGZT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0585', 'lever-leg-extension', 'Lever Leg エクステンション', 'Lever Leg Extension', 'Lever Leg エクステンションは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Leg Extension is an effective exercise targeting the hamstrings using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0585-my33uHU.jpg', 'videos/0585-my33uHU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0586', 'lever-lying-leg-curl', 'Lever ライイング Leg カール', 'Lever Lying Leg Curl', 'Lever ライイング Leg カールは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Lying Leg Curl is an effective exercise targeting the calves using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0586-17lJ1kr.jpg', 'videos/0586-17lJ1kr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3195', 'lever-lying-two-one-leg-curl', 'Lever ライイング Two-one Leg カール', 'Lever Lying Two-one Leg Curl', 'Lever ライイング Two-one Leg カールは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Lying Two-one Leg Curl is an effective exercise targeting the glutes using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3195-UXpKJoq.jpg', 'videos/3195-UXpKJoq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0587', 'lever-military-press', 'Lever Military プレス', 'Lever Military Press', 'Lever Military プレスは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Military Press is an effective exercise targeting the triceps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0587-CggQhII.jpg', 'videos/0587-CggQhII.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0588', 'lever-narrow-grip-seated-row', 'Lever Narrow Grip シーテッド ロー', 'Lever Narrow Grip Seated Row', 'Lever Narrow Grip シーテッド ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Narrow Grip Seated Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0588-IGjKj1v.jpg', 'videos/0588-IGjKj1v.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0589', 'lever-one-arm-bent-over-row', 'Lever ワンハンド Bent Over ロー', 'Lever One Arm Bent Over Row', 'Lever ワンハンド Bent Over ローは、バーベルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever One Arm Bent Over Row is an effective exercise targeting the biceps using barbell.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0589-Fhdtwf3.jpg', 'videos/0589-Fhdtwf3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1356', 'lever-one-arm-lateral-high-row', 'Lever ワンハンド サイド High ロー', 'Lever One Arm Lateral High Row', 'Lever ワンハンド サイド High ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever One Arm Lateral High Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1356-OIFMAp1.jpg', 'videos/1356-OIFMAp1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1347', 'lever-one-arm-lateral-wide-pulldown', 'Lever ワンハンド サイド Wide プルダウン', 'Lever One Arm Lateral Wide Pulldown', 'Lever ワンハンド サイド Wide プルダウンは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever One Arm Lateral Wide Pulldown is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1347-tTuZSDT.jpg', 'videos/1347-tTuZSDT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0590', 'lever-one-arm-shoulder-press', 'Lever ワンハンド Shoulder プレス', 'Lever One Arm Shoulder Press', 'Lever ワンハンド Shoulder プレスは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever One Arm Shoulder Press is an effective exercise targeting the triceps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/0590-2KGnL6M.jpg', 'videos/0590-2KGnL6M.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0591', 'lever-overhand-triceps-dip', 'Lever Overhand トライセップス ディップス', 'Lever Overhand Triceps Dip', 'Lever Overhand トライセップス ディップスは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Overhand Triceps Dip is an effective exercise targeting the chest using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', 'images/0591-D5yqP2p.jpg', 'videos/0591-D5yqP2p.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0592', 'lever-preacher-curl', 'Lever Preacher カール', 'Lever Preacher Curl', 'Lever Preacher カールは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Preacher Curl is an effective exercise targeting the forearms using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0592-b6hQYMb.jpg', 'videos/0592-b6hQYMb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1614', 'lever-preacher-curl-v-2', 'Lever Preacher カール V. 2', 'Lever Preacher Curl V. 2', 'Lever Preacher カール V. 2は、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Preacher Curl V. 2 is an effective exercise targeting the forearms using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1614-ye84CTU.jpg', 'videos/1614-ye84CTU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2285', 'lever-pullover', 'Lever プルオーバー', 'Lever Pullover', 'Lever プルオーバーは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Pullover is an effective exercise targeting the triceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2285-4U7iLb5.jpg', 'videos/2285-4U7iLb5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2736', 'lever-reverse-grip-lateral-pulldown', 'Lever Reverse Grip サイド プルダウン', 'Lever Reverse Grip Lateral Pulldown', 'Lever Reverse Grip サイド プルダウンは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Reverse Grip Lateral Pulldown is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2736-ky8FLU8.jpg', 'videos/2736-ky8FLU8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1616', 'lever-reverse-grip-preacher-curl', 'Lever Reverse Grip Preacher カール', 'Lever Reverse Grip Preacher Curl', 'Lever Reverse Grip Preacher カールは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Reverse Grip Preacher Curl is an effective exercise targeting the forearms using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', 'images/1616-kj3hy6W.jpg', 'videos/1616-kj3hy6W.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1348', 'lever-reverse-grip-vertical-row', 'Lever Reverse Grip Vertical ロー', 'Lever Reverse Grip Vertical Row', 'Lever Reverse Grip Vertical ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Reverse Grip Vertical Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1348-ZqNOWQ6.jpg', 'videos/1348-ZqNOWQ6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0593', 'lever-reverse-hyperextension', 'Lever Reverse Hyperextension', 'Lever Reverse Hyperextension', 'Lever Reverse Hyperextensionは、レバレッジマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lever Reverse Hyperextension is an effective exercise targeting the hamstrings using leverage machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0593-Krmb3cB.jpg', 'videos/0593-Krmb3cB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1349', 'lever-reverse-t-bar-row', 'Lever Reverse T-bar ロー', 'Lever Reverse T-bar Row', 'Lever Reverse T-bar ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Reverse T-bar Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1349-BgljGjd.jpg', 'videos/1349-BgljGjd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2315', 'lever-rotary-calf', 'Lever Rotary カーフ', 'Lever Rotary Calf', 'Lever Rotary カーフは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Rotary Calf is an effective exercise targeting the soleus using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2315-MrgP9L6.jpg', 'videos/2315-MrgP9L6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2335', 'lever-seated-calf-press', 'Lever シーテッド カーフ プレス', 'Lever Seated Calf Press', 'Lever シーテッド カーフ プレスは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Calf Press is an effective exercise targeting the soleus using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2335-Ie9UGty.jpg', 'videos/2335-Ie9UGty.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0594', 'lever-seated-calf-raise', 'Lever シーテッド カーフ レイズ', 'Lever Seated Calf Raise', 'Lever シーテッド カーフ レイズは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Calf Raise is an effective exercise targeting the soleus using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0594-bOOdeyc.jpg', 'videos/0594-bOOdeyc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1452', 'lever-seated-crunch', 'Lever シーテッド クランチ', 'Lever Seated Crunch', 'Lever シーテッド クランチは、レバレッジマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Crunch is an effective exercise targeting the obliques using leverage machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1452-Wgaz7pm.jpg', 'videos/1452-Wgaz7pm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0595', 'lever-seated-crunch-chest-pad', 'Lever シーテッド クランチ (チェスト Pad)', 'Lever Seated Crunch (chest Pad)', 'Lever シーテッド クランチ (チェスト Pad)は、レバレッジマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Crunch (chest Pad) is an effective exercise targeting the obliques using leverage machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."]', 'images/0595-ZnJHhMk.jpg', 'videos/0595-ZnJHhMk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3760', 'lever-seated-crunch-v-2', 'Lever シーテッド クランチ V. 2', 'Lever Seated Crunch V. 2', 'Lever シーテッド クランチ V. 2は、レバレッジマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Crunch V. 2 is an effective exercise targeting the obliques using leverage machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."]', 'images/3760-eXFXCY0.jpg', 'videos/3760-eXFXCY0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1451', 'lever-seated-dip', 'Lever シーテッド ディップス', 'Lever Seated Dip', 'Lever シーテッド ディップスは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Dip is an effective exercise targeting the chest using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/1451-BRImeP8.jpg', 'videos/1451-BRImeP8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0596', 'lever-seated-fly', 'Lever シーテッド フライ', 'Lever Seated Fly', 'Lever シーテッド フライは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Fly is an effective exercise targeting the deltoids using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."]', 'images/0596-v3xmPAR.jpg', 'videos/0596-v3xmPAR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3759', 'lever-seated-good-morning', 'Lever シーテッド Good Morning', 'Lever Seated Good Morning', 'Lever シーテッド Good Morningは、レバレッジマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Good Morning is an effective exercise targeting the hamstrings using leverage machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."]', 'images/3759-XsCcxCC.jpg', 'videos/3759-XsCcxCC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0597', 'lever-seated-hip-abduction', 'Lever シーテッド ヒップ Abduction', 'Lever Seated Hip Abduction', 'Lever シーテッド ヒップ Abductionは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Hip Abduction is an effective exercise targeting the glutes using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."]', 'images/0597-CHpahtl.jpg', 'videos/0597-CHpahtl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0598', 'lever-seated-hip-adduction', 'Lever シーテッド ヒップ Adduction', 'Lever Seated Hip Adduction', 'Lever シーテッド ヒップ Adductionは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Hip Adduction is an effective exercise targeting the hamstrings using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0598-oHsrypV.jpg', 'videos/0598-oHsrypV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0599', 'lever-seated-leg-curl', 'Lever シーテッド Leg カール', 'Lever Seated Leg Curl', 'Lever シーテッド Leg カールは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Leg Curl is an effective exercise targeting the calves using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0599-Zg3XY7P.jpg', 'videos/0599-Zg3XY7P.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0600', 'lever-seated-leg-raise-crunch', 'Lever シーテッド Leg レイズ クランチ', 'Lever Seated Leg Raise Crunch', 'Lever シーテッド Leg レイズ クランチは、レバレッジマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Leg Raise Crunch is an effective exercise targeting the hip flexors using leverage machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0600-PQ2AtC3.jpg', 'videos/0600-PQ2AtC3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0602', 'lever-seated-reverse-fly', 'Lever シーテッド Reverse フライ', 'Lever Seated Reverse Fly', 'Lever シーテッド Reverse フライは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Reverse Fly is an effective exercise targeting the trapezius using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0602-myfUsKf.jpg', 'videos/0602-myfUsKf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0601', 'lever-seated-reverse-fly-parallel-grip', 'Lever シーテッド Reverse フライ (parallel Grip)', 'Lever Seated Reverse Fly (parallel Grip)', 'Lever シーテッド Reverse フライ (parallel Grip)は、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Reverse Fly (parallel Grip) is an effective exercise targeting the trapezius using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0601-xiHiJcA.jpg', 'videos/0601-xiHiJcA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1350', 'lever-seated-row', 'Lever シーテッド ロー', 'Lever Seated Row', 'Lever シーテッド ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1350-7I6LNUG.jpg', 'videos/1350-7I6LNUG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1385', 'lever-seated-squat-calf-raise-on-leg-press-machine', 'Lever シーテッド スクワット カーフ レイズ On Leg プレス マシン', 'Lever Seated Squat Calf Raise On Leg Press Machine', 'Lever シーテッド スクワット カーフ レイズ On Leg プレス マシンは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Seated Squat Calf Raise On Leg Press Machine is an effective exercise targeting the quadriceps using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."]', 'images/1385-IeDEXTe.jpg', 'videos/1385-IeDEXTe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0603', 'lever-shoulder-press', 'Lever Shoulder プレス', 'Lever Shoulder Press', 'Lever Shoulder プレスは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Shoulder Press is an effective exercise targeting the triceps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0603-67n3r98.jpg', 'videos/0603-67n3r98.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0869', 'lever-shoulder-press-v-2', 'Lever Shoulder プレス V. 2', 'Lever Shoulder Press V. 2', 'Lever Shoulder プレス V. 2は、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Shoulder Press V. 2 is an effective exercise targeting the triceps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0869-vqsbmL0.jpg', 'videos/0869-vqsbmL0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2318', 'lever-shoulder-press-v-3', 'Lever Shoulder プレス V. 3', 'Lever Shoulder Press V. 3', 'Lever Shoulder プレス V. 3は、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Shoulder Press V. 3 is an effective exercise targeting the triceps using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2318-dNFYIU1.jpg', 'videos/2318-dNFYIU1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0604', 'lever-shrug', 'Lever シュラッグ', 'Lever Shrug', 'Lever シュラッグは、レバレッジマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Lever Shrug is an effective exercise targeting the shoulders using leverage machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0604-ZZKbeMw.jpg', 'videos/0604-ZZKbeMw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0605', 'lever-standing-calf-raise', 'Lever スタンディング カーフ レイズ', 'Lever Standing Calf Raise', 'Lever スタンディング カーフ レイズは、レバレッジマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lever Standing Calf Raise is an effective exercise targeting the soleus using leverage machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0605-ykUOVze.jpg', 'videos/0605-ykUOVze.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3758', 'lever-standing-chest-press', 'Lever スタンディング チェスト プレス', 'Lever Standing Chest Press', 'Lever スタンディング チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Lever Standing Chest Press is an effective exercise targeting the shoulders using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', 'images/3758-WbNq5Xu.jpg', 'videos/3758-WbNq5Xu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0606', 'lever-t-bar-row', 'Lever T Bar ロー', 'Lever T Bar Row', 'Lever T Bar ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever T Bar Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0606-aaXr7ld.jpg', 'videos/0606-aaXr7ld.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1351', 'lever-t-bar-reverse-grip-row', 'Lever T-bar Reverse Grip ロー', 'Lever T-bar Reverse Grip Row', 'Lever T-bar Reverse Grip ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever T-bar Reverse Grip Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1351-FVM1AUZ.jpg', 'videos/1351-FVM1AUZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0607', 'lever-triceps-extension', 'Lever トライセップス エクステンション', 'Lever Triceps Extension', 'Lever トライセップス エクステンションは、レバレッジマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Lever Triceps Extension is an effective exercise targeting the shoulders using leverage machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0607-Ser9eQp.jpg', 'videos/0607-Ser9eQp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1313', 'lever-unilateral-row', 'Lever Unilateral ロー', 'Lever Unilateral Row', 'Lever Unilateral ローは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lever Unilateral Row is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1313-oROuvrX.jpg', 'videos/1313-oROuvrX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0609', 'london-bridge', 'London Bridge', 'London Bridge', 'London Bridgeは、ロープを使用した背中をターゲットとする効果的なトレーニング種目です。', 'London Bridge is an effective exercise targeting the shoulders using rope.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0609-bLyQokI.jpg', 'videos/0609-bLyQokI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3013', 'low-glute-bridge-on-floor', 'Low グルート Bridge On Floor', 'Low Glute Bridge On Floor', 'Low グルート Bridge On Floorは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Low Glute Bridge On Floor is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3013-u0cNiij.jpg', 'videos/3013-u0cNiij.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1352', 'lower-back-curl', 'Lower バック カール', 'Lower Back Curl', 'Lower バック カールは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Lower Back Curl is an effective exercise targeting the glutes using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1352-ANbbry2.jpg', 'videos/1352-ANbbry2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3582', 'lunge-with-jump', 'ランジ With Jump', 'Lunge With Jump', 'ランジ With Jumpは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Lunge With Jump is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."]', 'images/3582-PM1PZjg.jpg', 'videos/3582-PM1PZjg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1688', 'lunge-with-twist', 'ランジ With ツイスト', 'Lunge With Twist', 'ランジ With ツイストは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lunge With Twist is an effective exercise targeting the quadriceps using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."]', 'images/1688-K9VL0Jq.jpg', 'videos/1688-K9VL0Jq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0613', 'lying-side-quads-stretch', 'ライイング (side) Quads ストレッチ', 'Lying (side) Quads Stretch', 'ライイング (side) Quads ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Lying (side) Quads Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', 'images/0613-BWnJR72.jpg', 'videos/0613-BWnJR72.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2312', 'lying-elbow-to-knee', 'ライイング Elbow To Knee', 'Lying Elbow To Knee', 'ライイング Elbow To Kneeは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lying Elbow To Knee is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."]', 'images/2312-AQIhRjM.jpg', 'videos/2312-AQIhRjM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0620', 'lying-leg-raise-flat-bench', 'ライイング Leg レイズ Flat ベンチ', 'Lying Leg Raise Flat Bench', 'ライイング Leg レイズ Flat ベンチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lying Leg Raise Flat Bench is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0620-WhuFnR7.jpg', 'videos/0620-WhuFnR7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0865', 'lying-leg-hip-raise', 'ライイング Leg-ヒップ レイズ', 'Lying Leg-hip Raise', 'ライイング Leg-ヒップ レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Lying Leg-hip Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0865-9IxJdtC.jpg', 'videos/0865-9IxJdtC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1301', 'machine-inner-chest-press', 'マシン Inner チェスト プレス', 'Machine Inner Chest Press', 'マシン Inner チェスト プレスは、レバレッジマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Machine Inner Chest Press is an effective exercise targeting the triceps using leverage machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', 'images/1301-wDN97Ca.jpg', 'videos/1301-wDN97Ca.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0624', 'march-sit-wall', 'March Sit (wall)', 'March Sit (wall)', 'March Sit (wall)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'March Sit (wall) is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."]', 'images/0624-sVQCCeG.jpg', 'videos/0624-sVQCCeG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1353', 'medicine-ball-catch-and-overhead-throw', 'Medicine Ball Catch And オーバーヘッド Throw', 'Medicine Ball Catch And Overhead Throw', 'Medicine Ball Catch And オーバーヘッド Throwは、メディシンボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Catch And Overhead Throw is an effective exercise targeting the shoulders using medicine ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."]', 'images/1353-PsVS1QP.jpg', 'videos/1353-PsVS1QP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1302', 'medicine-ball-chest-pass', 'Medicine Ball チェスト Pass', 'Medicine Ball Chest Pass', 'Medicine Ball チェスト Passは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Chest Pass is an effective exercise targeting the shoulders using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."]', 'images/1302-aDoFKrE.jpg', 'videos/1302-aDoFKrE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1303', 'medicine-ball-chest-push-from-3-point-stance', 'Medicine Ball チェスト Push From 3 Point Stance', 'Medicine Ball Chest Push From 3 Point Stance', 'Medicine Ball チェスト Push From 3 Point Stanceは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Chest Push From 3 Point Stance is an effective exercise targeting the shoulders using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."]', 'images/1303-dCJnuVq.jpg', 'videos/1303-dCJnuVq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1304', 'medicine-ball-chest-push-multiple-response', 'Medicine Ball チェスト Push Multiple Response', 'Medicine Ball Chest Push Multiple Response', 'Medicine Ball チェスト Push Multiple Responseは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Chest Push Multiple Response is an effective exercise targeting the triceps using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', 'images/1304-7aolH9D.jpg', 'videos/1304-7aolH9D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1305', 'medicine-ball-chest-push-single-response', 'Medicine Ball チェスト Push Single Response', 'Medicine Ball Chest Push Single Response', 'Medicine Ball チェスト Push Single Responseは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Chest Push Single Response is an effective exercise targeting the triceps using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', 'images/1305-jeHtrlO.jpg', 'videos/1305-jeHtrlO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1312', 'medicine-ball-chest-push-with-run-release', 'Medicine Ball チェスト Push With Run Release', 'Medicine Ball Chest Push With Run Release', 'Medicine Ball チェスト Push With Run Releaseは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Chest Push With Run Release is an effective exercise targeting the triceps using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."]', 'images/1312-pX9Elbe.jpg', 'videos/1312-pX9Elbe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1701', 'medicine-ball-close-grip-push-up', 'Medicine Ball Close Grip Push Up', 'Medicine Ball Close Grip Push Up', 'Medicine Ball Close Grip Push Upは、メディシンボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Close Grip Push Up is an effective exercise targeting the chest using medicine ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1701-8K7m2SS.jpg', 'videos/1701-8K7m2SS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1354', 'medicine-ball-overhead-slam', 'Medicine Ball オーバーヘッド Slam', 'Medicine Ball Overhead Slam', 'Medicine Ball オーバーヘッド Slamは、メディシンボールを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Overhead Slam is an effective exercise targeting the shoulders using medicine ball.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."]', 'images/1354-oHg8eop.jpg', 'videos/1354-oHg8eop.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1750', 'medicine-ball-supine-chest-throw', 'Medicine Ball Supine チェスト Throw', 'Medicine Ball Supine Chest Throw', 'Medicine Ball Supine チェスト Throwは、メディシンボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Medicine Ball Supine Chest Throw is an effective exercise targeting the chest using medicine ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."]', 'images/1750-Al3tP0D.jpg', 'videos/1750-Al3tP0D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0627', 'mixed-grip-chin-up', 'Mixed Grip チンアップ', 'Mixed Grip Chin-up', 'Mixed Grip チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Mixed Grip Chin-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', 'images/0627-T8UpLkb.jpg', 'videos/0627-T8UpLkb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3217', 'modified-hindu-push-up-male', 'Modified Hindu プッシュアップ (male)', 'Modified Hindu Push-up (male)', 'Modified Hindu プッシュアップ (male)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Modified Hindu Push-up (male) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3217-epOSYUZ.jpg', 'videos/3217-epOSYUZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1421', 'modified-push-up-to-lower-arms', 'Modified Push Up To Lower Arms', 'Modified Push Up To Lower Arms', 'Modified Push Up To Lower Armsは、自重を使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Modified Push Up To Lower Arms is an effective exercise targeting the triceps using body weight.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1421-arvaszz.jpg', 'videos/1421-arvaszz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0628', 'monster-walk', 'Monster Walk', 'Monster Walk', 'Monster Walkは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Monster Walk is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0628-O95afRA.jpg', 'videos/0628-O95afRA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0630', 'mountain-climber', 'Mountain Climber', 'Mountain Climber', 'Mountain Climberは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Mountain Climber is an effective exercise targeting the core using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]', 'images/0630-RJgzwny.jpg', 'videos/0630-RJgzwny.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0631', 'muscle-up', 'Muscle Up', 'Muscle Up', 'Muscle Upは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Muscle Up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0631-yJUHKTn.jpg', 'videos/0631-yJUHKTn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1401', 'muscle-up-on-vertical-bar', 'Muscle-up (on Vertical Bar)', 'Muscle-up (on Vertical Bar)', 'Muscle-up (on Vertical Bar)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Muscle-up (on Vertical Bar) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1401-Af0EW2I.jpg', 'videos/1401-Af0EW2I.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2328', 'narrow-push-up-on-exercise-ball', 'Narrow プッシュアップ On Exercise Ball', 'Narrow Push-up On Exercise Ball', 'Narrow プッシュアップ On Exercise Ballは、スタビリティボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Narrow Push-up On Exercise Ball is an effective exercise targeting the chest using stability ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/2328-4cWjYEN.jpg', 'videos/2328-4cWjYEN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1403', 'neck-side-stretch', 'ネック Side ストレッチ', 'Neck Side Stretch', 'ネック Side ストレッチは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Neck Side Stretch is an effective exercise targeting the trapezius using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."]', 'images/1403-x2chWLO.jpg', 'videos/1403-x2chWLO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0634', 'negative-crunch', 'Negative クランチ', 'Negative Crunch', 'Negative クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Negative Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0634-szIn2UK.jpg', 'videos/0634-szIn2UK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1495', 'oblique-crunch-v-2', 'オブリーク クランチ V. 2', 'Oblique Crunch V. 2', 'オブリーク クランチ V. 2は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Oblique Crunch V. 2 is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1495-cJgSTmh.jpg', 'videos/1495-cJgSTmh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0635', 'oblique-crunches-floor', 'オブリーク Crunches Floor', 'Oblique Crunches Floor', 'オブリーク Crunches Floorは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Oblique Crunches Floor is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."]', 'images/0635-QUDd8WS.jpg', 'videos/0635-QUDd8WS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0636', 'olympic-barbell-hammer-curl', 'Olympic バーベル ハンマー カール', 'Olympic Barbell Hammer Curl', 'Olympic バーベル ハンマー カールは、olympic barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Olympic Barbell Hammer Curl is an effective exercise targeting the forearms using olympic barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0636-o1ntciW.jpg', 'videos/0636-o1ntciW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0637', 'olympic-barbell-triceps-extension', 'Olympic バーベル トライセップス エクステンション', 'Olympic Barbell Triceps Extension', 'Olympic バーベル トライセップス エクステンションは、olympic barbellを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Olympic Barbell Triceps Extension is an effective exercise targeting the shoulders using olympic barbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0637-wu5LXwz.jpg', 'videos/0637-wu5LXwz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1355', 'one-arm-against-wall', 'ワンハンド Against Wall', 'One Arm Against Wall', 'ワンハンド Against Wallは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'One Arm Against Wall is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."]', 'images/1355-ZZTGMKh.jpg', 'videos/1355-ZZTGMKh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0638', 'one-arm-chin-up', 'ワンハンド チンアップ', 'One Arm Chin-up', 'ワンハンド チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'One Arm Chin-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', 'images/0638-HjdqmZa.jpg', 'videos/0638-HjdqmZa.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0639', 'one-arm-dip', 'ワンハンド ディップス', 'One Arm Dip', 'ワンハンド ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'One Arm Dip is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', 'images/0639-FAoIFMw.jpg', 'videos/0639-FAoIFMw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0640', 'one-arm-slam-with-medicine-ball', 'ワンハンド Slam (with Medicine Ball)', 'One Arm Slam (with Medicine Ball)', 'ワンハンド Slam (with Medicine Ball)は、メディシンボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'One Arm Slam (with Medicine Ball) is an effective exercise targeting the shoulders using medicine ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]', 'images/0640-jCrtE9b.jpg', 'videos/0640-jCrtE9b.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1773', 'one-arm-towel-row', 'ワンハンド タオル ロー', 'One Arm Towel Row', 'ワンハンド タオル ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'One Arm Towel Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', 'images/1773-bKWbrTA.jpg', 'videos/1773-bKWbrTA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1386', 'one-leg-donkey-calf-raise', 'One Leg Donkey カーフ レイズ', 'One Leg Donkey Calf Raise', 'One Leg Donkey カーフ レイズは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'One Leg Donkey Calf Raise is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."]', 'images/1386-A2upspL.jpg', 'videos/1386-A2upspL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1387', 'one-leg-floor-calf-raise', 'One Leg Floor カーフ レイズ', 'One Leg Floor Calf Raise', 'One Leg Floor カーフ レイズは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'One Leg Floor Calf Raise is an effective exercise targeting the ankles using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1387-0jp9Rlz.jpg', 'videos/1387-0jp9Rlz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1476', 'one-leg-squat', 'One Leg スクワット', 'One Leg Squat', 'One Leg スクワットは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'One Leg Squat is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."]', 'images/1476-C31LMnP.jpg', 'videos/1476-C31LMnP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0641', 'otis-up', 'Otis Up', 'Otis Up', 'Otis Upは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Otis Up is an effective exercise targeting the hip flexors using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0641-UVL20oz.jpg', 'videos/0641-UVL20oz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0642', 'outside-leg-kick-push-up', 'Outside Leg Kick プッシュアップ', 'Outside Leg Kick Push-up', 'Outside Leg Kick プッシュアップは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Outside Leg Kick Push-up is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."]', 'images/0642-jNU1gFQ.jpg', 'videos/0642-jNU1gFQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0643', 'overhead-triceps-stretch', 'オーバーヘッド トライセップス ストレッチ', 'Overhead Triceps Stretch', 'オーバーヘッド トライセップス ストレッチは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Overhead Triceps Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', 'images/0643-Z5YStHW.jpg', 'videos/0643-Z5YStHW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3147', 'pelvic-tilt', 'Pelvic Tilt', 'Pelvic Tilt', 'Pelvic Tiltは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Pelvic Tilt is an effective exercise targeting the lower back using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3147-NKJ8o6x.jpg', 'videos/3147-NKJ8o6x.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1422', 'pelvic-tilt-into-bridge', 'Pelvic Tilt Into Bridge', 'Pelvic Tilt Into Bridge', 'Pelvic Tilt Into Bridgeは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Pelvic Tilt Into Bridge is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1422-D9qe7CM.jpg', 'videos/1422-D9qe7CM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1388', 'peroneals-stretch', 'Peroneals ストレッチ', 'Peroneals Stretch', 'Peroneals ストレッチは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Peroneals Stretch is an effective exercise targeting the ankles using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."]', 'images/1388-XhfS1DZ.jpg', 'videos/1388-XhfS1DZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3662', 'pike-to-cobra-push-up', 'Pike-to-cobra プッシュアップ', 'Pike-to-cobra Push-up', 'Pike-to-cobra プッシュアップは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Pike-to-cobra Push-up is an effective exercise targeting the core using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."]', 'images/3662-XPUDTt7.jpg', 'videos/3662-XPUDTt7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1306', 'plyo-push-up', 'Plyo Push Up', 'Plyo Push Up', 'Plyo Push Upは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Plyo Push Up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."]', 'images/1306-Snj1wSv.jpg', 'videos/1306-Snj1wSv.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1687', 'posterior-step-to-overhead-reach', 'Posterior Step To オーバーヘッド Reach', 'Posterior Step To Overhead Reach', 'Posterior Step To オーバーヘッド Reachは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Posterior Step To Overhead Reach is an effective exercise targeting the glutes using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."]', 'images/1687-ErqK3UL.jpg', 'videos/1687-ErqK3UL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1389', 'posterior-tibialis-stretch', 'Posterior Tibialis ストレッチ', 'Posterior Tibialis Stretch', 'Posterior Tibialis ストレッチは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Posterior Tibialis Stretch is an effective exercise targeting the hamstrings using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."]', 'images/1389-DEEqoI2.jpg', 'videos/1389-DEEqoI2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3119', 'potty-squat', 'Potty スクワット', 'Potty Squat', 'Potty スクワットは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Potty Squat is an effective exercise targeting the quadriceps using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3119-75Bgtjy.jpg', 'videos/3119-75Bgtjy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3132', 'potty-squat-with-support', 'Potty スクワット With Support', 'Potty Squat With Support', 'Potty スクワット With Supportは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Potty Squat With Support is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3132-b63ZzGe.jpg', 'videos/3132-b63ZzGe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0648', 'power-clean', 'Power Clean', 'Power Clean', 'Power Cleanは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Power Clean is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."]', 'images/0648-SiWCcTN.jpg', 'videos/0648-SiWCcTN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3665', 'power-point-plank', 'Power Point プランク', 'Power Point Plank', 'Power Point プランクは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Power Point Plank is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."]', 'images/3665-hCjGsRQ.jpg', 'videos/3665-hCjGsRQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3203', 'prisoner-half-sit-up-male', 'Prisoner Half Sit-up (male)', 'Prisoner Half Sit-up (male)', 'Prisoner Half Sit-up (male)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Prisoner Half Sit-up (male) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3203-mgejmGP.jpg', 'videos/3203-mgejmGP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1707', 'prone-twist-on-stability-ball', 'プローン ツイスト On Stability Ball', 'Prone Twist On Stability Ball', 'プローン ツイスト On Stability Ballは、スタビリティボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Prone Twist On Stability Ball is an effective exercise targeting the obliques using stability ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/1707-1IG6gVF.jpg', 'videos/1707-1IG6gVF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0651', 'pull-up-neutral-grip', 'Pull Up (neutral Grip)', 'Pull Up (neutral Grip)', 'Pull Up (neutral Grip)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Pull Up (neutral Grip) is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', 'images/0651-0V2YQjW.jpg', 'videos/0651-0V2YQjW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0650', 'pull-in-on-stability-ball', 'Pull-in (on Stability Ball)', 'Pull-in (on Stability Ball)', 'Pull-in (on Stability Ball)は、スタビリティボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Pull-in (on Stability Ball) is an effective exercise targeting the hip flexors using stability ball.', 'mg-core', 'Beginner', 'compound', 'pull', 'core', '["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0650-UQr48Oi.jpg', 'videos/0650-UQr48Oi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0652', 'pull-up', 'プルアップ', 'Pull-up', 'プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0652-lBDjFxJ.jpg', 'videos/0652-lBDjFxJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1689', 'push-and-pull-bodyweight', 'Push And Pull 自重', 'Push And Pull Bodyweight', 'Push And Pull 自重は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push And Pull Bodyweight is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'pull', 'upper', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1689-wXvUZC8.jpg', 'videos/1689-wXvUZC8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3638', 'push-to-run', 'Push To Run', 'Push To Run', 'Push To Runは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Push To Run is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."]', 'images/3638-PrQbjvB.jpg', 'videos/3638-PrQbjvB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1307', 'push-up-on-bosu-ball', 'Push Up On Bosu Ball', 'Push Up On Bosu Ball', 'Push Up On Bosu Ballは、ボスボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push Up On Bosu Ball is an effective exercise targeting the triceps using bosu ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/1307-wVompEp.jpg', 'videos/1307-wVompEp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0662', 'push-up', 'プッシュアップ', 'Push-up', 'プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0662-I4hDWkc.jpg', 'videos/0662-I4hDWkc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0653', 'push-up-bosu-ball', 'プッシュアップ (bosu Ball)', 'Push-up (bosu Ball)', 'プッシュアップ (bosu Ball)は、ボスボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up (bosu Ball) is an effective exercise targeting the triceps using bosu ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', 'images/0653-2kr2lWy.jpg', 'videos/0653-2kr2lWy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0655', 'push-up-on-stability-ball', 'プッシュアップ (on Stability Ball)', 'Push-up (on Stability Ball)', 'プッシュアップ (on Stability Ball)は、スタビリティボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up (on Stability Ball) is an effective exercise targeting the triceps using stability ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0655-Y4BRNQF.jpg', 'videos/0655-Y4BRNQF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0656', 'push-up-on-stability-ball-0656', 'プッシュアップ (on Stability Ball)', 'Push-up (on Stability Ball)', 'プッシュアップ (on Stability Ball)は、スタビリティボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up (on Stability Ball) is an effective exercise targeting the triceps using stability ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0656-tgryw5Y.jpg', 'videos/0656-tgryw5Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0659', 'push-up-wall', 'プッシュアップ (wall)', 'Push-up (wall)', 'プッシュアップ (wall)は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up (wall) is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0659-LEH9jxP.jpg', 'videos/0659-LEH9jxP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0658', 'push-up-wall-v-2', 'プッシュアップ (wall) V. 2', 'Push-up (wall) V. 2', 'プッシュアップ (wall) V. 2は、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up (wall) V. 2 is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0658-NCmbLCw.jpg', 'videos/0658-NCmbLCw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0660', 'push-up-close-grip-off-dumbbell', 'プッシュアップ ナローグリップ Off ダンベル', 'Push-up Close-grip Off Dumbbell', 'プッシュアップ ナローグリップ Off ダンベルは、ダンベルを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Push-up Close-grip Off Dumbbell is an effective exercise targeting the chest using dumbbell.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0660-KZXAtKQ.jpg', 'videos/0660-KZXAtKQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0661', 'push-up-inside-leg-kick', 'プッシュアップ Inside Leg Kick', 'Push-up Inside Leg Kick', 'プッシュアップ Inside Leg Kickは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Push-up Inside Leg Kick is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."]', 'images/0661-0br45wL.jpg', 'videos/0661-0br45wL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0663', 'push-up-medicine-ball', 'プッシュアップ Medicine Ball', 'Push-up Medicine Ball', 'プッシュアップ Medicine Ballは、メディシンボールを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up Medicine Ball is an effective exercise targeting the triceps using medicine ball.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0663-W8KAlkI.jpg', 'videos/0663-W8KAlkI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1467', 'push-up-on-lower-arms', 'プッシュアップ On Lower Arms', 'Push-up On Lower Arms', 'プッシュアップ On Lower Armsは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Push-up On Lower Arms is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1467-4Jt8QsQ.jpg', 'videos/1467-4Jt8QsQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3145', 'push-up-plus', 'プッシュアップ Plus', 'Push-up Plus', 'プッシュアップ Plusは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Push-up Plus is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3145-pvBMLHA.jpg', 'videos/3145-pvBMLHA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0664', 'push-up-to-side-plank', 'プッシュアップ To Side プランク', 'Push-up To Side Plank', 'プッシュアップ To Side プランクは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Push-up To Side Plank is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."]', 'images/0664-KhHJ338.jpg', 'videos/0664-KhHJ338.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3533', 'quads', 'Quads', 'Quads', 'Quadsは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Quads is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3533-6YUfHPL.jpg', 'videos/3533-6YUfHPL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3201', 'quarter-sit-up', 'Quarter Sit-up', 'Quarter Sit-up', 'Quarter Sit-upは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Quarter Sit-up is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3201-enxnJcM.jpg', 'videos/3201-enxnJcM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3552', 'quick-feet-v-2', 'Quick Feet V. 2', 'Quick Feet V. 2', 'Quick Feet V. 2は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Quick Feet V. 2 is an effective exercise targeting the calves using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."]', 'images/3552-mweqJin.jpg', 'videos/3552-mweqJin.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0666', 'raise-single-arm-push-up', 'レイズ シングルアーム プッシュアップ', 'Raise Single Arm Push-up', 'レイズ シングルアーム プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Raise Single Arm Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."]', 'images/0666-13TpY4H.jpg', 'videos/0666-13TpY4H.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0668', 'rear-decline-bridge', 'リア デクライン Bridge', 'Rear Decline Bridge', 'リア デクライン Bridgeは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Rear Decline Bridge is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0668-UpAlold.jpg', 'videos/0668-UpAlold.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0669', 'rear-deltoid-stretch', 'リア Deltoid ストレッチ', 'Rear Deltoid Stretch', 'リア Deltoid ストレッチは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Rear Deltoid Stretch is an effective exercise targeting the trapezius using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', 'images/0669-xifhB5W.jpg', 'videos/0669-xifhB5W.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0670', 'rear-pull-up', 'リア プルアップ', 'Rear Pull-up', 'リア プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Rear Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0670-CbFSYC1.jpg', 'videos/0670-CbFSYC1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1582', 'reclining-big-toe-pose-with-rope', 'Reclining Big Toe Pose With Rope', 'Reclining Big Toe Pose With Rope', 'Reclining Big Toe Pose With Ropeは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Reclining Big Toe Pose With Rope is an effective exercise targeting the calves using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', 'images/1582-K5xgdvI.jpg', 'videos/1582-K5xgdvI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3236', 'resistance-band-hip-thrusts-on-knees-female', 'Resistance バンド ヒップ Thrusts On Knees (female)', 'Resistance Band Hip Thrusts On Knees (female)', 'Resistance バンド ヒップ Thrusts On Knees (female)は、レジスタンスバンドを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Hip Thrusts On Knees (female) is an effective exercise targeting the hamstrings using resistance band.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3236-Pjbc0Kt.jpg', 'videos/3236-Pjbc0Kt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3007', 'resistance-band-leg-extension', 'Resistance バンド Leg エクステンション', 'Resistance Band Leg Extension', 'Resistance バンド Leg エクステンションは、レジスタンスバンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Leg Extension is an effective exercise targeting the hamstrings using resistance band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/3007-Y1MsI1l.jpg', 'videos/3007-Y1MsI1l.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3123', 'resistance-band-seated-biceps-curl', 'Resistance バンド シーテッド バイセップス カール', 'Resistance Band Seated Biceps Curl', 'Resistance バンド シーテッド バイセップス カールは、レジスタンスバンドを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Seated Biceps Curl is an effective exercise targeting the forearms using resistance band.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."]', 'images/3123-XFc3vpY.jpg', 'videos/3123-XFc3vpY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3124', 'resistance-band-seated-chest-press', 'Resistance バンド シーテッド チェスト プレス', 'Resistance Band Seated Chest Press', 'Resistance バンド シーテッド チェスト プレスは、レジスタンスバンドを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Seated Chest Press is an effective exercise targeting the shoulders using resistance band.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3124-4x5Okof.jpg', 'videos/3124-4x5Okof.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3006', 'resistance-band-seated-hip-abduction', 'Resistance バンド シーテッド ヒップ Abduction', 'Resistance Band Seated Hip Abduction', 'Resistance バンド シーテッド ヒップ Abductionは、レジスタンスバンドを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Seated Hip Abduction is an effective exercise targeting the glutes using resistance band.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."]', 'images/3006-0xDpB4L.jpg', 'videos/3006-0xDpB4L.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3122', 'resistance-band-seated-shoulder-press', 'Resistance バンド シーテッド Shoulder プレス', 'Resistance Band Seated Shoulder Press', 'Resistance バンド シーテッド Shoulder プレスは、レジスタンスバンドを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Seated Shoulder Press is an effective exercise targeting the triceps using resistance band.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/3122-S93zLTG.jpg', 'videos/3122-S93zLTG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3144', 'resistance-band-seated-straight-back-row', 'Resistance バンド シーテッド Straight バック ロー', 'Resistance Band Seated Straight Back Row', 'Resistance バンド シーテッド Straight バック ローは、レジスタンスバンドを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Resistance Band Seated Straight Back Row is an effective exercise targeting the biceps using resistance band.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3144-Nu7jqFE.jpg', 'videos/3144-Nu7jqFE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0872', 'reverse-crunch', 'Reverse クランチ', 'Reverse Crunch', 'Reverse クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Reverse Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0872-nCU1Ekp.jpg', 'videos/0872-nCU1Ekp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0672', 'reverse-dip', 'Reverse ディップス', 'Reverse Dip', 'Reverse ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Reverse Dip is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0672-NZ5Qqkz.jpg', 'videos/0672-NZ5Qqkz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0673', 'reverse-grip-machine-lat-pulldown', 'Reverse Grip マシン ラットプルダウン', 'Reverse Grip Machine Lat Pulldown', 'Reverse Grip マシン ラットプルダウンは、レバレッジマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Reverse Grip Machine Lat Pulldown is an effective exercise targeting the biceps using leverage machine.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0673-ecpY0rH.jpg', 'videos/0673-ecpY0rH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0674', 'reverse-grip-pull-up', 'Reverse Grip プルアップ', 'Reverse Grip Pull-up', 'Reverse Grip プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Reverse Grip Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0674-YAk5dIw.jpg', 'videos/0674-YAk5dIw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0675', 'reverse-hyper-extension-on-stability-ball', 'Reverse Hyper エクステンション (on Stability Ball)', 'Reverse Hyper Extension (on Stability Ball)', 'Reverse Hyper エクステンション (on Stability Ball)は、スタビリティボールを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Reverse Hyper Extension (on Stability Ball) is an effective exercise targeting the hamstrings using stability ball.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0675-vM5YS2g.jpg', 'videos/0675-vM5YS2g.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1423', 'reverse-hyper-on-flat-bench', 'Reverse Hyper On Flat ベンチ', 'Reverse Hyper On Flat Bench', 'Reverse Hyper On Flat ベンチは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Reverse Hyper On Flat Bench is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1423-OrETs32.jpg', 'videos/1423-OrETs32.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3663', 'reverse-plank-with-leg-lift', 'Reverse プランク With Leg Lift', 'Reverse Plank With Leg Lift', 'Reverse プランク With Leg Liftは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Reverse Plank With Leg Lift is an effective exercise targeting the glutes using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/3663-tFToB7l.jpg', 'videos/3663-tFToB7l.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0677', 'ring-dips', 'Ring ディップス', 'Ring Dips', 'Ring ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ring Dips is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0677-ezTvXcr.jpg', 'videos/0677-ezTvXcr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2571', 'rocking-frog-stretch', 'Rocking Frog ストレッチ', 'Rocking Frog Stretch', 'Rocking Frog ストレッチは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Rocking Frog Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."]', 'images/2571-2Dk4xQV.jpg', 'videos/2571-2Dk4xQV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0678', 'rocky-pull-up-pulldown', 'Rocky プルアップ プルダウン', 'Rocky Pull-up Pulldown', 'Rocky プルアップ プルダウンは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Rocky Pull-up Pulldown is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0678-cQ19bBP.jpg', 'videos/0678-cQ19bBP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2208', 'roller-back-stretch', 'Roller バック ストレッチ', 'Roller Back Stretch', 'Roller バック ストレッチは、rollerを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Roller Back Stretch is an effective exercise targeting the hamstrings using roller.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2208-isofgzg.jpg', 'videos/2208-isofgzg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2204', 'roller-body-saw', 'Roller Body Saw', 'Roller Body Saw', 'Roller Body Sawは、rollerを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Roller Body Saw is an effective exercise targeting the shoulders using roller.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."]', 'images/2204-XeMvLgE.jpg', 'videos/2204-XeMvLgE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2205', 'roller-hip-lat-stretch', 'Roller ヒップ Lat ストレッチ', 'Roller Hip Lat Stretch', 'Roller ヒップ Lat ストレッチは、rollerを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Roller Hip Lat Stretch is an effective exercise targeting the hamstrings using roller.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2205-0L2KwtI.jpg', 'videos/2205-0L2KwtI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2202', 'roller-hip-stretch', 'Roller ヒップ ストレッチ', 'Roller Hip Stretch', 'Roller ヒップ ストレッチは、rollerを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Roller Hip Stretch is an effective exercise targeting the hamstrings using roller.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."]', 'images/2202-oMypNrz.jpg', 'videos/2202-oMypNrz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2206', 'roller-reverse-crunch', 'Roller Reverse クランチ', 'Roller Reverse Crunch', 'Roller Reverse クランチは、rollerを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Roller Reverse Crunch is an effective exercise targeting the hip flexors using roller.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."]', 'images/2206-SKXQAx3.jpg', 'videos/2206-SKXQAx3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2203', 'roller-seated-shoulder-flexor-depresor-retractor', 'Roller シーテッド Shoulder Flexor Depresor Retractor', 'Roller Seated Shoulder Flexor Depresor Retractor', 'Roller シーテッド Shoulder Flexor Depresor Retractorは、rollerを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Roller Seated Shoulder Flexor Depresor Retractor is an effective exercise targeting the deltoids using roller.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."]', 'images/2203-8coXSYU.jpg', 'videos/2203-8coXSYU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2209', 'roller-seated-single-leg-shoulder-flexor-depresor-retractor', 'Roller シーテッド シングルレッグ Shoulder Flexor Depresor Retractor', 'Roller Seated Single Leg Shoulder Flexor Depresor Retractor', 'Roller シーテッド シングルレッグ Shoulder Flexor Depresor Retractorは、rollerを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Roller Seated Single Leg Shoulder Flexor Depresor Retractor is an effective exercise targeting the deltoids using roller.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."]', 'images/2209-CjETvlw.jpg', 'videos/2209-CjETvlw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2207', 'roller-side-lat-stretch', 'Roller Side Lat ストレッチ', 'Roller Side Lat Stretch', 'Roller Side Lat ストレッチは、rollerを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Roller Side Lat Stretch is an effective exercise targeting the shoulders using roller.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/2207-c3Pfhti.jpg', 'videos/2207-c3Pfhti.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0680', 'rope-climb', 'Rope Climb', 'Rope Climb', 'Rope Climbは、ロープを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Rope Climb is an effective exercise targeting the forearms using rope.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."]', 'images/0680-yaAxcQr.jpg', 'videos/0680-yaAxcQr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0685', 'run', 'Run', 'Run', 'Runは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Run is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', 'images/0685-oLrKqDH.jpg', 'videos/0685-oLrKqDH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0684', 'run-equipment', 'Run (equipment)', 'Run (equipment)', 'Run (equipment)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Run (equipment) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', 'images/0684-y5p0H8a.jpg', 'videos/0684-y5p0H8a.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1585', 'runners-stretch', 'Runners ストレッチ', 'Runners Stretch', 'Runners ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Runners Stretch is an effective exercise targeting the calves using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', 'images/1585-0mB6wHO.jpg', 'videos/1585-0mB6wHO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0687', 'russian-twist', 'Russian ツイスト', 'Russian Twist', 'Russian ツイストは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Russian Twist is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', 'images/0687-XVDdcoj.jpg', 'videos/0687-XVDdcoj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3012', 'scapula-dips', 'Scapula ディップス', 'Scapula Dips', 'Scapula ディップスは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Scapula Dips is an effective exercise targeting the rhomboids using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3012-7xeukSt.jpg', 'videos/3012-7xeukSt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3021', 'scapula-push-up', 'Scapula プッシュアップ', 'Scapula Push-up', 'Scapula プッシュアップは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Scapula Push-up is an effective exercise targeting the triceps using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3021-jV65tKx.jpg', 'videos/3021-jV65tKx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0688', 'scapular-pull-up', 'Scapular プルアップ', 'Scapular Pull-up', 'Scapular プルアップは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Scapular Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'pull', 'upper', '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0688-uTBt1HV.jpg', 'videos/0688-uTBt1HV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3219', 'scissor-jumps-male', 'Scissor Jumps (male)', 'Scissor Jumps (male)', 'Scissor Jumps (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Scissor Jumps (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."]', 'images/3219-Eh2v5Iu.jpg', 'videos/3219-Eh2v5Iu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1390', 'seated-calf-stretch-male', 'シーテッド カーフ ストレッチ (male)', 'Seated Calf Stretch (male)', 'シーテッド カーフ ストレッチ (male)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Seated Calf Stretch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', 'images/1390-17bqEXD.jpg', 'videos/1390-17bqEXD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1424', 'seated-glute-stretch', 'シーテッド グルート ストレッチ', 'Seated Glute Stretch', 'シーテッド グルート ストレッチは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Seated Glute Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."]', 'images/1424-DeDThfG.jpg', 'videos/1424-DeDThfG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0689', 'seated-leg-raise', 'シーテッド Leg レイズ', 'Seated Leg Raise', 'シーテッド Leg レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Seated Leg Raise is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0689-Hgs6Nl1.jpg', 'videos/0689-Hgs6Nl1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0690', 'seated-lower-back-stretch', 'シーテッド Lower バック ストレッチ', 'Seated Lower Back Stretch', 'シーテッド Lower バック ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Seated Lower Back Stretch is an effective exercise targeting the glutes using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."]', 'images/0690-QFmz6ch.jpg', 'videos/0690-QFmz6ch.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2567', 'seated-piriformis-stretch', 'シーテッド Piriformis ストレッチ', 'Seated Piriformis Stretch', 'シーテッド Piriformis ストレッチは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Seated Piriformis Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', 'images/2567-QY39eBr.jpg', 'videos/2567-QY39eBr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0691', 'seated-side-crunch-wall', 'シーテッド Side クランチ (wall)', 'Seated Side Crunch (wall)', 'シーテッド Side クランチ (wall)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Seated Side Crunch (wall) is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0691-Y9hNPcN.jpg', 'videos/0691-Y9hNPcN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1587', 'seated-wide-angle-pose-sequence', 'シーテッド Wide Angle Pose Sequence', 'Seated Wide Angle Pose Sequence', 'シーテッド Wide Angle Pose Sequenceは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Seated Wide Angle Pose Sequence is an effective exercise targeting the quadriceps using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1587-HIgYKAB.jpg', 'videos/1587-HIgYKAB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0697', 'self-assisted-inverse-leg-curl', 'Self アシスト Inverse Leg カール', 'Self Assisted Inverse Leg Curl', 'Self アシスト Inverse Leg カールは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Self Assisted Inverse Leg Curl is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0697-GwYwElT.jpg', 'videos/0697-GwYwElT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1766', 'self-assisted-inverse-leg-curl-1766', 'Self アシスト Inverse Leg カール', 'Self Assisted Inverse Leg Curl', 'Self アシスト Inverse Leg カールは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Self Assisted Inverse Leg Curl is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."]', 'images/1766-ZSY3MsL.jpg', 'videos/1766-ZSY3MsL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0696', 'self-assisted-inverse-leg-curl-on-floor', 'Self アシスト Inverse Leg カール (on Floor)', 'Self Assisted Inverse Leg Curl (on Floor)', 'Self アシスト Inverse Leg カール (on Floor)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Self Assisted Inverse Leg Curl (on Floor) is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."]', 'images/0696-E4PwJqI.jpg', 'videos/0696-E4PwJqI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3222', 'semi-squat-jump-male', 'Semi スクワット Jump (male)', 'Semi Squat Jump (male)', 'Semi スクワット Jump (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Semi Squat Jump (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]', 'images/3222-6FMU51h.jpg', 'videos/3222-6FMU51h.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3656', 'short-stride-run', 'Short Stride Run', 'Short Stride Run', 'Short Stride Runは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Short Stride Run is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."]', 'images/3656-CcWEoWV.jpg', 'videos/3656-CcWEoWV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1763', 'shoulder-grip-pull-up', 'Shoulder Grip プルアップ', 'Shoulder Grip Pull-up', 'Shoulder Grip プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Shoulder Grip Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1763-YtgD7Xq.jpg', 'videos/1763-YtgD7Xq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3699', 'shoulder-tap', 'Shoulder Tap', 'Shoulder Tap', 'Shoulder Tapは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Shoulder Tap is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."]', 'images/3699-yRpV5TC.jpg', 'videos/3699-yRpV5TC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0699', 'shoulder-tap-push-up', 'Shoulder Tap プッシュアップ', 'Shoulder Tap Push-up', 'Shoulder Tap プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Shoulder Tap Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."]', 'images/0699-qEse6fe.jpg', 'videos/0699-qEse6fe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1774', 'side-bridge-hip-abduction', 'Side Bridge ヒップ Abduction', 'Side Bridge Hip Abduction', 'Side Bridge ヒップ Abductionは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Side Bridge Hip Abduction is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1774-WL4EmxJ.jpg', 'videos/1774-WL4EmxJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0705', 'side-bridge-v-2', 'Side Bridge V. 2', 'Side Bridge V. 2', 'Side Bridge V. 2は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Side Bridge V. 2 is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."]', 'images/0705-RKjH6Lt.jpg', 'videos/0705-RKjH6Lt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0709', 'side-hip-on-parallel-bars', 'Side ヒップ (on Parallel Bars)', 'Side Hip (on Parallel Bars)', 'Side ヒップ (on Parallel Bars)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Side Hip (on Parallel Bars) is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0709-jTkSc6o.jpg', 'videos/0709-jTkSc6o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0710', 'side-hip-abduction', 'Side ヒップ Abduction', 'Side Hip Abduction', 'Side ヒップ Abductionは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Side Hip Abduction is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0710-7WaDzyL.jpg', 'videos/0710-7WaDzyL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1358', 'side-lying-floor-stretch', 'Side ライイング Floor ストレッチ', 'Side Lying Floor Stretch', 'Side ライイング Floor ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Side Lying Floor Stretch is an effective exercise targeting the obliques using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."]', 'images/1358-jDOKRM5.jpg', 'videos/1358-jDOKRM5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3667', 'side-lying-hip-adduction-male', 'Side ライイング ヒップ Adduction (male)', 'Side Lying Hip Adduction (male)', 'Side ライイング ヒップ Adduction (male)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Side Lying Hip Adduction (male) is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/3667-c8f5cSY.jpg', 'videos/3667-c8f5cSY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1775', 'side-plank-hip-adduction', 'Side プランク ヒップ Adduction', 'Side Plank Hip Adduction', 'Side プランク ヒップ Adductionは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Side Plank Hip Adduction is an effective exercise targeting the obliques using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1775-VO2qeJg.jpg', 'videos/1775-VO2qeJg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0716', 'side-push-neck-stretch', 'Side Push ネック ストレッチ', 'Side Push Neck Stretch', 'Side Push ネック ストレッチは、自重を使用した肩をターゲットとする効果的なトレーニング種目です。', 'Side Push Neck Stretch is an effective exercise targeting the trapezius using body weight.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."]', 'images/0716-oQRJYkC.jpg', 'videos/0716-oQRJYkC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0717', 'side-push-up', 'Side プッシュアップ', 'Side Push-up', 'Side プッシュアップは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Side Push-up is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0717-wpbD28t.jpg', 'videos/0717-wpbD28t.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0721', 'side-wrist-pull-stretch', 'Side リスト Pull ストレッチ', 'Side Wrist Pull Stretch', 'Side リスト Pull ストレッチは、自重を使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Side Wrist Pull Stretch is an effective exercise targeting the wrists using body weight.', 'mg-forearms', 'Beginner', 'compound', 'pull', 'upper', '["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', 'images/0721-UtmIqcI.jpg', 'videos/0721-UtmIqcI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0720', 'side-to-side-chin', 'Side-to-side チンアップ', 'Side-to-side Chin', 'Side-to-side チンアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Side-to-side Chin is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0720-isAAZWA.jpg', 'videos/0720-isAAZWA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3213', 'side-to-side-toe-touch-male', 'Side-to-side Toe Touch (male)', 'Side-to-side Toe Touch (male)', 'Side-to-side Toe Touch (male)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Side-to-side Toe Touch (male) is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."]', 'images/3213-WCAvOfC.jpg', 'videos/3213-WCAvOfC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0725', 'single-arm-push-up', 'シングルアーム プッシュアップ', 'Single Arm Push-up', 'シングルアーム プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Single Arm Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."]', 'images/0725-MUic5zN.jpg', 'videos/0725-MUic5zN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3645', 'single-leg-bridge-with-outstretched-leg', 'シングルレッグ Bridge With Outstretched Leg', 'Single Leg Bridge With Outstretched Leg', 'シングルレッグ Bridge With Outstretched Legは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Single Leg Bridge With Outstretched Leg is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/3645-rmEukuS.jpg', 'videos/3645-rmEukuS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0727', 'single-leg-calf-raise-on-a-dumbbell', 'シングルレッグ カーフ レイズ (on A ダンベル)', 'Single Leg Calf Raise (on A Dumbbell)', 'シングルレッグ カーフ レイズ (on A ダンベル)は、ダンベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Single Leg Calf Raise (on A Dumbbell) is an effective exercise targeting the ankles using dumbbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."]', 'images/0727-fKZgDEO.jpg', 'videos/0727-fKZgDEO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0730', 'single-leg-platform-slide', 'シングルレッグ Platform Slide', 'Single Leg Platform Slide', 'シングルレッグ Platform Slideは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Single Leg Platform Slide is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."]', 'images/0730-LNE3wfo.jpg', 'videos/0730-LNE3wfo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1759', 'single-leg-squat-pistol-male', 'シングルレッグ スクワット (pistol) Male', 'Single Leg Squat (pistol) Male', 'シングルレッグ スクワット (pistol) Maleは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Single Leg Squat (pistol) Male is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/1759-nqs5HGV.jpg', 'videos/1759-nqs5HGV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1489', 'sissy-squat', 'Sissy スクワット', 'Sissy Squat', 'Sissy スクワットは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sissy Squat is an effective exercise targeting the calves using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1489-xdYPUtE.jpg', 'videos/1489-xdYPUtE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0735', 'sit-up-v-2', 'Sit-up V. 2', 'Sit-up V. 2', 'Sit-up V. 2は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Sit-up V. 2 is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0735-Bn6TXyO.jpg', 'videos/0735-Bn6TXyO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3679', 'sit-up-with-arms-on-chest', 'Sit-up With Arms On チェスト', 'Sit-up With Arms On Chest', 'Sit-up With Arms On チェストは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Sit-up With Arms On Chest is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3679-6ZCiYWQ.jpg', 'videos/3679-6ZCiYWQ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3361', 'skater-hops', 'Skater Hops', 'Skater Hops', 'Skater Hopsは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Skater Hops is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."]', 'images/3361-zfNHMN9.jpg', 'videos/3361-zfNHMN9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2142', 'ski-ergometer', 'Ski Ergometer', 'Ski Ergometer', 'Ski Ergometerは、skierg machineを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Ski Ergometer is an effective exercise targeting the shoulders using skierg machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/2142-vpQaQkH.jpg', 'videos/2142-vpQaQkH.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3671', 'ski-step', 'Ski Step', 'Ski Step', 'Ski Stepは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Ski Step is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."]', 'images/3671-5MRH8H2.jpg', 'videos/3671-5MRH8H2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3304', 'skin-the-cat', 'Skin The Cat', 'Skin The Cat', 'Skin The Catは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Skin The Cat is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."]', 'images/3304-MSfvriJ.jpg', 'videos/3304-MSfvriJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1425', 'sled-45-degrees-one-leg-press', 'Sled 45 Degrees One Leg プレス', 'Sled 45 Degrees One Leg Press', 'Sled 45 Degrees One Leg プレスは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled 45 Degrees One Leg Press is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', 'images/1425-WWD6FzI.jpg', 'videos/1425-WWD6FzI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0738', 'sled-45-calf-press', 'Sled 45в° カーフ プレス', 'Sled 45в° Calf Press', 'Sled 45в° カーフ プレスは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sled 45в° Calf Press is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0738-qCNVnaU.jpg', 'videos/0738-qCNVnaU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0739', 'sled-45-leg-press', 'Sled 45в° Leg プレス', 'Sled 45в° Leg Press', 'Sled 45в° Leg プレスは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled 45в° Leg Press is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."]', 'images/0739-10Z2DXU.jpg', 'videos/0739-10Z2DXU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1464', 'sled-45-leg-press-back-pov', 'Sled 45в° Leg プレス (バック Pov)', 'Sled 45в° Leg Press (back Pov)', 'Sled 45в° Leg プレス (バック Pov)は、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled 45в° Leg Press (back Pov) is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."]', 'images/1464-yn2lLSI.jpg', 'videos/1464-yn2lLSI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1463', 'sled-45-leg-press-side-pov', 'Sled 45° Leg プレス (side Pov)', 'Sled 45° Leg Press (side Pov)', 'Sled 45° Leg プレス (side Pov)は、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled 45° Leg Press (side Pov) is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."]', 'images/1463-2Qh2J1e.jpg', 'videos/1463-2Qh2J1e.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0740', 'sled-45-leg-wide-press', 'Sled 45в° Leg Wide プレス', 'Sled 45в° Leg Wide Press', 'Sled 45в° Leg Wide プレスは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled 45в° Leg Wide Press is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0740-tj41Nu6.jpg', 'videos/0740-tj41Nu6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1391', 'sled-calf-press-on-leg-press', 'Sled カーフ プレス On Leg プレス', 'Sled Calf Press On Leg Press', 'Sled カーフ プレス On Leg プレスは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sled Calf Press On Leg Press is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."]', 'images/1391-ykHcWme.jpg', 'videos/1391-ykHcWme.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0741', 'sled-closer-hack-squat', 'Sled Closer ハック スクワット', 'Sled Closer Hack Squat', 'Sled Closer ハック スクワットは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled Closer Hack Squat is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0741-gf3ZjB9.jpg', 'videos/0741-gf3ZjB9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0742', 'sled-forward-angled-calf-raise', 'Sled Forward Angled カーフ レイズ', 'Sled Forward Angled Calf Raise', 'Sled Forward Angled カーフ レイズは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sled Forward Angled Calf Raise is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0742-XDOiFns.jpg', 'videos/0742-XDOiFns.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0743', 'sled-hack-squat', 'Sled ハック スクワット', 'Sled Hack Squat', 'Sled ハック スクワットは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled Hack Squat is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0743-Qa55kX1.jpg', 'videos/0743-Qa55kX1.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2334', 'sled-lying-calf-press', 'Sled ライイング カーフ プレス', 'Sled Lying Calf Press', 'Sled ライイング カーフ プレスは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sled Lying Calf Press is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2334-g376LuL.jpg', 'videos/2334-g376LuL.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0744', 'sled-lying-squat', 'Sled ライイング スクワット', 'Sled Lying Squat', 'Sled ライイング スクワットは、sled machineを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Sled Lying Squat is an effective exercise targeting the quadriceps using sled machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."]', 'images/0744-9n2149Z.jpg', 'videos/0744-9n2149Z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1392', 'sled-one-leg-calf-press-on-leg-press', 'Sled One Leg カーフ プレス On Leg プレス', 'Sled One Leg Calf Press On Leg Press', 'Sled One Leg カーフ プレス On Leg プレスは、sled machineを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Sled One Leg Calf Press On Leg Press is an effective exercise targeting the hamstrings using sled machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."]', 'images/1392-u0pLNgz.jpg', 'videos/1392-u0pLNgz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1496', 'sledge-hammer', 'Sledge ハンマー', 'Sledge Hammer', 'Sledge ハンマーは、hammerを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Sledge Hammer is an effective exercise targeting the forearms using hammer.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."]', 'images/1496-REXmfVC.jpg', 'videos/1496-REXmfVC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0746', 'smith-back-shrug', 'スミス バック シュラッグ', 'Smith Back Shrug', 'スミス バック シュラッグは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Back Shrug is an effective exercise targeting the shoulders using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0746-MzNnwx9.jpg', 'videos/0746-MzNnwx9.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0747', 'smith-behind-neck-press', 'スミス Behind ネック プレス', 'Smith Behind Neck Press', 'スミス Behind ネック プレスは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Behind Neck Press is an effective exercise targeting the triceps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0747-Gpn4ADc.jpg', 'videos/0747-Gpn4ADc.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0748', 'smith-bench-press', 'スミス ベンチプレス', 'Smith Bench Press', 'スミス ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Bench Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0748-trqKQv2.jpg', 'videos/0748-trqKQv2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0749', 'smith-bent-knee-good-morning', 'スミス Bent Knee Good Morning', 'Smith Bent Knee Good Morning', 'スミス Bent Knee Good Morningは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Bent Knee Good Morning is an effective exercise targeting the hamstrings using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0749-1bQkKZK.jpg', 'videos/0749-1bQkKZK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1359', 'smith-bent-over-row', 'スミス Bent Over ロー', 'Smith Bent Over Row', 'スミス Bent Over ローは、スミスマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Smith Bent Over Row is an effective exercise targeting the biceps using smith machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1359-ZX9UZmj.jpg', 'videos/1359-ZX9UZmj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0750', 'smith-chair-squat', 'スミス Chair スクワット', 'Smith Chair Squat', 'スミス Chair スクワットは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Chair Squat is an effective exercise targeting the glutes using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0750-Gu2rNJd.jpg', 'videos/0750-Gu2rNJd.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0751', 'smith-close-grip-bench-press', 'スミス ナローグリップ ベンチプレス', 'Smith Close-grip Bench Press', 'スミス ナローグリップ ベンチプレスは、スミスマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Smith Close-grip Bench Press is an effective exercise targeting the chest using smith machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0751-WcHl7ru.jpg', 'videos/0751-WcHl7ru.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0752', 'smith-deadlift', 'スミス デッドリフト', 'Smith Deadlift', 'スミス デッドリフトは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Deadlift is an effective exercise targeting the hamstrings using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."]', 'images/0752-UfePqpx.jpg', 'videos/0752-UfePqpx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0753', 'smith-decline-bench-press', 'スミス デクライン ベンチプレス', 'Smith Decline Bench Press', 'スミス デクライン ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Decline Bench Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0753-ETZfAbZ.jpg', 'videos/0753-ETZfAbZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0754', 'smith-decline-reverse-grip-press', 'スミス デクライン リバースグリップ プレス', 'Smith Decline Reverse-grip Press', 'スミス デクライン リバースグリップ プレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Decline Reverse-grip Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0754-MY9P1WA.jpg', 'videos/0754-MY9P1WA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1433', 'smith-front-squat-clean-grip', 'スミス フロント スクワット (clean Grip)', 'Smith Front Squat (clean Grip)', 'スミス フロント スクワット (clean Grip)は、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Front Squat (clean Grip) is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1433-lFhb2Rw.jpg', 'videos/1433-lFhb2Rw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3281', 'smith-full-squat', 'スミス Full スクワット', 'Smith Full Squat', 'スミス Full スクワットは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Full Squat is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3281-NNoHCEA.jpg', 'videos/3281-NNoHCEA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0755', 'smith-hack-squat', 'スミス ハック スクワット', 'Smith Hack Squat', 'スミス ハック スクワットは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Hack Squat is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0755-ZuPXtCK.jpg', 'videos/0755-ZuPXtCK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0756', 'smith-hip-raise', 'スミス ヒップ レイズ', 'Smith Hip Raise', 'スミス ヒップ レイズは、スミスマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Smith Hip Raise is an effective exercise targeting the glutes using smith machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0756-CqhoytW.jpg', 'videos/0756-CqhoytW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0757', 'smith-incline-bench-press', 'スミス インクライン ベンチプレス', 'Smith Incline Bench Press', 'スミス インクライン ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Incline Bench Press is an effective exercise targeting the shoulders using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0757-5v7KYld.jpg', 'videos/0757-5v7KYld.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0758', 'smith-incline-reverse-grip-press', 'スミス インクライン リバースグリップ プレス', 'Smith Incline Reverse-grip Press', 'スミス インクライン リバースグリップ プレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Incline Reverse-grip Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/0758-78VqWQK.jpg', 'videos/0758-78VqWQK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0759', 'smith-incline-shoulder-raises', 'スミス インクライン Shoulder Raises', 'Smith Incline Shoulder Raises', 'スミス インクライン Shoulder Raisesは、スミスマシンを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Smith Incline Shoulder Raises is an effective exercise targeting the deltoids using smith machine.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0759-ayAHcEm.jpg', 'videos/0759-ayAHcEm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0760', 'smith-leg-press', 'スミス Leg プレス', 'Smith Leg Press', 'スミス Leg プレスは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Leg Press is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."]', 'images/0760-7zdxRTl.jpg', 'videos/0760-7zdxRTl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1434', 'smith-low-bar-squat', 'スミス Low Bar スクワット', 'Smith Low Bar Squat', 'スミス Low Bar スクワットは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Low Bar Squat is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', 'images/1434-RGLscZM.jpg', 'videos/1434-RGLscZM.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1683', 'smith-machine-bicep-curl', 'スミス マシン Bicep カール', 'Smith Machine Bicep Curl', 'スミス マシン Bicep カールは、スミスマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Smith Machine Bicep Curl is an effective exercise targeting the forearms using smith machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1683-zILLZ98.jpg', 'videos/1683-zILLZ98.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1625', 'smith-machine-decline-close-grip-bench-press', 'スミス マシン デクライン Close Grip ベンチプレス', 'Smith Machine Decline Close Grip Bench Press', 'スミス マシン デクライン Close Grip ベンチプレスは、スミスマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Smith Machine Decline Close Grip Bench Press is an effective exercise targeting the chest using smith machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1625-yB9SvIF.jpg', 'videos/1625-yB9SvIF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1752', 'smith-machine-incline-tricep-extension', 'スミス マシン インクライン Tricep エクステンション', 'Smith Machine Incline Tricep Extension', 'スミス マシン インクライン Tricep エクステンションは、スミスマシンを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Smith Machine Incline Tricep Extension is an effective exercise targeting the shoulders using smith machine.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1752-o8aOcrz.jpg', 'videos/1752-o8aOcrz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1626', 'smith-machine-reverse-decline-close-grip-bench-press', 'スミス マシン Reverse デクライン Close Grip ベンチプレス', 'Smith Machine Reverse Decline Close Grip Bench Press', 'スミス マシン Reverse デクライン Close Grip ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Machine Reverse Decline Close Grip Bench Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1626-QyO6Uma.jpg', 'videos/1626-QyO6Uma.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0761', 'smith-narrow-row', 'スミス Narrow ロー', 'Smith Narrow Row', 'スミス Narrow ローは、スミスマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Smith Narrow Row is an effective exercise targeting the biceps using smith machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0761-JGKowMS.jpg', 'videos/0761-JGKowMS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1360', 'smith-one-arm-row', 'スミス ワンハンド ロー', 'Smith One Arm Row', 'スミス ワンハンド ローは、スミスマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Smith One Arm Row is an effective exercise targeting the biceps using smith machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', 'images/1360-Q4DSJPC.jpg', 'videos/1360-Q4DSJPC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1393', 'smith-one-leg-floor-calf-raise', 'スミス One Leg Floor カーフ レイズ', 'Smith One Leg Floor Calf Raise', 'スミス One Leg Floor カーフ レイズは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith One Leg Floor Calf Raise is an effective exercise targeting the hamstrings using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1393-9GXrTE6.jpg', 'videos/1393-9GXrTE6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0762', 'smith-rear-delt-row', 'スミス リア Delt ロー', 'Smith Rear Delt Row', 'スミス リア Delt ローは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Rear Delt Row is an effective exercise targeting the trapezius using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0762-nFUwqG6.jpg', 'videos/0762-nFUwqG6.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0763', 'smith-reverse-calf-raises', 'スミス Reverse カーフ Raises', 'Smith Reverse Calf Raises', 'スミス Reverse カーフ Raisesは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Reverse Calf Raises is an effective exercise targeting the hamstrings using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0763-ywaNfuh.jpg', 'videos/0763-ywaNfuh.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1394', 'smith-reverse-calf-raises-1394', 'スミス Reverse カーフ Raises', 'Smith Reverse Calf Raises', 'スミス Reverse カーフ Raisesは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Reverse Calf Raises is an effective exercise targeting the hamstrings using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1394-Lsqrgh4.jpg', 'videos/1394-Lsqrgh4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1361', 'smith-reverse-grip-bent-over-row', 'スミス Reverse Grip Bent Over ロー', 'Smith Reverse Grip Bent Over Row', 'スミス Reverse Grip Bent Over ローは、スミスマシンを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Smith Reverse Grip Bent Over Row is an effective exercise targeting the biceps using smith machine.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1361-aaxA3cm.jpg', 'videos/1361-aaxA3cm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0764', 'smith-reverse-grip-press', 'スミス リバースグリップ プレス', 'Smith Reverse-grip Press', 'スミス リバースグリップ プレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Reverse-grip Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0764-zK8Fu1W.jpg', 'videos/0764-zK8Fu1W.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1395', 'smith-seated-one-leg-calf-raise', 'スミス シーテッド One Leg カーフ レイズ', 'Smith Seated One Leg Calf Raise', 'スミス シーテッド One Leg カーフ レイズは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Seated One Leg Calf Raise is an effective exercise targeting the hamstrings using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/1395-0S75mYG.jpg', 'videos/1395-0S75mYG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0765', 'smith-seated-shoulder-press', 'スミス シーテッド Shoulder プレス', 'Smith Seated Shoulder Press', 'スミス シーテッド Shoulder プレスは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Seated Shoulder Press is an effective exercise targeting the triceps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0765-xUwnBMT.jpg', 'videos/0765-xUwnBMT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1426', 'smith-seated-wrist-curl', 'スミス シーテッド リスト カール', 'Smith Seated Wrist Curl', 'スミス シーテッド リスト カールは、スミスマシンを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Smith Seated Wrist Curl is an effective exercise targeting the biceps using smith machine.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1426-B6dAO1t.jpg', 'videos/1426-B6dAO1t.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0766', 'smith-shoulder-press', 'スミス Shoulder プレス', 'Smith Shoulder Press', 'スミス Shoulder プレスは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Shoulder Press is an effective exercise targeting the triceps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0766-903mzG8.jpg', 'videos/0766-903mzG8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0767', 'smith-shrug', 'スミス シュラッグ', 'Smith Shrug', 'スミス シュラッグは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Shrug is an effective exercise targeting the shoulders using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0767-OUQ0ZyW.jpg', 'videos/0767-OUQ0ZyW.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0768', 'smith-single-leg-split-squat', 'スミス シングルレッグ Split スクワット', 'Smith Single Leg Split Squat', 'スミス シングルレッグ Split スクワットは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Single Leg Split Squat is an effective exercise targeting the glutes using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0768-wWFspEi.jpg', 'videos/0768-wWFspEi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0769', 'smith-sprint-lunge', 'スミス Sprint ランジ', 'Smith Sprint Lunge', 'スミス Sprint ランジは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Sprint Lunge is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."]', 'images/0769-HsjbB1z.jpg', 'videos/0769-HsjbB1z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0770', 'smith-squat', 'スミス スクワット', 'Smith Squat', 'スミス スクワットは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Squat is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0770-jFtipLl.jpg', 'videos/0770-jFtipLl.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0771', 'smith-standing-back-wrist-curl', 'スミス スタンディング バック リスト カール', 'Smith Standing Back Wrist Curl', 'スミス スタンディング バック リスト カールは、スミスマシンを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Smith Standing Back Wrist Curl is an effective exercise targeting the biceps using smith machine.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0771-hfmQ0Tz.jpg', 'videos/0771-hfmQ0Tz.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0772', 'smith-standing-behind-head-military-press', 'スミス スタンディング Behind Head Military プレス', 'Smith Standing Behind Head Military Press', 'スミス スタンディング Behind Head Military プレスは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Standing Behind Head Military Press is an effective exercise targeting the triceps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0772-ht8xDrP.jpg', 'videos/0772-ht8xDrP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0773', 'smith-standing-leg-calf-raise', 'スミス スタンディング Leg カーフ レイズ', 'Smith Standing Leg Calf Raise', 'スミス スタンディング Leg カーフ レイズは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Standing Leg Calf Raise is an effective exercise targeting the hamstrings using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0773-6MaEjVA.jpg', 'videos/0773-6MaEjVA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0774', 'smith-standing-military-press', 'スミス スタンディング Military プレス', 'Smith Standing Military Press', 'スミス スタンディング Military プレスは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Standing Military Press is an effective exercise targeting the triceps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."]', 'images/0774-jjUPrze.jpg', 'videos/0774-jjUPrze.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3142', 'smith-sumo-squat', 'スミス Sumo スクワット', 'Smith Sumo Squat', 'スミス Sumo スクワットは、スミスマシンを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Smith Sumo Squat is an effective exercise targeting the quadriceps using smith machine.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3142-dzz6BiV.jpg', 'videos/3142-dzz6BiV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1396', 'smith-toe-raise', 'スミス Toe レイズ', 'Smith Toe Raise', 'スミス Toe レイズは、スミスマシンを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Smith Toe Raise is an effective exercise targeting the ankles using smith machine.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1396-Y4QlY8z.jpg', 'videos/1396-Y4QlY8z.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0775', 'smith-upright-row', 'スミス Upright ロー', 'Smith Upright Row', 'スミス Upright ローは、スミスマシンを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Smith Upright Row is an effective exercise targeting the traps using smith machine.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0775-1DN3iz4.jpg', 'videos/0775-1DN3iz4.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1308', 'smith-wide-grip-bench-press', 'スミス Wide Grip ベンチプレス', 'Smith Wide Grip Bench Press', 'スミス Wide Grip ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Wide Grip Bench Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1308-zoOvPcx.jpg', 'videos/1308-zoOvPcx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1309', 'smith-wide-grip-decline-bench-press', 'スミス Wide Grip デクライン ベンチプレス', 'Smith Wide Grip Decline Bench Press', 'スミス Wide Grip デクライン ベンチプレスは、スミスマシンを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Smith Wide Grip Decline Bench Press is an effective exercise targeting the triceps using smith machine.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/1309-wi2H9QX.jpg', 'videos/1309-wi2H9QX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0776', 'snatch-pull', 'Snatch Pull', 'Snatch Pull', 'Snatch Pullは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Snatch Pull is an effective exercise targeting the hamstrings using barbell.', 'mg-legs', 'Beginner', 'compound', 'pull', 'lower', '["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', 'images/0776-dG5Smob.jpg', 'videos/0776-dG5Smob.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0777', 'spell-caster', 'Spell Caster', 'Spell Caster', 'Spell Casterは、ダンベルを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Spell Caster is an effective exercise targeting the obliques using dumbbell.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0777-p9cCe2r.jpg', 'videos/0777-p9cCe2r.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1362', 'sphinx', 'Sphinx', 'Sphinx', 'Sphinxは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Sphinx is an effective exercise targeting the glutes using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1362-DIVyqrU.jpg', 'videos/1362-DIVyqrU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0778', 'spider-crawl-push-up', 'Spider Crawl Push Up', 'Spider Crawl Push Up', 'Spider Crawl Push Upは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Spider Crawl Push Up is an effective exercise targeting the core using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]', 'images/0778-P9GFBME.jpg', 'videos/0778-P9GFBME.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1363', 'spine-stretch', 'Spine ストレッチ', 'Spine Stretch', 'Spine ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Spine Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1363-JbC2iaV.jpg', 'videos/1363-JbC2iaV.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2329', 'spine-twist', 'Spine ツイスト', 'Spine Twist', 'Spine ツイストは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Spine Twist is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."]', 'images/2329-2jl9K55.jpg', 'videos/2329-2jl9K55.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2368', 'split-squats', 'Split Squats', 'Split Squats', 'Split Squatsは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Split Squats is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', 'images/2368-9E25EOx.jpg', 'videos/2368-9E25EOx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0786', 'squat-jerk', 'スクワット Jerk', 'Squat Jerk', 'スクワット Jerkは、バーベルを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Squat Jerk is an effective exercise targeting the glutes using barbell.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."]', 'images/0786-IMRsOCn.jpg', 'videos/0786-IMRsOCn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1705', 'squat-on-bosu-ball', 'スクワット On Bosu Ball', 'Squat On Bosu Ball', 'スクワット On Bosu Ballは、ボスボールを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Squat On Bosu Ball is an effective exercise targeting the glutes using bosu ball.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1705-T2fA5Ir.jpg', 'videos/1705-T2fA5Ir.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1685', 'squat-to-overhead-reach', 'スクワット To オーバーヘッド Reach', 'Squat To Overhead Reach', 'スクワット To オーバーヘッド Reachは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Squat To Overhead Reach is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."]', 'images/1685-QChZi3x.jpg', 'videos/1685-QChZi3x.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1686', 'squat-to-overhead-reach-with-twist', 'スクワット To オーバーヘッド Reach With ツイスト', 'Squat To Overhead Reach With Twist', 'スクワット To オーバーヘッド Reach With ツイストは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Squat To Overhead Reach With Twist is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."]', 'images/1686-5BZHW9s.jpg', 'videos/1686-5BZHW9s.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2297', 'stability-ball-crunch-full-range-hands-behind-head', 'Stability Ball クランチ (full Range Hands Behind Head)', 'Stability Ball Crunch (full Range Hands Behind Head)', 'Stability Ball クランチ (full Range Hands Behind Head)は、スタビリティボールを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Stability Ball Crunch (full Range Hands Behind Head) is an effective exercise targeting the hip flexors using stability ball.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."]', 'images/2297-Gn5FwYT.jpg', 'videos/2297-Gn5FwYT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3291', 'stalder-press', 'Stalder プレス', 'Stalder Press', 'Stalder プレスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Stalder Press is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."]', 'images/3291-zd4P4B2.jpg', 'videos/3291-zd4P4B2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3669', 'standing-archer', 'スタンディング Archer', 'Standing Archer', 'スタンディング Archerは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Standing Archer is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."]', 'images/3669-JF8AkMX.jpg', 'videos/3669-JF8AkMX.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0788', 'standing-behind-neck-press', 'スタンディング Behind ネック プレス', 'Standing Behind Neck Press', 'スタンディング Behind ネック プレスは、バーベルを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Standing Behind Neck Press is an effective exercise targeting the triceps using barbell.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0788-xDh0lJr.jpg', 'videos/0788-xDh0lJr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1490', 'standing-calf-raise-on-a-staircase', 'スタンディング カーフ レイズ (on A Staircase)', 'Standing Calf Raise (on A Staircase)', 'スタンディング カーフ レイズ (on A Staircase)は、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Standing Calf Raise (on A Staircase) is an effective exercise targeting the ankles using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1490-6HmFgmx.jpg', 'videos/1490-6HmFgmx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1397', 'standing-calves', 'スタンディング カーフ', 'Standing Calves', 'スタンディング カーフは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Standing Calves is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1397-XIHEoCG.jpg', 'videos/1397-XIHEoCG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1398', 'standing-calves-calf-stretch', 'スタンディング カーフ カーフ ストレッチ', 'Standing Calves Calf Stretch', 'スタンディング カーフ カーフ ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Standing Calves Calf Stretch is an effective exercise targeting the hamstrings using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing a wall or sturdy object, about an arm''s length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."]', 'images/1398-qOKcgVP.jpg', 'videos/1398-qOKcgVP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1599', 'standing-hamstring-and-calf-stretch-with-strap', 'スタンディング Hamstring And カーフ ストレッチ With Strap', 'Standing Hamstring And Calf Stretch With Strap', 'スタンディング Hamstring And カーフ ストレッチ With Strapは、ロープを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Standing Hamstring And Calf Stretch With Strap is an effective exercise targeting the calves using rope.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."]', 'images/1599-xTjr103.jpg', 'videos/1599-xTjr103.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0794', 'standing-lateral-stretch', 'スタンディング サイド ストレッチ', 'Standing Lateral Stretch', 'スタンディング サイド ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Standing Lateral Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."]', 'images/0794-1jXLYEw.jpg', 'videos/0794-1jXLYEw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1364', 'standing-pelvic-tilt', 'スタンディング Pelvic Tilt', 'Standing Pelvic Tilt', 'スタンディング Pelvic Tiltは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Standing Pelvic Tilt is an effective exercise targeting the abdominals using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1364-cuKYxhu.jpg', 'videos/1364-cuKYxhu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0795', 'standing-single-leg-curl', 'スタンディング シングルレッグ カール', 'Standing Single Leg Curl', 'スタンディング シングルレッグ カールは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Standing Single Leg Curl is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0795-C5jncD2.jpg', 'videos/0795-C5jncD2.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0796', 'standing-wheel-rollerout', 'スタンディング ホイール Rollerout', 'Standing Wheel Rollerout', 'スタンディング ホイール Rolleroutは、ホイールローラーを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Standing Wheel Rollerout is an effective exercise targeting the lower back using wheel roller.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', 'images/0796-KtRomty.jpg', 'videos/0796-KtRomty.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3223', 'star-jump-male', 'Star Jump (male)', 'Star Jump (male)', 'Star Jump (male)は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Star Jump (male) is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."]', 'images/3223-HtfCpfi.jpg', 'videos/3223-HtfCpfi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2138', 'stationary-bike-run-v-3', 'Stationary Bike Run V. 3', 'Stationary Bike Run V. 3', 'Stationary Bike Run V. 3は、stationary bikeを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Stationary Bike Run V. 3 is an effective exercise targeting the quadriceps using stationary bike.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."]', 'images/2138-H1PESYI.jpg', 'videos/2138-H1PESYI.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0798', 'stationary-bike-walk', 'Stationary Bike Walk', 'Stationary Bike Walk', 'Stationary Bike Walkは、レバレッジマシンを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Stationary Bike Walk is an effective exercise targeting the quadriceps using leverage machine.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."]', 'images/0798-a8VDgLw.jpg', 'videos/0798-a8VDgLw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3314', 'straddle-maltese', 'Straddle Maltese', 'Straddle Maltese', 'Straddle Malteseは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Straddle Maltese is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3314-HfqciZF.jpg', 'videos/3314-HfqciZF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3298', 'straddle-planche', 'Straddle Planche', 'Straddle Planche', 'Straddle Plancheは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Straddle Planche is an effective exercise targeting the shoulders using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/3298-BL3GHeY.jpg', 'videos/3298-BL3GHeY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1427', 'straight-leg-outer-hip-abductor', 'Straight Leg Outer ヒップ Abductor', 'Straight Leg Outer Hip Abductor', 'Straight Leg Outer ヒップ Abductorは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Straight Leg Outer Hip Abductor is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/1427-mQ1tBXn.jpg', 'videos/1427-mQ1tBXn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0803', 'superman-push-up', 'Superman プッシュアップ', 'Superman Push-up', 'Superman プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Superman Push-up is an effective exercise targeting the core using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]', 'images/0803-4GqRrAk.jpg', 'videos/0803-4GqRrAk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0805', 'suspended-abdominal-fallout', 'Suspended アブドミナル Fallout', 'Suspended Abdominal Fallout', 'Suspended アブドミナル Falloutは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Suspended Abdominal Fallout is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0805-X3TCNEU.jpg', 'videos/0805-X3TCNEU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0806', 'suspended-push-up', 'Suspended プッシュアップ', 'Suspended Push-up', 'Suspended プッシュアップは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Suspended Push-up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0806-IaGQCrC.jpg', 'videos/0806-IaGQCrC.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0807', 'suspended-reverse-crunch', 'Suspended Reverse クランチ', 'Suspended Reverse Crunch', 'Suspended Reverse クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Suspended Reverse Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0807-R1WYG5D.jpg', 'videos/0807-R1WYG5D.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0808', 'suspended-row', 'Suspended ロー', 'Suspended Row', 'Suspended ローは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Suspended Row is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0808-4OaumBr.jpg', 'videos/0808-4OaumBr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0809', 'suspended-split-squat', 'Suspended Split スクワット', 'Suspended Split Squat', 'Suspended Split スクワットは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'Suspended Split Squat is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', 'images/0809-QpXqiq8.jpg', 'videos/0809-QpXqiq8.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3433', 'swimmer-kicks-v-2-male', 'Swimmer Kicks V. 2 (male)', 'Swimmer Kicks V. 2 (male)', 'Swimmer Kicks V. 2 (male)は、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Swimmer Kicks V. 2 (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."]', 'images/3433-SP3hUez.jpg', 'videos/3433-SP3hUez.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3318', 'swing-360', 'Swing 360', 'Swing 360', 'Swing 360は、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Swing 360 is an effective exercise targeting the shoulders using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."]', 'images/3318-tnaj0mT.jpg', 'videos/3318-tnaj0mT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1753', 'three-bench-dip', 'Three ベンチ ディップス', 'Three Bench Dip', 'Three ベンチ ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Three Bench Dip is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1753-DQ0cqkT.jpg', 'videos/1753-DQ0cqkT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2459', 'tire-flip', 'Tire Flip', 'Tire Flip', 'Tire Flipは、tireを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Tire Flip is an effective exercise targeting the hamstrings using tire.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."]', 'images/2459-oZjMu1t.jpg', 'videos/2459-oZjMu1t.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0811', 'trap-bar-deadlift', 'トラップ Bar デッドリフト', 'Trap Bar Deadlift', 'トラップ Bar デッドリフトは、trap barを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Trap Bar Deadlift is an effective exercise targeting the hamstrings using trap bar.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."]', 'images/0811-jQGwmxN.jpg', 'videos/0811-jQGwmxN.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0814', 'triceps-dip', 'トライセップス ディップス', 'Triceps Dip', 'トライセップス ディップスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Dip is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0814-X6C6i5Y.jpg', 'videos/0814-X6C6i5Y.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0812', 'triceps-dip-bench-leg', 'トライセップス ディップス (ベンチ Leg)', 'Triceps Dip (bench Leg)', 'トライセップス ディップス (ベンチ Leg)は、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Dip (bench Leg) is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0812-VuoerH0.jpg', 'videos/0812-VuoerH0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0813', 'triceps-dip-between-benches', 'トライセップス ディップス (between Benches)', 'Triceps Dip (between Benches)', 'トライセップス ディップス (between Benches)は、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Dip (between Benches) is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0813-Wgbn9qo.jpg', 'videos/0813-Wgbn9qo.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0815', 'triceps-dips-floor', 'トライセップス ディップス Floor', 'Triceps Dips Floor', 'トライセップス ディップス Floorは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Dips Floor is an effective exercise targeting the chest using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."]', 'images/0815-7aVz15j.jpg', 'videos/0815-7aVz15j.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0816', 'triceps-press', 'トライセップス プレス', 'Triceps Press', 'トライセップス プレスは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Press is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/0816-fSrPP6B.jpg', 'videos/0816-fSrPP6B.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0817', 'triceps-stretch', 'トライセップス ストレッチ', 'Triceps Stretch', 'トライセップス ストレッチは、自重を使用した腕をターゲットとする効果的なトレーニング種目です。', 'Triceps Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."]', 'images/0817-uOV3Itw.jpg', 'videos/0817-uOV3Itw.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0871', 'tuck-crunch', 'Tuck クランチ', 'Tuck Crunch', 'Tuck クランチは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Tuck Crunch is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0871-BMMolZ3.jpg', 'videos/0871-BMMolZ3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0818', 'twin-handle-parallel-grip-lat-pulldown', 'Twin Handle Parallel Grip ラットプルダウン', 'Twin Handle Parallel Grip Lat Pulldown', 'Twin Handle Parallel Grip ラットプルダウンは、ケーブルを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Twin Handle Parallel Grip Lat Pulldown is an effective exercise targeting the biceps using cable.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0818-rkg41Fb.jpg', 'videos/0818-rkg41Fb.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1466', 'twist-hip-lift', 'ツイスト ヒップ Lift', 'Twist Hip Lift', 'ツイスト ヒップ Liftは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Twist Hip Lift is an effective exercise targeting the obliques using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', 'images/1466-AX1kB0o.jpg', 'videos/1466-AX1kB0o.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2802', 'twisted-leg-raise', 'Twisted Leg レイズ', 'Twisted Leg Raise', 'Twisted Leg レイズは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Twisted Leg Raise is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/2802-C0eCeEt.jpg', 'videos/2802-C0eCeEt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2801', 'twisted-leg-raise-female', 'Twisted Leg レイズ (female)', 'Twisted Leg Raise (female)', 'Twisted Leg レイズ (female)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Twisted Leg Raise (female) is an effective exercise targeting the obliques using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/2801-yT9tk17.jpg', 'videos/2801-yT9tk17.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3231', 'two-toe-touch-male', 'Two Toe Touch (male)', 'Two Toe Touch (male)', 'Two Toe Touch (male)は、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Two Toe Touch (male) is an effective exercise targeting the hamstrings using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', 'images/3231-p195zsJ.jpg', 'videos/3231-p195zsJ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1365', 'upper-back-stretch', 'Upper バック ストレッチ', 'Upper Back Stretch', 'Upper バック ストレッチは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Upper Back Stretch is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."]', 'images/1365-GSDioYu.jpg', 'videos/1365-GSDioYu.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1366', 'upward-facing-dog', 'Upward Facing Dog', 'Upward Facing Dog', 'Upward Facing Dogは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Upward Facing Dog is an effective exercise targeting the shoulders using body weight.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1366-01qpYSe.jpg', 'videos/1366-01qpYSe.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3420', 'v-sit-on-floor', 'V-sit On Floor', 'V-sit On Floor', 'V-sit On Floorは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'V-sit On Floor is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3420-ZuXu4Eq.jpg', 'videos/3420-ZuXu4Eq.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0826', 'vertical-leg-raise-on-parallel-bars', 'Vertical Leg レイズ (on Parallel Bars)', 'Vertical Leg Raise (on Parallel Bars)', 'Vertical Leg レイズ (on Parallel Bars)は、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Vertical Leg Raise (on Parallel Bars) is an effective exercise targeting the hip flexors using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0826-ZNgOYQU.jpg', 'videos/0826-ZNgOYQU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2141', 'walk-elliptical-cross-trainer', 'Walk Elliptical Cross Trainer', 'Walk Elliptical Cross Trainer', 'Walk Elliptical Cross Trainerは、elliptical machineを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Walk Elliptical Cross Trainer is an effective exercise targeting the quadriceps using elliptical machine.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."]', 'images/2141-rjtuP6X.jpg', 'videos/2141-rjtuP6X.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3655', 'walking-high-knees-lunge', 'Walking High Knees ランジ', 'Walking High Knees Lunge', 'Walking High Knees ランジは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Walking High Knees Lunge is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."]', 'images/3655-J9zIWig.jpg', 'videos/3655-J9zIWig.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1460', 'walking-lunge', 'Walking ランジ', 'Walking Lunge', 'Walking ランジは、自重を使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Walking Lunge is an effective exercise targeting the quadriceps using body weight.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."]', 'images/1460-IZVHb27.jpg', 'videos/1460-IZVHb27.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3666', 'walking-on-incline-treadmill', 'Walking On インクライン Treadmill', 'Walking On Incline Treadmill', 'Walking On インクライン Treadmillは、レバレッジマシンを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Walking On Incline Treadmill is an effective exercise targeting the quadriceps using leverage machine.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."]', 'images/3666-rjiM4L3.jpg', 'videos/3666-rjiM4L3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2311', 'walking-on-stepmill', 'Walking On Stepmill', 'Walking On Stepmill', 'Walking On Stepmillは、stepmill machineを使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Walking On Stepmill is an effective exercise targeting the quadriceps using stepmill machine.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."]', 'images/2311-j9Q5crt.jpg', 'videos/2311-j9Q5crt.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0830', 'weighted-bench-dip', '加重 ベンチ ディップス', 'Weighted Bench Dip', '加重 ベンチ ディップスは、weightedを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Bench Dip is an effective exercise targeting the chest using weighted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/0830-MU9HnE7.jpg', 'videos/0830-MU9HnE7.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2987', 'weighted-close-grip-chin-up-on-dip-cage', '加重 Close Grip チンアップ On ディップス Cage', 'Weighted Close Grip Chin-up On Dip Cage', '加重 Close Grip チンアップ On ディップス Cageは、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted Close Grip Chin-up On Dip Cage is an effective exercise targeting the biceps using weighted.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', 'images/2987-Gk1r408.jpg', 'videos/2987-Gk1r408.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3643', 'weighted-cossack-squats-male', '加重 Cossack Squats (male)', 'Weighted Cossack Squats (male)', '加重 Cossack Squats (male)は、weightedを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Weighted Cossack Squats (male) is an effective exercise targeting the quadriceps using weighted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."]', 'images/3643-GWoKnIm.jpg', 'videos/3643-GWoKnIm.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0832', 'weighted-crunch', '加重 クランチ', 'Weighted Crunch', '加重 クランチは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Crunch is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0832-s8nrDXF.jpg', 'videos/0832-s8nrDXF.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3670', 'weighted-decline-sit-up', '加重 デクライン Sit-up', 'Weighted Decline Sit-up', '加重 デクライン Sit-upは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Decline Sit-up is an effective exercise targeting the hip flexors using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3670-EZeDVzO.jpg', 'videos/3670-EZeDVzO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0833', 'weighted-donkey-calf-raise', '加重 Donkey カーフ レイズ', 'Weighted Donkey Calf Raise', '加重 Donkey カーフ レイズは、weightedを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Weighted Donkey Calf Raise is an effective exercise targeting the hamstrings using weighted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0833-LmaFNZS.jpg', 'videos/0833-LmaFNZS.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1310', 'weighted-drop-push-up', '加重 Drop Push Up', 'Weighted Drop Push Up', '加重 Drop Push Upは、weightedを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Weighted Drop Push Up is an effective exercise targeting the triceps using weighted.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]', 'images/1310-PSlvNMs.jpg', 'videos/1310-PSlvNMs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2135', 'weighted-front-plank', '加重 フロント プランク', 'Weighted Front Plank', '加重 フロント プランクは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Front Plank is an effective exercise targeting the shoulders using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/2135-VBAWRPG.jpg', 'videos/2135-VBAWRPG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0834', 'weighted-front-raise', '加重 フロント レイズ', 'Weighted Front Raise', '加重 フロント レイズは、weightedを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Weighted Front Raise is an effective exercise targeting the biceps using weighted.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0834-e4aFmFY.jpg', 'videos/0834-e4aFmFY.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0866', 'weighted-hanging-leg-hip-raise', '加重 Hanging Leg-ヒップ レイズ', 'Weighted Hanging Leg-hip Raise', '加重 Hanging Leg-ヒップ レイズは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Hanging Leg-hip Raise is an effective exercise targeting the hip flexors using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0866-QOA0FD0.jpg', 'videos/0866-QOA0FD0.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0835', 'weighted-hyperextension-on-stability-ball', '加重 Hyperextension (on Stability Ball)', 'Weighted Hyperextension (on Stability Ball)', '加重 Hyperextension (on Stability Ball)は、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted Hyperextension (on Stability Ball) is an effective exercise targeting the glutes using weighted.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0835-8urJS9b.jpg', 'videos/0835-8urJS9b.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3641', 'weighted-kneeling-step-with-swing', '加重 ニーリング Step With Swing', 'Weighted Kneeling Step With Swing', '加重 ニーリング Step With Swingは、weightedを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Weighted Kneeling Step With Swing is an effective exercise targeting the triceps using weighted.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."]', 'images/3641-7uFJuXp.jpg', 'videos/3641-7uFJuXp.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3644', 'weighted-lunge-with-swing', '加重 ランジ With Swing', 'Weighted Lunge With Swing', '加重 ランジ With Swingは、weightedを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Weighted Lunge With Swing is an effective exercise targeting the quadriceps using weighted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."]', 'images/3644-5WiFcYk.jpg', 'videos/3644-5WiFcYk.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3286', 'weighted-muscle-up', '加重 Muscle Up', 'Weighted Muscle Up', '加重 Muscle Upは、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted Muscle Up is an effective exercise targeting the biceps using weighted.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', 'images/3286-JsOV1SU.jpg', 'videos/3286-JsOV1SU.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3312', 'weighted-muscle-up-on-bar', '加重 Muscle Up (on Bar)', 'Weighted Muscle Up (on Bar)', '加重 Muscle Up (on Bar)は、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted Muscle Up (on Bar) is an effective exercise targeting the biceps using weighted.', 'mg-back', 'Beginner', 'compound', 'push', 'upper', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/3312-MCkqdKE.jpg', 'videos/3312-MCkqdKE.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3290', 'weighted-one-hand-pull-up', '加重 One Hand Pull Up', 'Weighted One Hand Pull Up', '加重 One Hand Pull Upは、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted One Hand Pull Up is an effective exercise targeting the biceps using weighted.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', 'images/3290-fXfqg1E.jpg', 'videos/3290-fXfqg1E.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0840', 'weighted-overhead-crunch-on-stability-ball', '加重 オーバーヘッド クランチ (on Stability Ball)', 'Weighted Overhead Crunch (on Stability Ball)', '加重 オーバーヘッド クランチ (on Stability Ball)は、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Overhead Crunch (on Stability Ball) is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0840-xmM75XG.jpg', 'videos/0840-xmM75XG.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0841', 'weighted-pull-up', '加重 プルアップ', 'Weighted Pull-up', '加重 プルアップは、weightedを使用した背中をターゲットとする効果的なトレーニング種目です。', 'Weighted Pull-up is an effective exercise targeting the biceps using weighted.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0841-HMzLjXx.jpg', 'videos/0841-HMzLjXx.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0844', 'weighted-round-arm', '加重 Round Arm', 'Weighted Round Arm', '加重 Round Armは、weightedを使用した肩をターゲットとする効果的なトレーニング種目です。', 'Weighted Round Arm is an effective exercise targeting the triceps using weighted.', 'mg-shoulders', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0844-VLYXo8S.jpg', 'videos/0844-VLYXo8S.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0846', 'weighted-russian-twist', '加重 Russian ツイスト', 'Weighted Russian Twist', '加重 Russian ツイストは、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Russian Twist is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."]', 'images/0846-fZFZ704.jpg', 'videos/0846-fZFZ704.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0845', 'weighted-russian-twist-legs-up', '加重 Russian ツイスト (legs Up)', 'Weighted Russian Twist (legs Up)', '加重 Russian ツイスト (legs Up)は、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Russian Twist (legs Up) is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."]', 'images/0845-WU9BLIs.jpg', 'videos/0845-WU9BLIs.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2371', 'weighted-russian-twist-v-2', '加重 Russian ツイスト V. 2', 'Weighted Russian Twist V. 2', '加重 Russian ツイスト V. 2は、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Russian Twist V. 2 is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', 'images/2371-YIUAtYf.jpg', 'videos/2371-YIUAtYf.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0847', 'weighted-seated-bicep-curl-on-stability-ball', '加重 シーテッド Bicep カール (on Stability Ball)', 'Weighted Seated Bicep Curl (on Stability Ball)', '加重 シーテッド Bicep カール (on Stability Ball)は、メディシンボールを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Seated Bicep Curl (on Stability Ball) is an effective exercise targeting the forearms using medicine ball.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0847-b4b6afT.jpg', 'videos/0847-b4b6afT.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0849', 'weighted-seated-twist-on-stability-ball', '加重 シーテッド ツイスト (on Stability Ball)', 'Weighted Seated Twist (on Stability Ball)', '加重 シーテッド ツイスト (on Stability Ball)は、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Seated Twist (on Stability Ball) is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', 'images/0849-s34Y4LR.jpg', 'videos/0849-s34Y4LR.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0850', 'weighted-side-bend-on-stability-ball', '加重 Side Bend (on Stability Ball)', 'Weighted Side Bend (on Stability Ball)', '加重 Side Bend (on Stability Ball)は、weightedを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Weighted Side Bend (on Stability Ball) is an effective exercise targeting the obliques using weighted.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', 'images/0850-6bOA1Oi.jpg', 'videos/0850-6bOA1Oi.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0851', 'weighted-sissy-squat', '加重 Sissy スクワット', 'Weighted Sissy Squat', '加重 Sissy スクワットは、weightedを使用した脚をターゲットとする効果的なトレーニング種目です。', 'Weighted Sissy Squat is an effective exercise targeting the glutes using weighted.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', 'images/0851-0lQnxMZ.jpg', 'videos/0851-0lQnxMZ.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0852', 'weighted-squat', '加重 スクワット', 'Weighted Squat', '加重 スクワットは、weightedを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Weighted Squat is an effective exercise targeting the quadriceps using weighted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', 'images/0852-JZuApnB.jpg', 'videos/0852-JZuApnB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0853', 'weighted-standing-curl', '加重 スタンディング カール', 'Weighted Standing Curl', '加重 スタンディング カールは、weightedを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Standing Curl is an effective exercise targeting the forearms using weighted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0853-M5Y7GPg.jpg', 'videos/0853-M5Y7GPg.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0854', 'weighted-standing-hand-squeeze', '加重 スタンディング Hand Squeeze', 'Weighted Standing Hand Squeeze', '加重 スタンディング Hand Squeezeは、weightedを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Standing Hand Squeeze is an effective exercise targeting the biceps using weighted.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."]', 'images/0854-bjqbauy.jpg', 'videos/0854-bjqbauy.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3313', 'weighted-straight-bar-dip', '加重 Straight Bar ディップス', 'Weighted Straight Bar Dip', '加重 Straight Bar ディップスは、weightedを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Weighted Straight Bar Dip is an effective exercise targeting the triceps using weighted.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/3313-Ff18ItA.jpg', 'videos/3313-Ff18ItA.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3642', 'weighted-stretch-lunge', '加重 ストレッチ ランジ', 'Weighted Stretch Lunge', '加重 ストレッチ ランジは、weightedを使用したお尻をターゲットとする効果的なトレーニング種目です。', 'Weighted Stretch Lunge is an effective exercise targeting the quadriceps using weighted.', 'mg-glutes', 'Beginner', 'compound', 'push', 'lower', '["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', 'images/3642-13VW2VO.jpg', 'videos/3642-13VW2VO.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0856', 'weighted-svend-press', '加重 Svend プレス', 'Weighted Svend Press', '加重 Svend プレスは、weightedを使用した胸をターゲットとする効果的なトレーニング種目です。', 'Weighted Svend Press is an effective exercise targeting the shoulders using weighted.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."]', 'images/0856-I1OBLnn.jpg', 'videos/0856-I1OBLnn.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1754', 'weighted-three-bench-dips', '加重 Three ベンチ ディップス', 'Weighted Three Bench Dips', '加重 Three ベンチ ディップスは、weightedを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Three Bench Dips is an effective exercise targeting the chest using weighted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', 'images/1754-gtO1ErP.jpg', 'videos/1754-gtO1ErP.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1755', 'weighted-tricep-dips', '加重 Tricep ディップス', 'Weighted Tricep Dips', '加重 Tricep ディップスは、weightedを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Tricep Dips is an effective exercise targeting the chest using weighted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/1755-bZq4bwK.jpg', 'videos/1755-bZq4bwK.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1767', 'weighted-triceps-dip-on-high-parallel-bars', '加重 トライセップス ディップス On High Parallel Bars', 'Weighted Triceps Dip On High Parallel Bars', '加重 トライセップス ディップス On High Parallel Barsは、weightedを使用した腕をターゲットとする効果的なトレーニング種目です。', 'Weighted Triceps Dip On High Parallel Bars is an effective exercise targeting the chest using weighted.', 'mg-arms', 'Beginner', 'compound', 'push', 'upper', '["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1767-K1vlode.jpg', 'videos/1767-K1vlode.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0857', 'wheel-rollerout', 'ホイール Rollerout', 'Wheel Rollerout', 'ホイール Rolleroutは、ホイールローラーを使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Wheel Rollerout is an effective exercise targeting the lower back using wheel roller.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."]', 'images/0857-NAgVB3t.jpg', 'videos/0857-NAgVB3t.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('3637', 'wheel-run', 'ホイール Run', 'Wheel Run', 'ホイール Runは、自重を使用した有酸素をターゲットとする効果的なトレーニング種目です。', 'Wheel Run is an effective exercise targeting the quadriceps using body weight.', 'mg-cardio', 'Beginner', 'compound', 'push', 'cardio', '["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."]', 'images/3637-km2Ljzj.jpg', 'videos/3637-km2Ljzj.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1429', 'wide-grip-pull-up', 'Wide Grip プルアップ', 'Wide Grip Pull-up', 'Wide Grip プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Wide Grip Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', 'images/1429-Qqi7bko.jpg', 'videos/1429-Qqi7bko.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1367', 'wide-grip-rear-pull-up', 'Wide Grip リア プルアップ', 'Wide Grip Rear Pull-up', 'Wide Grip リア プルアップは、自重を使用した背中をターゲットとする効果的なトレーニング種目です。', 'Wide Grip Rear Pull-up is an effective exercise targeting the biceps using body weight.', 'mg-back', 'Beginner', 'compound', 'pull', 'upper', '["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/1367-OYFhXVD.jpg', 'videos/1367-OYFhXVD.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1311', 'wide-hand-push-up', 'Wide Hand Push Up', 'Wide Hand Push Up', 'Wide Hand Push Upは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Wide Hand Push Up is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', 'images/1311-JmMVpR3.jpg', 'videos/1311-JmMVpR3.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('2363', 'wide-grip-chest-dip-on-high-parallel-bars', 'ワイドグリップ チェスト ディップス On High Parallel Bars', 'Wide-grip Chest Dip On High Parallel Bars', 'ワイドグリップ チェスト ディップス On High Parallel Barsは、自重を使用した胸をターゲットとする効果的なトレーニング種目です。', 'Wide-grip Chest Dip On High Parallel Bars is an effective exercise targeting the triceps using body weight.', 'mg-chest', 'Beginner', 'compound', 'push', 'upper', '["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', 'images/2363-O2K9Vb5.jpg', 'videos/2363-O2K9Vb5.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0858', 'wind-sprints', 'Wind Sprints', 'Wind Sprints', 'Wind Sprintsは、自重を使用した腹筋をターゲットとする効果的なトレーニング種目です。', 'Wind Sprints is an effective exercise targeting the quadriceps using body weight.', 'mg-core', 'Beginner', 'compound', 'push', 'core', '["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."]', 'images/0858-Qoujh3Q.jpg', 'videos/0858-Qoujh3Q.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1604', 'world-greatest-stretch', 'World Greatest ストレッチ', 'World Greatest Stretch', 'World Greatest ストレッチは、自重を使用した脚をターゲットとする効果的なトレーニング種目です。', 'World Greatest Stretch is an effective exercise targeting the glutes using body weight.', 'mg-legs', 'Beginner', 'compound', 'push', 'lower', '["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."]', 'images/1604-DFGXwZr.jpg', 'videos/1604-DFGXwZr.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('1428', 'wrist-circles', 'リスト Circles', 'Wrist Circles', 'リスト Circlesは、自重を使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Wrist Circles is an effective exercise targeting the hands using body weight.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."]', 'images/1428-2zNKRUB.jpg', 'videos/1428-2zNKRUB.gif', FALSE, 9999, TRUE);
INSERT INTO exercises (id, slug, name_ja, name_en, description_ja, description_en, muscle_group_id, difficulty, mechanics, force, body_region, instructions, image, gif_url, is_default, sort_order, is_system) VALUES ('0859', 'wrist-rollerer', 'リスト Rollerer', 'Wrist Rollerer', 'リスト Rollererは、weightedを使用した前腕をターゲットとする効果的なトレーニング種目です。', 'Wrist Rollerer is an effective exercise targeting the biceps using weighted.', 'mg-forearms', 'Beginner', 'compound', 'push', 'upper', '["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."]', 'images/0859-bd5b860.jpg', 'videos/0859-bd5b860.gif', FALSE, 9999, TRUE);
